-- 5.3: the Route page guides a questing character: where to do the unfinished quests, nearest first, then hand in
do
  local N, U = newbie.QB, newbie.QB.UI
  local D = N.Data
  local e1 = N.state.logOrder[1]
  local saveSpot = D.SPOT[e1.id]
  D.SPOT[e1.id] = "k,1,1429,520,500,10,c"
  e1.complete = false
  local legs = U.ObjectiveLegs(5)
  assert(#legs >= 1 and legs[1].quests[1].id == e1.id and legs[1].mins >= 0 and legs[1].yards >= 0, "the nearest unfinished quest's place comes first")
  U:ShowTab(3); U:Refresh()
  local v3n = U.views[3]
  -- (5.4.4: questing, the page opens on the planned route, the one the arrow follows; Ready now is a click away)
  assert(N.Target.Mode() == "plan" and not v3n.modePlan:IsEnabled() and v3n.modeNow:GetText() == "Ready now", "questing: the page opens on the plan")
  v3n.modeNow.__scripts.OnClick(v3n.modeNow)
  assert(N:Settings().routeQuest == "now" and N.Target.Mode() == "now" and N.Target.Route() == (#N.routeNow.legs > 0 and N.routeNow or N.routePlan),
    "Ready now: the route on screen is what is ready")
  local first
  for _, l in ipairs(v3n.legs.items) do if l:IsShown() and not first then first = l end end
  assert(first and first.divider:IsShown() and first.divider:GetText() == "Do now" and first.name:GetText() == legs[1].name, "the page opens with Do now")
  assert(first.pin.stop and first.pin.stop.m == 1429, "with a waypoint on the place")
  v3n.modePlan.__scripts.OnClick(v3n.modePlan)
  assert(N:Settings().routeQuest == "plan" and N.Target.Route() == N.routePlan, "and back to the plan")
  D.SPOT[e1.id] = saveSpot
end

-- 3.6.2: who drops what (Loot.lua): a dwarf hunter looting in Elwynn and in the City of Dalaran on the Forever
-- client. Each creature or chest looted is noted by id with the item ids in its window, the map or the dungeon with
-- its difficulty, and the boss fight it ended; never a name, never a player; under the same Settings box as the
-- item notes, and gone with them when it is unticked
----------------------------------------------------------------------------
local torvald = newClient({
  name = "Torvald", level = 29, cap = 60, faction = "Alliance", className = "Hunter", class = "HUNTER", classID = 3, race = "Dwarf",
  log = {}, done = {}, group = false, guild = false, world = { 0, -9450, 60 }, map = 1429, bind = "Goldshire", riding = false, xp = 300,
  bagSlots = { { 2589, 3 } }, gear = { [16] = 2504 }, book = { { spellID = 75, itemType = 1 } },
})
login(torvald)
do
  local c, Q2 = torvald, torvald.QB
  local Lo, G = Q2.Loot, Q2.Game
  local DB = c.env.QuestBankDB
  local f = Lo.frame
  local function open(isFromItem) f.__scripts.OnEvent(f, "LOOT_OPENED", false, isFromItem or false) end
  local function ev(event, ...) f.__scripts.OnEvent(f, event, ...) end
  local function loot() return DB.disc.loot or {} end
  local function diag() return DB.diag and DB.diag.loot or {} end
  local function src(guid) return { { guid, 1 } } end
  local errs0 = #(DB.errors or {})
  assert(Lo.On() and G.On() and f.__scripts.OnEvent, "the Forever client with the box ticked: the loot notes are on")
  assert(Lo.LOOT_SOURCES == 400 and Lo.LOOT_ITEMS == 40 and Lo.AGAIN == 120 and Lo.KILL_WINDOW == 120, "the caps")
  local K = Q2.Discover.Key
  assert(K("Creature-0-4455-0-12-197-0000A1B2C3") == "c197" and K("GameObject-0-4455-0-12-2843-0000A1B2C3") == "o2843"
    and K("Vehicle-0-4455-0-12-1234-0000A1B2C3") == "c1234" and K("Player-1234-0000ABCD") == nil
    and K("Pet-0-4455-0-12-197-0000A1B2C3") == nil and K(SECRET.str()) == nil and K(nil) == nil,
    "a GUID's key: creatures and vehicles c, game objects o, nothing for players, pets and hidden values")

  -- in the world: a kobold's corpse with linen, some copper and a grey
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2C3") }, { id = 0, kind = 2 }, { id = 2590, q = 0, src = src("Creature-0-4455-0-12-197-0000A1B2C3") } }
  open()
  local r = loot().c197
  assert(r and r.m == 1429 and r.n == 1 and r.b == 70170 and r.i[2589] == 1 and r.i[2590] == nil and countOf(r.i) == 1
    and r.im == nil and r.d == nil and r.e == nil and r.ex == nil, "a corpse in the world: the map, looted once, the build, the item; no coin, no grey")
  assert(diag().w == 1 and diag().s == 1 and not diag().h and not diag().f, "diag: one window, one with a source")
  assert(DB.disc.lootN == 1 and DB.disc.lootAt.c197 == 1, "the touch counter")
  -- the same corpse opened again (the window was closed with an item left): items added, not looted again; another
  -- kobold: looted again; a grey quest item is kept
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2C3") }, { id = 2592, src = src("Creature-0-4455-0-12-197-0000A1B2C3") } }
  open()
  r = loot().c197
  assert(r.n == 1 and r.i[2589] == 1 and r.i[2592] == 1, "the same corpse again: a new item, not another time looted")
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2C4") }, { id = 2591, q = 0, quest = true, src = src("Creature-0-4455-0-12-197-0000A1B2C4") } }
  open()
  r = loot().c197
  assert(r.n == 2 and r.i[2589] == 2 and r.i[2591] == 1, "another kobold: looted twice, the linen seen in two windows, a grey quest item kept")
  c.loot = { { id = 2593, q = 0, questID = 7, src = src("Creature-0-4455-0-12-197-0000A1B2C4") } }
  open()
  assert(loot().c197.i[2593] == 1 and loot().c197.n == 2, "a grey with a quest id is a quest item too")
  tick(c, 121)
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2C4") } }
  open()
  assert(loot().c197.n == 3 and loot().c197.i[2589] == 3, "the same GUID past two minutes: looted again, as far as the notes can tell")

  -- the City of Dalaran: the Shade of the Archmage, whose kill event names its creature
  c.env.IsInInstance = function() return true, "party" end
  c.instance = { "City of Dalaran", 1, 2959 }
  ev("ENCOUNTER_START", 3303, "Shade of the Archmage", 1, 5)
  ev("ENCOUNTER_END", 3303, "Shade of the Archmage", 1, 5, 1, { { creatureID = 246020, creatureName = "Shade of the Archmage", remainingHealthPercent = 0 } })
  c.loot = { { id = 273031, src = src("Creature-0-4455-2959-12-246020-0000A1B2C9") }, { id = 273032, src = src("Creature-0-4455-2959-12-246020-0000A1B2C9") } }
  open()
  r = loot().c246020
  assert(r and r.im == 2959 and r.d == 1 and r.e == 3303 and r.ex == true and r.n == 1 and r.b == 70170 and r.i[273031] == 1 and r.i[273032] == 1 and r.m == nil,
    "a boss in Dalaran: the instance map and difficulty, the fight by its creature list, the items")
  assert(diag().eu == 1 and not diag().ee, "diag: the kill named its creatures")
  -- trash looted after it is not the boss: the list named 246020 only
  c.loot = { { id = 273033, src = src("Creature-0-4455-2959-12-246021-0000A1B2CA") } }
  open()
  assert(loot().c246021 and loot().c246021.e == nil and loot().c246021.im == 2959, "a trash creature after the kill: no fight")
  -- the list's creature id under another field name, as a string: still the fight's creature; the field names are noted
  ev("ENCOUNTER_START", 3298, "Arcane Anomaly", 1, 5)
  ev("ENCOUNTER_END", 3298, "Arcane Anomaly", 1, 5, 1, { { npcID = "245999", remainingHealthPercent = 0 } })
  c.loot = { { id = 273034, src = src("Creature-0-4455-2959-12-245999-0000A1B2D0") } }
  open()
  assert(loot().c245999 and loot().c245999.e == 3298 and loot().c245999.ex == true, "a creature id given as npcID text still links the fight by the game's list")
  assert(diag().uk == "npcID,remainingHealthPercent", "diag: the list's field names are noted, nothing else: " .. tostring(diag().uk))
  -- a kill that names no creatures: the first corpse looted within two minutes is taken for it, as a guess
  ev("ENCOUNTER_END", 3311, "Atrexis the Grave Knight", 1, 5, 1, nil)
  assert(diag().ee == 1, "diag: a kill without the list")
  tick(c, 30)
  c.loot = { { id = 273040, src = src("Creature-0-4455-2959-12-246030-0000A1B2CB") } }
  open()
  tick(c, 30)
  c.loot = { { id = 273041, src = src("Creature-0-4455-2959-12-246031-0000A1B2CC") } }
  open()
  assert(loot().c246030.e == 3311 and loot().c246030.ex == nil, "the first corpse after the kill: the fight, as a guess (no ex)")
  assert(loot().c246031.e == nil, "the second: nothing")
  tick(c, 121)
  ev("BOSS_KILL", 3312, "Mana Wraith")
  tick(c, 125)
  c.loot = { { id = 273042, src = src("Creature-0-4455-2959-12-246032-0000A1B2CD") } }
  open()
  assert(loot().c246032.e == nil, "a corpse more than two minutes after a kill: nothing")
  -- the game's own link stands over a guess
  ev("BOSS_KILL", 3310, "Lyn the Ignored")
  c.loot = { { id = 273031, src = src("Creature-0-4455-2959-12-246020-0000A1B2CE") } }
  open()
  assert(loot().c246020.e == 3303 and loot().c246020.ex == true and loot().c246020.n == 2 and loot().c246020.i[273031] == 2,
    "a creature the game once named for a fight keeps that fight")
  -- a wipe links nothing; a loading screen forgets the kill; so does a new fight starting
  ev("PLAYER_ENTERING_WORLD", false, true)
  ev("ENCOUNTER_END", 3298, "Arcane Anomaly", 1, 5, 0, nil)
  c.loot = { { id = 273043, src = src("Creature-0-4455-2959-12-246033-0000A1B2CF") } }
  open()
  assert(loot().c246033.e == nil, "a wipe: nothing")
  ev("ENCOUNTER_END", 3299, "Fel Ancient", 1, 5, 1, nil)
  ev("PLAYER_ENTERING_WORLD", false, true)
  c.loot = { { id = 273044, src = src("Creature-0-4455-2959-12-246034-0000A1B2D0") } }
  open()
  assert(loot().c246034.e == nil, "after a loading screen: the kill is forgotten")
  ev("ENCOUNTER_END", 3300, "Mana Devourer", 1, 5, 1, nil)
  ev("ENCOUNTER_START", 3301, "Mana Elemental", 1, 5)
  c.loot = { { id = 273045, src = src("Creature-0-4455-2959-12-246035-0000A1B2D1") } }
  open()
  assert(loot().c246035.e == nil, "a new fight started: the last kill's guess is off")

  -- hidden values: nothing noted, no error
  local n0 = countOf(loot())
  local h0 = diag().h or 0
  c.loot = { { id = 273050, src = src(SECRET.str()) } }
  open()
  assert(countOf(loot()) == n0 and diag().h == h0 + 1, "a hidden source: nothing noted, counted as hidden")
  ev("ENCOUNTER_END", SECRET.num(), "Unstable Sentinel", 1, 5, 1, nil)
  c.loot = { { id = 273051, src = src("Creature-0-4455-2959-12-246040-0000A1B2D2") } }
  open()
  assert(loot().c246040 and loot().c246040.e == nil, "a hidden encounter id: no kill to link")
  local numItems = c.env.GetNumLootItems
  c.env.GetNumLootItems = function() return SECRET.num() end
  c.loot = { { id = 273052, src = src("Creature-0-4455-2959-12-246041-0000A1B2D3") } }
  open()
  c.env.GetNumLootItems = numItems
  assert(not loot().c246041, "a hidden slot count: nothing")
  -- a hidden place: the items count, the place is unknown; what was noted before stands only where it still can (a
  -- map from outdoors is wrong for a corpse looted inside, a dungeon is wrong for one looted outdoors)
  c.env.IsInInstance = function() return false, "none" end
  c.loot = { { id = 273053, src = src("Creature-0-4455-0-12-246042-0000A1B2D4") } }
  open()
  assert(loot().c246042.m == 1429, "a creature first met outdoors: the map")
  c.env.IsInInstance = function() return true, "party" end
  c.instance[3] = SECRET.num()
  c.loot = { { id = 273053, src = src("Creature-0-4455-2959-12-246042-0000A1B2D8") } }
  open()
  c.instance[3] = 2959
  r = loot().c246042
  assert(r and r.i[273053] == 2 and r.n == 2 and r.im == nil and r.d == nil and r.m == nil, "a hidden instance id: the items count, the place is unknown, the map from outdoors goes")
  c.instance[2] = SECRET.num()
  c.loot = { { id = 273053, src = src("Creature-0-4455-2959-12-246021-0000A1B2D9") } }
  open()
  c.instance[2] = 1
  r = loot().c246021
  assert(r.i[273053] == 1 and r.im == 2959 and r.d == 1, "a hidden difficulty: the dungeon noted before stands, it is the same side")
  c.env.IsInInstance = function() return false, "none" end
  local best = c.env.C_Map.GetBestMapForUnit
  c.env.C_Map.GetBestMapForUnit = function() return SECRET.num() end
  c.loot = { { id = 273053, src = src("Creature-0-4455-0-12-246021-0000A1B2DA") } }
  open()
  assert(loot().c246021.im == nil and loot().c246021.d == nil and loot().c246021.m == nil, "outdoors with the map hidden: the dungeon noted before goes")
  c.env.C_Map.GetBestMapForUnit = best
  c.env.IsInInstance = function() return SECRET.num(), SECRET.str() end
  c.loot = { { id = 273053, src = src("Creature-0-4455-0-12-246020-0000A1B2DB") } }
  open()
  assert(loot().c246020.im == 2959 and loot().c246020.d == 1 and loot().c246020.m == nil, "not even inside or out known: the place noted before stands")
  c.env.IsInInstance = function() return true, "party" end
  ev("ENCOUNTER_END", 3302, "Unstable Sentinel", 1, 5, 1, SECRET.str())
  c.loot = { { id = 273054, src = src("Creature-0-4455-2959-12-246043-0000A1B2D5") } }
  open()
  assert(loot().c246043.e == 3302 and loot().c246043.ex == nil, "a hidden creature list is no list: the first corpse is a guess")
  ev("ENCOUNTER_END", 3302, "Unstable Sentinel", 1, 5, 1, { SECRET.str(), { creatureID = SECRET.num(), creatureName = "x" } })
  c.loot = { { id = 273055, src = src("Creature-0-4455-2959-12-246044-0000A1B2D6") } }
  open()
  assert(loot().c246044.e == 3302 and loot().c246044.ex == nil, "a list whose every creature is hidden: the same")
  -- a hidden source beside a plain one: the plain one is noted, and the window counts as hidden too
  c.loot = { { id = 273056, src = { { SECRET.str(), 1 }, { "Creature-0-4455-2959-12-246045-0000A1B2D7", 1 } } } }
  open()
  assert(loot().c246045 and loot().c246045.i[273056] == 1 and diag().h == h0 + 2, "a window half hidden: what shows is noted")

  -- kinds: a chest is an o key, a vehicle a c key; a player's corpse is nobody (skipped, not hidden); a lockbox,
  -- fishing, coins only, no source: skipped whole
  c.env.IsInInstance = function() return false, "none" end
  c.loot = { { id = 2589, src = src("GameObject-0-4455-0-12-2843-0000A1B2E0") }, { id = 2592, src = src("Vehicle-0-4455-0-12-1234-0000A1B2E1") } }
  open()
  assert(loot().o2843 and loot().o2843.i[2589] == 1 and loot().o2843.m == 1429 and loot().o2843.im == nil and loot().c1234 and loot().c1234.i[2592] == 1,
    "a chest: o; a vehicle: c; outdoors again: the map")
  n0 = countOf(loot())
  local f0, hh = diag().f or 0, diag().h
  c.loot = { { id = 2589, src = src("Player-1234-0000ABCD") } }
  open()
  assert(countOf(loot()) == n0 and diag().f == f0 + 1 and diag().h == hh, "a player's corpse: nothing, and not a hidden source")
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2E2") } }
  open(true)
  assert(countOf(loot()) == n0 and loot().c197.n == 3 and diag().f == f0 + 2, "a window from an item (a lockbox): nothing")
  c.fishing = true
  open()
  c.fishing = nil
  assert(loot().c197.n == 3 and diag().f == f0 + 3, "fishing: nothing")
  c.loot = { { id = 0, kind = 2 } }
  open()
  assert(diag().f == f0 + 4, "coins only: nothing lootable")
  c.loot = { { id = 2589 } }
  c.lootSrc = {}
  open()
  c.lootSrc = nil
  assert(diag().f == f0 + 5 and countOf(loot()) == n0, "no source at all: nothing")
  local sourceInfo = c.env.GetLootSourceInfo
  c.env.GetLootSourceInfo = nil
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2E3") } }
  open()
  c.env.GetLootSourceInfo = sourceInfo
  assert(countOf(loot()) == n0 and loot().c197.n == 3 and diag().h == hh + 1, "a client without GetLootSourceInfo: nothing, counted as hidden")

  -- the caps: 400 sources, the ones touched longest ago going first; 40 items a source, the least-seen going, and a
  -- new one left out while every kept item was seen more than once
  c.loot = { { id = 273060 } }
  for k = 1, Lo.LOOT_SOURCES + 5 do
    c.lootSrc = src("Creature-0-4455-0-12-" .. (500000 + k) .. "-0000B" .. string.format("%07X", k))
    open()
  end
  c.lootSrc = nil
  assert(countOf(loot()) == Lo.LOOT_SOURCES and countOf(DB.disc.lootAt) == Lo.LOOT_SOURCES, "at most 400 sources, and as many touch marks")
  assert(not loot().c197 and not loot().o2843 and not loot().c246020 and not loot().c500005 and loot().c500006 and loot().c500405,
    "the ones touched longest ago went first")
  local function many(a, b, guid)
    local t = {}
    for id = a, b do t[#t + 1] = { id = id } end
    c.loot, c.lootSrc = t, src(guid)
    open()
    c.lootSrc = nil
  end
  many(273001, 273040, "Creature-0-4455-0-12-600000-0000C000001")
  many(273001, 273039, "Creature-0-4455-0-12-600000-0000C000002")
  r = loot().c600000
  assert(r and countOf(r.i) == 40 and r.i[273001] == 2 and r.i[273040] == 1 and r.n == 2, "40 items on one source")
  many(273041, 273041, "Creature-0-4455-0-12-600000-0000C000003")
  assert(countOf(r.i) == 40 and r.i[273040] == nil and r.i[273041] == 1, "a 41st: the one seen fewest times goes")
  many(273041, 273041, "Creature-0-4455-0-12-600000-0000C000004")
  many(273042, 273042, "Creature-0-4455-0-12-600000-0000C000005")
  assert(countOf(r.i) == 40 and r.i[273042] == nil and r.i[273041] == 2 and r.n == 5, "every kept item seen twice: a new one is left out")
  assert(countOf(loot()) == Lo.LOOT_SOURCES and not loot().c500006, "and the source cap held")

  -- no names anywhere: every value a number, a boolean or a table; every key a source ("c123", "o123"), an item id,
  -- or one of the record's own fields
  local FIELDS = { im = true, m = true, d = true, e = true, ex = true, n = true, b = true, i = true }
  local function clean(v, path)
    if type(v) == "table" then
      for k, x in pairs(v) do
        assert(type(k) == "number" or (type(k) == "string" and (k:match("^[co]%d+$") or FIELDS[k])), "an odd key at " .. path .. ": " .. tostring(k))
        clean(x, path .. "." .. tostring(k))
      end
    else
      assert(type(v) == "number" or type(v) == "boolean", "a " .. type(v) .. " at " .. path .. ": " .. tostring(v))
    end
  end
  clean(DB.disc.loot, "loot"); clean(DB.disc.lootAt, "lootAt")
  names(c, DB.disc.loot, { "Shade of the Archmage", "Dalaran", "Torvald" })
  assert(type(DB.disc.lootN) == "number", "the counter is a number")

  -- the switch: unticked, the notes go with the item notes; a window notes nothing; ticked, the next window does
  G.SetOn(false)
  assert(DB.disc.loot == nil and DB.disc.lootAt == nil and DB.disc.lootN == nil and DB.game == nil, "unticked: the loot notes go")
  c.loot = { { id = 2589, src = src("Creature-0-4455-0-12-197-0000A1B2F0") } }
  open()
  assert(DB.disc.loot == nil and not Lo.On(), "and nothing is noted while it is off")
  G.SetOn(true)
  open()
  assert(DB.disc.loot and DB.disc.loot.c197 and DB.disc.loot.c197.n == 1 and DB.disc.lootN == 1 and Lo.Count() == 1, "ticked again: the next window notes")
  c.env.SlashCmdList.QUESTBANK("discoveries")
  local said = c.chat[#c.chat]
  assert(said:find(", 1 drop source.", 1, true), "/qb discoveries counts them: " .. said)
  c.loot = { { id = 2592, src = src("Creature-0-4455-0-12-198-0000A1B2F1") }, { id = 2593, src = src("Creature-0-4455-0-12-198-0000A1B2F1") } }
  open()
  local ns, ni = Lo.Count()
  assert(ns == 2 and ni == 3, "Count: sources, and the items under them")
  -- the Settings page: the count, the tooltip, the layout
  Q2.UI:Open(5); Q2.UI:Refresh()
  local v5 = Q2.UI.views[5]
  assert(v5.discText:GetText():find(", 2 drop sources.", 1, true), "the Settings page counts drop sources: " .. v5.discText:GetText())
  lines = {}
  v5.noteGame.__scripts.OnEnter(v5.noteGame)
  assert(table.concat(lines, " "):find("chests", 1, true) and table.concat(lines, " "):find("by id", 1, true), "the tooltip says what is noted: " .. table.concat(lines, " | "))
  v5.noteGame.__scripts.OnLeave(v5.noteGame)
  for _, pr in ipairs(checkLayout(Q2.UI.frame, "settings with the loot notes")) do problems[#problems + 1] = pr end
  local sf = v5.scroll
  local _, hi = sf.bar:GetMinMaxValues()
  sf.bar:SetValue(hi); Q2.UI:Refresh()
  for _, pr in ipairs(checkLayout(Q2.UI.frame, "settings with the loot notes, scrolled")) do problems[#problems + 1] = pr end
  sf.bar:SetValue(0)
  Q2.UI.frame:Hide()
  c.env.SlashCmdList.QUESTBANK("discoveries")
  said = c.chat[#c.chat]
  assert(said:find(", 2 drop sources.", 1, true), "/qb discoveries, plural: " .. said)
  assert(#(DB.errors or {}) == errs0, "no error through all of it")
  local dg = diag()
  print(string.format("loot notes: %d sources, %d items; windows %d, with a source %d, hidden %d, skipped %d; kills with a list %d, without %d",
    ns, ni, dg.w, dg.s, dg.h, dg.f, dg.eu, dg.ee))
end

----------------------------------------------------------------------------
-- 3.6.2: tooltips without a hover (Game.lua with Loot.lua). The owner's City of Dalaran run left two boss drops in
-- the bags with no tooltip in the upload: only hovered items were read. Now every item a loot window shows, every
-- drop the game announces to the group, and every item worn or carried is read, two every half second, never in a
-- fight, by the same reader with the same guards and caps
----------------------------------------------------------------------------
do
  local c, Q2 = torvald, torvald.QB
  local G, Lo = Q2.Game, Q2.Loot
  local DB = c.env.QuestBankDB
  local lf = Lo.frame
  local function src(guid) return { { guid, 1 } } end
  local function open(isFromItem) lf.__scripts.OnEvent(lf, "LOOT_OPENED", true, isFromItem or false) end -- auto-loot: the window is never seen
  local function has(ids) local n = 0; for _, id in ipairs(ids) do if DB.game.items[id] then n = n + 1 end end; return n end
  local reads, asked = { n = 0 }, {}
  local realTip, realLoad = c.env.C_TooltipInfo.GetItemByID, c.env.C_Item.RequestLoadItemDataByID
  c.env.C_TooltipInfo.GetItemByID = function(id) reads[id] = (reads[id] or 0) + 1; reads.n = reads.n + 1; return realTip(id) end
  c.env.C_Item.RequestLoadItemDataByID = function(id) asked[id] = (asked[id] or 0) + 1; return realLoad(id) end
  tick(c, 60) -- the loot tests' windows left ids in the queue: read out
  local g = DB.game
  local errs0 = #(DB.errors or {})
  assert(G.PACE == 0.5 and G.BATCH == 2 and G.LOADS == 2 and G.TRIES == 3, "the pace: two tooltips every half second")
  c.env.IsInInstance = function() return true, "party" end
  c.instance = { "City of Dalaran", 1, 2959 }
  -- what is worn and carried now, read before the rest (a sweep by hand; the game's comes at login and when the bags change)
  assert(not g.items[2504], "the worn axe was never hovered")
  G.Sweep(); tick(c, 1)
  assert(g.items[2504] and g.items[2504].n == "Item 2504", "the sweep reads what is worn")

  -- the owner's two drops, auto-looted and never hovered: the loot recorder queues them, the reader reads them
  local boss = "Creature-0-4455-2959-12-246050-0000A1B300"
  g.items[273035], reads[273035] = nil, nil -- (the loot tests' window of forty read it; forgotten, so the drop is new again)
  c.loot = { { id = 273035, src = src(boss) }, { id = 273048, src = src(boss) } }
  open()
  assert(not g.items[273035] and not g.items[273048] and not reads[273035], "the window only queues: nothing is read inside the event")
  tick(c, 1)
  local it = g.items[273035]
  assert(it and g.items[273048] and it.n == "Item 273035" and it.el == "INVTYPE_CHEST" and it.b == "1.60.1.70170" and #it.x == 6,
    "both drops have a tooltip without a hover")
  assert(DB.disc.loot.c246050 and DB.disc.loot.c246050.i[273035] == 1 and DB.disc.loot.c246050.i[273048] == 1, "and the source is noted as before")
  -- a lockbox's contents: no source to note, the tooltips still read
  local ns0 = countOf(DB.disc.loot)
  local f0 = DB.diag.loot.f
  c.loot = { { id = 273071, src = src("Creature-0-4455-2959-12-246051-0000A1B301") } }
  open(true)
  assert(not g.items[273071], "a lockbox's window: only queued")
  tick(c, 1)
  assert(g.items[273071] and countOf(DB.disc.loot) == ns0 and not DB.disc.loot.c246051 and DB.diag.loot.f == f0 + 1,
    "a window from an item: its items are read, no source noted")
  -- a boss drop another player looted and this one won: the game announces it to the group
  lf.__scripts.OnEvent(lf, "ENCOUNTER_LOOT_RECEIVED", 3303, 273070, "|cffa335ee|Hitem:273070::::::::29:::::::|h[Item 273070]|h|r", 1, "Torvald", "HUNTER")
  assert(not g.items[273070], "announced: only queued")
  tick(c, 1)
  assert(g.items[273070], "a drop the kill event announces is read, whoever looted the corpse")
  lf.__scripts.OnEvent(lf, "ENCOUNTER_LOOT_RECEIVED", 3303, SECRET.num(), SECRET.str(), 1, SECRET.str(), "HUNTER")
  tick(c, 1)

  -- the bags: ten new items, read two every half second, across ticks, so a bag full of new items never reads in
  -- one frame; the sweep waits five seconds after the bags change
  local bagged = {}
  c.o.bagSlots = { { 2589, 3 } }
  for i = 1, 10 do bagged[i] = 273100 + i; c.o.bagSlots[#c.o.bagSlots + 1] = { 273100 + i, 1 } end
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 4)
  assert(has(bagged) == 0, "the bags are looked through five seconds after they change, not at once")
  tick(c, 1)
  assert(has(bagged) == 0, "the sweep only queues")
  tick(c, 0.5)
  assert(has(bagged) == 2, "half a second on: two read (" .. has(bagged) .. ")")
  tick(c, 0.5)
  assert(has(bagged) == 4, "another half second: four (" .. has(bagged) .. ")")
  tick(c, 1.5)
  assert(has(bagged) == 10, "and all ten after three seconds (" .. has(bagged) .. ")")
  for _, id in ipairs(bagged) do assert(reads[id] == 1, "each read once") end
  -- the bags change again: every tooltip is fresh, nothing is read
  local n0 = reads.n
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 6)
  assert(reads.n == n0, "a sweep with every tooltip fresh reads nothing")
  -- duplicates collapse: the same id hovered three times, looted and in the bags is read once
  c.o.bagSlots[#c.o.bagSlots + 1] = { 273120, 1 }
  hover(c, 273120); hover(c, 273120); hover(c, 273120)
  c.loot = { { id = 273120, src = src("Creature-0-4455-2959-12-246052-0000A1B302") } }
  open()
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 10)
  assert(g.items[273120] and reads[273120] == 1, "hovered, looted and bagged: read once (" .. tostring(reads[273120]) .. ")")
  -- six hours on, the sweep reads it again
  g.items[273120].at = g.items[273120].at - 7 * 3600
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 6)
  assert(reads[273120] == 2, "read again after six hours")

  -- the cap holds: a full table, five new items in the bags and the worn axe unread at this build; the oldest six go
  local full = {}
  for i = 1, G.MAX_ITEMS do full[400000 + i] = { b = "1.60.1.69000", at = 1000 + i, n = "Old", c = 4, x = {} } end
  g.items = full
  c.o.bagSlots = {}
  for i = 1, 5 do c.o.bagSlots[i] = { 273130 + i, 1 } end
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 8)
  assert(countOf(g.items) == G.MAX_ITEMS and g.items[273131] and g.items[273135] and g.items[2504] and not g.items[400001] and not g.items[400006]
    and g.items[400007], "at most 1000: the oldest six went for the six new (" .. countOf(g.items) .. ")")

  -- an item the client hasn't loaded (server-sent): asked of the server, nothing kept until it answers; a failed
  -- answer is left for a later sweep, and the asking stops after two in a session
  c.o.bagSlots = { { 273201, 1 }, { 273202, 1 } }
  c.unloaded[273201], c.unloaded[273202] = true, true
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 7)
  assert(not g.items[273201] and not g.items[273202] and asked[273201] == 1 and asked[273202] == 1, "not loaded: asked for, nothing kept")
  fire(c, "ITEM_DATA_LOAD_RESULT", 273201, false)
  tick(c, 2)
  assert(not g.items[273201] and asked[273201] == 1, "the server said no: nothing kept, not asked again at once")
  c.unloaded[273202] = nil
  fire(c, "ITEM_DATA_LOAD_RESULT", 273202, true)
  assert(not g.items[273202], "the answer only queues")
  tick(c, 1)
  assert(g.items[273202] and g.items[273202].n == "Item 273202" and #g.items[273202].x == 6, "loaded: read on the server's answer")
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  assert(asked[273201] == 2 and not g.items[273201], "the next sweep asks again")
  fire(c, "ITEM_DATA_LOAD_RESULT", 273201, false)
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  assert(asked[273201] == 2 and not g.items[273201], "twice a session, then left for the next")
  fire(c, "ITEM_DATA_LOAD_RESULT", SECRET.num(), true); fire(c, "ITEM_DATA_LOAD_RESULT", 273201, SECRET.bool())
  tick(c, 1)
  -- a hidden name: the same, asked twice at most, never kept
  c.o.bagSlots = { { 273203, 1 } }
  c.itemName[273203] = SECRET.str()
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  fire(c, "ITEM_DATA_LOAD_RESULT", 273203, true); tick(c, 1)
  fire(c, "ITEM_DATA_LOAD_RESULT", 273203, true); tick(c, 1)
  fire(c, "ITEM_DATA_LOAD_RESULT", 273203, true); tick(c, 1)
  assert(not g.items[273203] and asked[273203] == 2, "a hidden name: asked twice, never kept (" .. tostring(asked[273203]) .. ")")

  -- a tooltip the server hasn't filled in ("Retrieving item information"): read again three times, three seconds
  -- apart, then left; nothing half-read is kept. The next sweep reads it whole
  c.o.bagSlots = { { 273204, 1 } }
  c.tipLines[273204] = { { leftText = "Item 273204" }, { leftText = "Retrieving item information" } }
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 6)
  assert(reads[273204] == 1 and not g.items[273204], "half-read: not kept")
  tick(c, 20)
  assert(reads[273204] == 4 and not g.items[273204], "read again three times, then left (" .. tostring(reads[273204]) .. ")")
  hover(c, 273204); tick(c, 10)
  assert(reads[273204] == 5 and not g.items[273204], "a hover reads once more, still not kept")
  c.tipLines[273204] = nil -- the server's text arrives
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 6)
  assert(g.items[273204] and g.items[273204].x[1] == "Binds when picked up" and reads[273204] == 6, "whole at last: kept")

  -- the body missing or hidden while the client has the name: GetItemByID returning nothing (MayReturnNothing in
  -- the client's documentation), an empty list, the list hidden, a line hidden, a line's left or right text hidden.
  -- None is kept half-read or lineless (a record with lines missing would stand for the item's stats in the
  -- Database): read again three times, then left; a later sweep reads it once more; whole at last, it is kept
  local gone = {}
  c.env.C_TooltipInfo.GetItemByID = function(id)
    reads[id] = (reads[id] or 0) + 1; reads.n = reads.n + 1
    if gone[id] then return nil end
    return realTip(id)
  end
  local bodies = { 273205, 273206, 273207, 273208, 273209, 273210 }
  gone[273205] = true
  c.tipLines[273206] = {}
  c.tipLines[273207] = SECRET.str()
  c.tipLines[273208] = { { leftText = "Item 273208" }, SECRET.str(), { leftText = "+5 Stamina" } }
  c.tipLines[273209] = { { leftText = "Item 273209" }, { leftText = SECRET.str() }, { leftText = "+5 Stamina" } }
  c.tipLines[273210] = { { leftText = "Item 273210" }, { leftText = "Chest", rightText = SECRET.str() }, { leftText = "+5 Stamina" } }
  c.o.bagSlots = {}
  for i, id in ipairs(bodies) do c.o.bagSlots[i] = { id, 1 } end
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  for _, id in ipairs(bodies) do assert(reads[id] == 1 and not g.items[id], "body missing or hidden: read, not kept (" .. id .. ")") end
  tick(c, 20)
  for _, id in ipairs(bodies) do assert(reads[id] == 4 and not g.items[id], "read again three times, then left (" .. id .. ": " .. tostring(reads[id]) .. ")") end
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  for _, id in ipairs(bodies) do assert(reads[id] == 5 and not g.items[id], "a later sweep reads it once more, still not kept (" .. id .. ")") end
  gone[273205] = nil
  for _, id in ipairs(bodies) do c.tipLines[id] = nil end -- the client shows them whole
  fire(c, "BAG_UPDATE_DELAYED"); tick(c, 7)
  for _, id in ipairs(bodies) do
    assert(g.items[id] and #g.items[id].x == 6 and g.items[id].x[1] == "Binds when picked up" and reads[id] == 6, "whole at last: kept (" .. id .. ")")
  end
  assert(#(DB.errors or {}) == errs0, "no error from a missing or hidden body")

  -- a fight: nothing is read, nothing looked through, nothing asked of the server, until it ends
  c.o.bagSlots = { { 273301, 1 }, { 273302, 1 } }
  c.combat = true
  n0 = reads.n
  local a0 = countOf(asked)
  c.loot = { { id = 273303, src = src("Creature-0-4455-2959-12-246060-0000A1B310") } }
  open()
  hover(c, 273304)
  fire(c, "BAG_UPDATE_DELAYED")
  tick(c, 30)
  assert(reads.n == n0 and not g.items[273301] and not g.items[273303] and not g.items[273304] and countOf(asked) == a0, "in a fight: nothing read, nothing asked")
  assert(DB.disc.loot.c246060 and DB.disc.loot.c246060.i[273303] == 1, "(the loot source is noted as before)")
  c.combat = false
  fire(c, "PLAYER_REGEN_ENABLED")
  tick(c, 0.5)
  assert(g.items[273303] and g.items[273304], "the fight over: the queue goes on at once")
  tick(c, 10)
  assert(g.items[273301] and g.items[273302], "and the bags are looked through")
  -- the game holding addons back as in combat without InCombatLockdown (an encounter): the same wait
  c.env.Enum.AddOnRestrictionType = { Combat = 0, Encounter = 1 }
  local held = true
  c.env.C_RestrictedActions = { IsAddOnRestrictionActive = function(kind) return kind == 1 and held end }
  n0 = reads.n
  hover(c, 273305)
  tick(c, 30)
  assert(reads.n == n0 and not g.items[273305], "held back in an encounter: nothing read")
  held = false
  fire(c, "ADDON_RESTRICTION_STATE_CHANGED", 1, 0)
  tick(c, 0.5)
  assert(g.items[273305], "the encounter over: read")
  c.env.C_RestrictedActions, c.env.Enum.AddOnRestrictionType = nil, nil

  assert(#(DB.errors or {}) == errs0, "no error through all of it")
  names(c, g, { "Torvald", "Dalaran" })
  c.env.C_TooltipInfo.GetItemByID, c.env.C_Item.RequestLoadItemDataByID = realTip, realLoad
  local nAsked = 0
  for _ in pairs(asked) do nAsked = nAsked + 1 end
  print(string.format("tooltips without a hover: %d reads, %d records kept, %d items asked of the server", reads.n, countOf(g.items), nAsked))
end

----------------------------------------------------------------------------
-- 3.7.0: the event probe (Observe.lua). On the Forever client QuestBank counts, per unit event, whether the game
-- handed it readable values, secret values or nothing, in QuestBankDB.diag.ev, so the observer can be designed on
-- what this client really gives addons. Kinds only: never a name, never a player
----------------------------------------------------------------------------
do
  local c, Q2 = torvald, torvald.QB
  local Ob = Q2.Observe
  local DB = c.env.QuestBankDB
  assert(Ob and Ob.frame and Ob.On() and Ob.frame.__scripts.OnEvent, "the Forever client with the box ticked: the probe is on")
  assert(Ob.MAX_KEYS == 60, "the cap")
  local function ev() return DB.diag and DB.diag.ev or {} end
  Ob.Note("TEST_EVENT", { a = 1, b = "x" })
  local r = ev().TEST_EVENT
  assert(r and r.n == 1 and r.ok == 1 and r.sec == 0 and r.nl == 0 and r.s.a == "number" and r.s.b == "string", "a plain read: counted ok, kinds kept, values not")
  Ob.Note("TEST_EVENT", { a = SECRET.num(), b = "x" })
  r = ev().TEST_EVENT
  assert(r.n == 2 and r.ok == 1 and r.sec == 1 and r.s.a == "number", "a secret read: counted, the first sample stays")
  Ob.Note("TEST_EVENT2", { a = Ob.NIL, b = SECRET.str() })
  r = ev().TEST_EVENT2
  assert(r.n == 1 and r.ok == 0 and r.sec == 1 and r.nl == 1 and r.s.a == "nil" and r.s.b == "secret", "nil and secret both noted in the sample")
  -- the unit cast events: a target casting with everything readable, then a nameplate whose GUID is hidden
  local f = Ob.frame
  local function fire(event, ...) f.__scripts.OnEvent(f, event, ...) end
  local unitLevel, guidOf = c.env.UnitLevel, c.env.UnitGUID
  c.env.UnitLevel = function(u) if u == "target" or u:find("^nameplate") then return 31 end return unitLevel(u) end
  c.env.UnitClassification = function() return "elite" end
  c.env.UnitHealth = function() return 1200 end
  c.env.UnitHealthMax = function() return 4000 end
  c.env.UnitCastingInfo = function() return "Arcane Bolt", "Arcane Bolt", "", 1000, 2500, false, "cast-1", false, 1234 end
  c.env.UnitChannelInfo = function() return nil end
  c.env.UnitGUID = function(u) if u == "target" then return "Creature-0-4455-0-12-245999-0000A1B2C3" end if u:find("^nameplate") then return SECRET.str() end return guidOf(u) end
  fire("UNIT_SPELLCAST_START", "target", "cast-1", 1234)
  r = ev().UNIT_SPELLCAST_START
  assert(r and r.n == 1 and r.ok == 1 and r.s.guid == "string" and r.s.cast == "string" and r.s.castSpell == "number" and r.s.castId == "string"
    and r.s.spellId == "number" and r.s.unit == "string" and r.s.level == "number" and r.s.cls == "string" and r.s.hp == "number" and r.s.chan == "none",
    "a readable cast on the target: the unit's guid, level, class, health, the cast and the event's ids")
  assert(r.s.name == "string", "the creature's name is read (its kind kept, never the name)")
  fire("UNIT_SPELLCAST_START", "nameplate3", "cast-2", 1234)
  r = ev().UNIT_SPELLCAST_START
  assert(r.n == 2 and r.sec == 1 and r.nl == 0, "a nameplate with a hidden GUID counts as secret (not casting is not missing)")
  fire("UNIT_SPELLCAST_START", "player", "cast-3", 1)
  fire("UNIT_SPELLCAST_START", "party1", "cast-3", 1)
  fire("UNIT_SPELLCAST_START", SECRET.str(), "cast-3", 1)
  assert(ev().UNIT_SPELLCAST_START.n == 2, "our own casts, and a hidden unit, are not the probe's business")
  fire("UNIT_HEALTH", "target")
  assert(ev().UNIT_HEALTH.n == 1 and ev().UNIT_HEALTH.s.hp == "number", "health on the target")
  c.env.UnitCastingInfo = function() return nil end
  fire("UNIT_SPELLCAST_STOP", "target", "cast-1", 1234)
  r = ev().UNIT_SPELLCAST_STOP
  assert(r.ok == 1 and r.s.cast == "none" and r.s.castSpell == nil, "a cast that ended: no cast going on, nothing missing")
  fire("PLAYER_TARGET_CHANGED")
  assert(ev().PLAYER_TARGET_CHANGED.n == 1 and ev().PLAYER_TARGET_CHANGED.s.guid == "string", "a target change reads the target")
  -- auras on the player and party: the first harmful one, by C_UnitAuras
  local auraByIndex = c.env.C_UnitAuras.GetAuraDataByIndex
  c.env.C_UnitAuras.GetAuraDataByIndex = function(unit, i, filter)
    if i == 1 and filter == "HARMFUL" then return { name = "Mana Burn", spellId = 1300001, sourceUnit = "target", isHarmful = true, dispelName = "Magic" } end
  end
  fire("UNIT_AURA", "player", { isFullUpdate = true })
  r = ev().UNIT_AURA
  assert(r and r.n == 1 and r.ok == 1 and r.s.n == "number" and r.s.name == "string" and r.s.spellId == "number" and r.s.source == "string" and r.s.kind == "string", "a harmful aura on the player: its source unit and school")
  fire("UNIT_AURA", "target")
  assert(ev().UNIT_AURA.n == 1, "auras on creatures are not read (only what lands on us)")
  c.env.C_UnitAuras.GetAuraDataByIndex = auraByIndex
  -- nameplates and rare vignettes
  fire("NAME_PLATE_UNIT_ADDED", "nameplate1")
  assert(ev().NAME_PLATE_UNIT_ADDED.n == 1 and ev().NAME_PLATE_UNIT_ADDED.sec == 1 and ev().NAME_PLATE_UNIT_ADDED.s.level == "number", "a nameplate added reads the unit (its GUID hidden here)")
  c.env.C_VignetteInfo = { GetVignettes = function() return { "v-1" } end,
    GetVignetteInfo = function(id) return { vignetteGUID = id, objectGUID = "Creature-0-4455-0-12-7777-0000A1B2C3", name = "Grizzled Rare", atlasName = "VignetteKill", onWorldMap = true, onMinimap = true } end }
  fire("VIGNETTE_MINIMAP_UPDATED", "v-1", true)
  r = ev().VIGNETTE_MINIMAP_UPDATED
  assert(r and r.n == 1 and r.ok == 1 and r.s.objectGUID == "string" and r.s.atlas == "string", "a vignette: its object GUID and atlas")
  c.env.C_VignetteInfo = nil
  fire("VIGNETTE_MINIMAP_UPDATED", "v-2", true)
  assert(ev().VIGNETTE_MINIMAP_UPDATED.n == 2 and ev().VIGNETTE_MINIMAP_UPDATED.nl == 1, "a client without C_VignetteInfo: counted as missing")
  -- a merchant: the npc's GUID, the first item's id, price and link
  c.npcGUID = "Creature-0-4455-0-12-1234-0000A1B2C3"
  c.merchant = { 2589, 2592 }
  c.env.GetMerchantItemInfo = function(i) return "Linen Cloth", "", 13, 1, 0, true, nil end
  c.env.GetMerchantItemLink = function(i) return "|cffffffff|Hitem:2589::::::::29:::::|h[Linen Cloth]|h|r" end
  fire("MERCHANT_SHOW")
  r = ev().MERCHANT_SHOW
  assert(r and r.n == 1 and r.ok == 1 and r.s.guid == "string" and r.s.items == "number" and r.s.id == "number" and r.s.price == "number" and r.s.link == "string", "a merchant: who, how many, the first item's id, price and link")
  c.merchant = {}
  fire("MERCHANT_SHOW")
  assert(ev().MERCHANT_SHOW.n == 2 and ev().MERCHANT_SHOW.ok == 2, "an empty vendor: who and none, still ok")
  -- a chest: loot from a game object
  c.loot = { { id = 2589, src = { { "GameObject-0-4455-0-12-2843-0000A1B2C3", 1 } } } }
  fire("LOOT_OPENED", false, false)
  r = ev().LOOT_OPENED
  assert(r and r.n == 1 and r.ok == 1 and r.s.src == "string" and r.s.slots == "number", "a loot window: the first slot's source GUID")
  -- combat and encounter timing
  fire("PLAYER_REGEN_DISABLED"); fire("ENCOUNTER_START", 3303, "Shade of the Archmage", 1, 5); fire("ENCOUNTER_END", 3303, "Shade of the Archmage", 1, 5, 1); fire("PLAYER_REGEN_ENABLED")
  assert(ev().PLAYER_REGEN_DISABLED.n == 1 and ev().PLAYER_REGEN_ENABLED.n == 1 and ev().PLAYER_REGEN_ENABLED.s.t == "number"
    and ev().ENCOUNTER_START.s.id == "number" and ev().ENCOUNTER_START.s.t == "number" and ev().ENCOUNTER_START.s.diff == "number" and ev().ENCOUNTER_END.n == 1,
    "combat edges and the encounter id with a time")
  -- an event QuestBank registered but has no reader for: its argument count
  fire("SOMETHING_ELSE", 1, 2)
  assert(ev().SOMETHING_ELSE.s.nargs == "number", "an unknown event: counted with its argument count")
  -- with the box unticked nothing is counted
  DB.settings = DB.settings or {}
  DB.settings.noteGame = false
  local n0 = ev().UNIT_HEALTH.n
  f.__scripts.OnEvent(f, "UNIT_HEALTH", "target")
  assert(ev().UNIT_HEALTH.n == n0, "the box unticked: the frame's handler counts nothing")
  DB.settings.noteGame = nil
  c.env.UnitLevel, c.env.UnitGUID = unitLevel, guidOf
  c.env.UnitClassification, c.env.UnitHealth, c.env.UnitHealthMax, c.env.UnitCastingInfo, c.env.UnitChannelInfo = nil, nil, nil, nil, nil
  c.env.GetMerchantItemInfo, c.env.GetMerchantItemLink = nil, nil
  -- the readout, then the clear that the notes box does
  local chat0 = #c.chat
  c.env.SlashCmdList.QUESTBANK("events")
  local said = table.concat(c.chat, "\n", chat0 + 1)
  assert(#c.chat > chat0 and said:find("TEST_EVENT: 2 seen, 1 ok, 1 secret, 0 missing (a=number b=string)", 1, true), "/qb events lists the events with their counts: " .. said:sub(1, 200))
  Ob.Clear()
  assert(DB.diag.ev == nil, "clear drops the probe's counts")
  Ob.Note("X", { a = 1 })
  assert(ev().X.n == 1, "and counting starts again")
  -- the cap, and never a name in what is kept
  for i = 1, 70 do Ob.Note("FILL_" .. i, { a = i }) end
  assert(countOf(ev()) == 60, "no more than 60 event keys")
  local dump = {}
  for k, v in pairs(ev()) do for fld, kind in pairs(v.s) do dump[#dump + 1] = k .. fld .. kind end end
  assert(not table.concat(dump):find("Torvald", 1, true) and not table.concat(dump):find("Arcane Bolt", 1, true), "never a player's name, never a value")
  Ob.Clear()
end

----------------------------------------------------------------------------
-- map icons (QuestMap.lua): a level 3 human priest in Elwynn on the Forever client. The spots are injected here
-- (gen_data builds the real ones); the givers and hand-ins are the catalog's own
----------------------------------------------------------------------------
local maren = newClient({
  name = "Maren", level = 3, cap = 60, faction = "Alliance", className = "Priest", class = "PRIEST", classID = 5, race = "Human",
  log = { { 7, 0 }, { 33, 1 }, { 18, 0 } }, done = { [783] = true, [5261] = true }, group = false, guild = false,
  world = { 0, -8914, -133 }, bind = "Northshire Abbey", riding = false, bagSlots = {}, xp = 900, map = 1429,
})
maren.map.id = 1429
do
  local M, MQ = maren, maren.QB
  local MD = MQ.Data
  local QMm = MQ.QuestMap
  local SPOT = {
    [7] = "k,1,1429,483,397,25,c,1;k,1,1429,470,350,30,p,1;u,2,1429,450,380,0,g,4",
    [18] = "c,5,1429,540,300,40,w,2;c,6,1429,560,320,0,g,3;c,5,1453,500,500,20,w,2",
    [33] = "k,1,1429,600,600,30,c,1", -- complete: none of its spots show
  }
  local function inject()
    MD.SN = { [1] = "Kobold Vermin", [2] = "Red Burlap Bandana", [3] = "Defias Mask", [4] = "Stolen Crate", [5] = "Northshire Gift Voucher" }
    MD.SPOT, MD.SREQ = {}, { [7] = "1:10,2:1", [18] = "5:12,6:12", [33] = "1:8" }
    for k, v in pairs(SPOT) do MD.SPOT[k] = v end
    MD.START = { [5805] = "s,0,1429,420,640,20,w,5;s,0,1453,100,100,20,c,5" }
  end
  inject()
  M.objectives = {
    [7] = { { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 } },
    -- the game lists them the other way round, and the masks are done
    [18] = { { text = "Defias Mask: 12/12", type = "item", finished = true, numFulfilled = 12, numRequired = 12 },
             { text = "Red Burlap Bandana: 2/12", type = "item", finished = false, numFulfilled = 2, numRequired = 12 } },
  }
  login(M)
  assert(QMm.provider, "on Forever the icons have their own provider on the world map")
  assert(#MQ.Pins.layers == 2 and MQ.Pins.watcher and MQ.Pins.watcher.__parent == M.map:GetCanvas(),
    "no hook on the world map (the mock's HookScript errors): both layers hear it shut as its providers, and a frame of QuestBank's on its canvas watches the keys")
  local function redraw()
    MQ:Recompute(true); MQ.Model.Finish(); MQ.Pins:Update(); QMm:Update()
  end
  local function icons(kind)
    local out = {}
    for _, pin in ipairs(ours(M, "QuestBankQuestPinTemplate")) do
      if not kind or pin.data.kind == kind then out[#out + 1] = pin end
    end
    return out
  end
  local function areas() return ours(M, "QuestBankAreaPinTemplate") end
  local function routePins() return ours(M, "QuestBankPinTemplate") end
  local function tipOf(pin) lines = {}; pin:OnMouseEnter(); pin:OnMouseLeave(); return table.concat(lines, "\n") end
  local function marksFor(id) local n = 0; for _, pin in ipairs(icons("obj")) do if pin.data.id == id then n = n + 1 end end return n end
  local function near(pin, x, y) return math.abs(pin.mapX - x) < 1e-6 and math.abs(pin.mapY - y) < 1e-6 end

  -- the route's own pins off first: this layer then draws every NPC itself
  MQ:Settings().pins = false
  redraw()
  local give, turn, obj, start = icons("give"), icons("turn"), icons("obj"), icons("start")
  print(string.format("map icons, Elwynn at level 3: %d !, %d ?, %d objective marks, %d item drops, %d areas", #give, #turn, #obj, #start, #areas()))
  assert(#give > 0 and #turn == 1 and #obj == 4 and #start == 1 and #areas() == 0, "the ! , ? , objectives and the item drop are all there; no areas of QuestBank's own (the game's blob is the area)")
  -- ! only for quests you can take now: todo, not in the log, not done, for your side; the game's own offer pin:
  -- QuestNormal on a 22 px frame (where a click lands, the game's), on the offers' level, 1.0 to 1.2 as you zoom in; its
  -- art at half its 32 px since 5.4.4 (the owner: "quest icons on the map are massive, can be halved")
  for _, pin in ipairs(give) do
    assert(pin.levelType == "PIN_FRAME_LEVEL_QUEST_OFFER" and pin.__frameLevel == M.map.levels.PIN_FRAME_LEVEL_QUEST_OFFER and pin.Texture.__atlas == "QuestNormal"
      and pin.Texture.__w == 16 and pin.__w == 22 and pin.kind.template == "QuestBankOfferTemplate" and pin.kind.scale[2] == 1.0 and pin.kind.scale[3] == 1.2
      and pin.Texture.__vertex[1] == 1 and pin.Texture.__vertex[2] == 1 and not pin.Texture.__desat,
      "a ! is the game's offer pin, on the offers' level")
    for _, q in ipairs(pin.data.quests) do
      local st = MQ:Status(q)
      assert(st.code == "todo" and not st.behind, "a ! only for a quest you can take now: " .. q.name .. " (" .. st.code .. ")")
      assert(not MQ.state.log[q.id] and not M.done[q.id] and q.side ~= 2, "never one in the log, done or Horde: " .. q.name)
    end
  end
  -- ? where Wolves Across the Border goes, at Eagan Peltskinner's own spot
  local eagan = turn[1]
  -- the ? is the game's quest POI for a complete quest: the disc with the turn-in glyph, 32 px on a 20 px button, the
  -- same size at every zoom, on the quest pins' level in the log's order
  local eaganIndex
  for i, e in ipairs(MQ.state.logOrder) do if e.id == 33 then eaganIndex = i end end
  assert(eagan.data.title == "Eagan Peltskinner" and eagan.data.quests[1].id == 33 and near(eagan, 0.489, 0.402)
    and eagan.kind.template == "QuestBankPoiTemplate" and eagan.Disc.__atlas == "UI-QuestPoi-QuestNumber" and eagan.Glyph.__atlas == "UI-QuestIcon-TurnIn-Normal"
    and eagan.Disc.__w == 16 and eagan.Glyph.__w == 16 and eagan.__w == 20 and eagan.Hi.__atlas == "UI-QuestPoi-InnerGlow" and not eagan.Hi:IsShown()
    and eagan.kind.scale[1] == 1 and eagan.kind.scale[2] == 1 and eagan.kind.scale[3] == 1 and eagan.levelType == "PIN_FRAME_LEVEL_ACTIVE_QUEST"
    and eagan.levelIndex == eaganIndex and eagan.__frameLevel == M.map.levels.PIN_FRAME_LEVEL_ACTIVE_QUEST + eaganIndex - 1,
    "a ? where the finished quest is handed in, as the game's complete quest pin: " .. tostring(eagan.data.title) .. " on level " .. tostring(eagan.levelIndex))
  -- objectives: Kobold Vermin's two areas and the crate no line of the game's fits; the bandanas, not the finished masks
  assert(marksFor(7) == 3 and marksFor(18) == 1 and marksFor(33) == 0, "the marks: 3 for Kobold Camp Cleanup, 1 for the bandanas, none for a complete quest")
  -- each is the game's quest POI in progress: the disc with the yellow in-progress glyph, on the quest pins' level
  -- in the log's order (Kobold Camp Cleanup is the log's second, the bandanas' quest its third)
  for _, pin in ipairs(obj) do
    local li
    for i, e in ipairs(MQ.state.logOrder) do if e.id == pin.data.id then li = i end end
    assert(pin.levelType == "PIN_FRAME_LEVEL_ACTIVE_QUEST" and pin.levelIndex == li and pin.__frameLevel == M.map.levels.PIN_FRAME_LEVEL_ACTIVE_QUEST + li - 1
      and pin.kind.template == "QuestBankPoiTemplate" and pin.Disc.__atlas == "UI-QuestPoi-QuestNumber" and pin.Glyph.__atlas == "Quest-In-Progress-Icon-yellow"
      and pin.Disc.__w == 16 and pin.__w == 20 and pin.kind.scale[3] == 1, "an objective's mark is the game's in-progress quest pin, on its quest's level: " .. tostring(pin.levelIndex))
    if pin.data.id == 18 then assert(pin.data.spot.name == 2 and near(pin, 0.54, 0.30), "the bandanas' spot, not the finished masks'") end
  end
  -- the item that starts Welcome! (from a Northshire Gift Voucher): where it drops, the game's ! in red (QuestTrail's
  -- mark for a quest a drop starts), on the offers' level
  assert(MQ:Status(MQ.Quest.Get(5805)).code == "item", "Welcome! starts from an item for Maren")
  assert(start[1].data.id == 5805 and near(start[1], 0.42, 0.64) and start[1].kind.template == "QuestBankOfferTemplate" and start[1].Texture.__atlas == "QuestNormal"
    and start[1].Texture.__desat and start[1].Texture.__vertex[1] == 1 and start[1].Texture.__vertex[2] == 0.22 and start[1].levelType == "PIN_FRAME_LEVEL_QUEST_OFFER",
    "where the item that starts a quest drops: the ! in red")
  -- tooltips say what and where from
  local t7 = tipOf(icons("obj")[1])
  -- the game's own words first (QuestDataProvider's tooltip: "[level] name" in its colour, "- " and each unfinished
  -- objective), then QuestBank's (what this spot is for, where it comes from) and the game's green instruction line
  assert(t7:find("%[%d+%] Kobold Camp Cleanup") and t7:find("- Kobold Vermin slain: 3/10", 1, true) and t7:find("Kill Kobold Vermin", 1, true)
    and t7:find("Position: Classic data (may have moved in Forever)", 1, true) and t7:find("<Click to show it on the arrow for now>", 1, true) and t7:find("<Shift-click: skip this quest>", 1, true)
    and t7:find("^%[%d+%] Kobold Camp Cleanup\n%- Kobold Vermin slain: 3/10\nKill Kobold Vermin\nPosition"), "the kill mark's tooltip (5.4.4: a click shows it for now, Shift-click skips it): " .. t7)
  local sources = {}
  for _, pin in ipairs(icons()) do
    local t = tipOf(pin)
    assert(#t > 0 and t:find("<Click to show it on the arrow for now>", 1, true) and not t:find("Click: ", 1, true), "every icon has a tooltip, its click the game's way: " .. t)
    for _, src in pairs(QMm.SOURCE) do if t:find("Position: " .. src, 1, true) then sources[src] = true end end
  end
  assert(sources["Wowhead Forever"] and sources["seen in players' games"] and sources["Classic data (may have moved in Forever)"], "tooltips name all three sources")
  local tStart = tipOf(start[1])
  assert(tStart:find("Northshire Gift Voucher", 1, true) and tStart:find("Drops here, and starts:\n[1] Welcome!", 1, true) and tStart:find("<Shift%-click: add to my route>"),
    "the drop's tooltip names the item and the quest: " .. tStart)
  local tGive = tipOf(give[1])
  assert(tGive:find("^" .. give[1].data.title:gsub("%p", "%%%0") .. "\nAvailable [Qq]uests?\n%[%d+%] ") and tGive:find("<Click to show it on the arrow for now>", 1, true)
    and tGive:find("<Shift%-click: add to my route>"), "a !'s tooltip: the NPC, the game's Available quest, each quest as the game titles it: " .. tGive)
  local tTurn = tipOf(eagan)
  assert(tTurn:find("^Eagan Peltskinner\nReady for turn%-in\n%[%d+%] Wolves Across the Border") and tTurn:find("<Click to show it on the arrow for now>", 1, true) and tTurn:find("<Shift-click: skip this quest>", 1, true),
    "a ?'s tooltip: the NPC, the game's Ready for turn-in, the quest: " .. tTurn)
  print("map icon tooltip:", (t7:gsub("\n", " | ")))
  print("map icon tooltip, !:", (tipOf(give[1]):gsub("\n", " | ")))
  print("map icon tooltip, ?:", (tipOf(eagan):gsub("\n", " | ")))
  print("map icon tooltip, drop:", (tStart:gsub("\n", " | ")))
  -- left click: the arrow points there at once, and a chat line carries the game's map-pin link; the game's own
  -- waypoint is never set from QuestBank's code (C_Map.SetUserWaypoint errors here), map open or shut, in combat or not
  local function lastLine() return M.chat[#M.chat] or "" end
  local mark = icons("obj")[1]
  local said = #M.chat
  mark:OnMouseClickAction("LeftButton")
  assert(#M.chat == said + 1 and lastLine():find("Waypoint: Kobold Camp Cleanup: Kobold Vermin (48, 40).", 1, true)
    and lastLine():find("|Hworldmap:1429:4830:3970|h", 1, true) and #M.pins == 0,
    "a click with the map open: a waypoint line with the map-pin link, nothing set by QuestBank: " .. lastLine())
  assert(MQ:Settings().arrowPin and MQ:Settings().arrowPin.name == "Kobold Camp Cleanup: Kobold Vermin", "the arrow points there")
  local wp = clickMapLink(M, lastLine())
  assert(wp and wp.m == 1429 and math.abs(wp.x - 0.483) < 1e-6 and math.abs(wp.y - 0.397) < 1e-6, "the link's click: the game's pin on the mark")
  said = #M.chat
  icons("obj")[1]:OnMouseClickAction("RightButton")
  assert(#M.chat == said, "a right-click is the map's (zoom out)")
  -- the frames' own mouse scripts: let go over an icon is a click, let go elsewhere is not
  mark = icons("obj")[1]
  assert(mark.__scripts.OnEnter and mark.__scripts.OnLeave and mark.__scripts.OnMouseUp, "QuestBank's frames have their own mouse scripts")
  lines = {}; mark.__scripts.OnEnter(mark); assert(#lines > 0, "hovering shows the tooltip"); mark.__scripts.OnLeave(mark)
  mark.__scripts.OnMouseUp(mark, "LeftButton", false)
  assert(#M.chat == said, "let go outside the icon: no click")
  -- (each click below is a session's first waypoint, so it shows in chat: later ones the arrow shows are not said)
  MQ.API.waypointSaid = false
  mark.__scripts.OnMouseUp(mark, "LeftButton", true)
  assert(#M.chat == said + 1 and lastLine():find("worldmap:", 1, true), "let go over it: a click")
  -- /qb next: the next stop's line and link, the map open or not
  said = #M.chat
  MQ.Pins:PinNext(true)
  assert(#M.chat == said + 1 and (lastLine():find("worldmap:", 1, true) or lastLine():find("Nothing on the route", 1, true)), "/qb next: " .. lastLine())
  -- in combat, the map shut or open: the same, at once
  M.map:Close()
  M.combat = true
  MQ.API.waypointSaid = false
  MQ.API.SetWaypoint(1429, 40, 50, "Test spot")
  assert(lastLine():find("|Hworldmap:1429:4000:5000|h", 1, true) and #M.pins == 1, "in combat, the map shut: the line at once, nothing set")
  M.map:Open()
  MQ.API.waypointSaid = false
  MQ.API.SetWaypoint(1429, 41, 51, "Test spot")
  assert(lastLine():find("|Hworldmap:1429:4100:5100|h", 1, true) and #M.pins == 1, "in combat, the map open: the same")
  M.combat = false
  MQ.Pins.combatFrame.__scripts.OnEvent(MQ.Pins.combatFrame, "PLAYER_REGEN_ENABLED")
  assert(#M.pins == 1, "and nothing set when combat ends either")
  -- the same frames again, drawn for the map now open
  give, turn, obj, start = icons("give"), icons("turn"), icons("obj"), icons("start")
  eagan = turn[1]
  mark = icons("obj")[1]
  -- Shift-click on a mark or a ?: the game's tracker is left alone (C_QuestLog.AddQuestWatch errors here); 5.4.4: the
  -- labelled change, its quest out of the route for good (Skip this quest), and the same click routes it again
  M.shift = true
  said = #M.chat
  local markId = mark.data.id
  mark:OnMouseClickAction("LeftButton")
  assert(#M.chat == said + 1 and lastLine():find("Skipped, out of your route", 1, true) and MQ:IsSkipped(markId) and not M.watched,
    "Shift-click on an objective: its quest skipped, the game's tracker untouched: " .. lastLine())
  assert(tipOf(mark):find("<Shift-click: route it again>", 1, true), "its tooltip says the same click routes it again")
  mark:OnMouseClickAction("LeftButton")
  assert(not MQ:IsSkipped(markId) and lastLine():find("Back in your route", 1, true), "and it does")
  eagan:OnMouseClickAction("LeftButton")
  assert(not M.watched and MQ:IsSkipped(33) and tipOf(eagan):find("<Shift-click: route it again>", 1, true), "and on a ?: its quest skipped, said so")
  eagan:OnMouseClickAction("LeftButton")
  assert(not MQ:IsSkipped(33), "routed again")
  M.map:Close(); M.map:Open()
  give, turn, obj, start = icons("give"), icons("turn"), icons("obj"), icons("start")
  eagan = turn[1]
  -- Shift-click on a !: the pick-up list, and the route's own ! takes over that NPC
  local g = give[1]
  local gd = g.data -- (the frame itself is drawn again for whatever comes next)
  local gid = gd.quests[1].id
  assert(not MQ:IsAdded(gid), "not on the pick-up list yet")
  g:OnMouseClickAction("LeftButton")
  M.shift = false
  assert(MQ:IsAdded(gid) and M.chat[#M.chat]:find("Added to your route", 1, true), "Shift-click on a ! puts its quests on the pick-up list (Add to my route)")
  MQ:Settings().pins = true
  redraw()
  -- (its own !, or folded into a stop of the route that stands on its giver: questing, the route on screen is the
  -- planned one, which takes the pick-up in)
  local routed = false
  for _, r in ipairs(MQ.Pins.list) do if r.name == gd.title or (r.num and r.ids and r.ids[gid] and (r.who == gd.title or r.name == gd.title)) then routed = true end end
  assert(routed, "the route's pins show that ! now")
  for _, pin in ipairs(icons("give")) do assert(pin.data.title ~= gd.title, "and the map icons leave that NPC to them") end
  -- with the route's pins on, a hand-in on the route is theirs too: the Route page on Ready now, its one stop Eagan's
  -- (a stop is named for its place when NPCs share it: "Elwynn Forest (49, 40)"; it stands where Eagan does. Questing,
  -- the planned route's stop 1 there takes Deputy Willem's quests too, and stands at his)
  MQ:Settings().routeQuest = "now"
  redraw()
  local eaganOnRoute = false
  for _, r in ipairs(MQ.Pins.list) do if r.num and r.m == 1429 and math.abs(r.x - 48.9) < 0.6 and math.abs(r.y - 40.2) < 0.6 then eaganOnRoute = true end end
  assert(eaganOnRoute and #icons("turn") == 0, "the route stands on Eagan: no second ? there")
  MQ:Settings().routeQuest = nil
  for _, id in ipairs(gd.quests) do if MQ:IsAdded(id.id) then MQ:ToggleAdd(id.id) end end
  MQ:Settings().pins = false
  redraw()
  assert(#icons("give") == #give and #icons("turn") == 1, "off the list and the route pins off: as before")

  -- each switch takes its own kind away and leaves the route's pins be
  MQ:Settings().pins = true
  redraw()
  local nRoute = #routePins()
  local function counts() return #icons("give"), #icons("turn"), #icons("obj") + #icons("start"), 0 end
  local g0, t0, o0, a0 = counts()
  QMm.Set("mapGive", false)
  local g1, t1, o1, a1 = counts()
  assert(g1 == 0 and t1 == t0 and o1 == o0 and a1 == a0 and #routePins() == nRoute, "no ! with Quests you can pick up off")
  QMm.Set("mapGive", true); QMm.Set("mapObj", false)
  g1, t1, o1, a1 = counts()
  assert(g1 == g0 and o1 == 0 and a1 == 0 and #routePins() == nRoute, "no objectives, drops or areas with Objectives and quest items off")
  QMm.Set("mapObj", true)
  M.env.SlashCmdList.QUESTBANK("icons")
  assert(MQ:Settings().mapIcons == false and #icons() == 0 and #routePins() == nRoute and M.chat[#M.chat]:find("off", 1, true), "/qb icons: all off, the route's pins stay")
  M.env.SlashCmdList.QUESTBANK("icons")
  g1, t1, o1, a1 = counts()
  assert(MQ:Settings().mapIcons and g1 == g0 and o1 == o0 and a1 == a0, "/qb icons: back on")
  -- the Settings page: four rows, the three kinds greyed out while the master is off
  MQ.UI:Open(5); MQ.Model.Finish(); MQ.UI:Refresh()
  local v5 = MQ.UI.views[5]
  assert(v5.mapIcons:IsEnabled() and v5.mapIcons:GetChecked() and v5.mapGive:GetChecked() and v5.mapTurn:GetChecked() and v5.mapObj:GetChecked(), "all four on by default")
  v5.mapTurn:SetChecked(false); v5.mapTurn.__scripts.OnClick(v5.mapTurn, "LeftButton")
  assert(MQ:Settings().mapTurn == false and #icons("turn") == 0 and #icons("give") > 0, "Hand-ins off from Settings")
  v5.mapTurn:SetChecked(true); v5.mapTurn.__scripts.OnClick(v5.mapTurn, "LeftButton")
  v5.mapIcons:SetChecked(false); v5.mapIcons.__scripts.OnClick(v5.mapIcons, "LeftButton")
  assert(MQ:Settings().mapIcons == false and #icons() == 0 and not v5.mapGive:IsEnabled() and v5.mapGive:GetChecked(), "master off: no icons, the kinds greyed out and kept")
  for _, pr in ipairs(checkLayout(MQ.UI.frame, "map icons: settings, master off")) do problems[#problems + 1] = pr end
  v5.mapIcons:SetChecked(true); v5.mapIcons.__scripts.OnClick(v5.mapIcons, "LeftButton")
  assert(v5.mapGive:IsEnabled() and #icons("give") == g0, "and back")
  for _, row in ipairs({ v5.mapIcons, v5.mapGive, v5.mapTurn, v5.mapObj }) do lines = {}; row.__scripts.OnEnter(row); assert(#lines > 0) end
  for _, pr in ipairs(checkLayout(MQ.UI.frame, "map icons: settings")) do problems[#problems + 1] = pr end
  MQ.UI.frame:Hide()

  -- objectives finish: their marks go; a slot no line of the game's fits stays until the quest is complete
  M.objectives[7][1] = { text = "Kobold Vermin slain: 10/10", type = "monster", finished = true, numFulfilled = 10, numRequired = 10 }
  redraw()
  assert(marksFor(7) == 1, "Kobold Vermin done: only the crate stays (no line of the game's fits it)")
  M.log[1] = { 7, 1 }
  MQ:Settings().pins = false
  redraw()
  local mcbride
  for _, pin in ipairs(icons("turn")) do if pin.data.title == "Marshal McBride" then mcbride = pin end end
  assert(marksFor(7) == 0 and mcbride, "complete: its marks go, and a ? stands at Marshal McBride")
  for _, pin in ipairs(icons("give")) do assert(pin.data.title ~= "Marshal McBride", "one icon per NPC: his ! goes on the ?") end
  if mcbride.data.offers then assert(tipOf(mcbride):find("\nAvailable [Qq]uests?\n"), "and its tooltip lists them under the game's word: " .. tipOf(mcbride)) end
  M.log[1] = { 7, 0 }
  M.objectives[7][1] = { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 }
  redraw()
  assert(marksFor(7) == 3, "back as it was")

  -- matching the game's lines: kind and count, then the name, then the name alone when the count changed
  do
    local list = QMm.Spots("k,1,1429,1,1,0,c,1;k,2,1429,1,1,0,c,6;c,5,1429,1,1,0,c,2")
    MD.SN[6] = "Kobold Worker"
    local objs = {
      { text = "Kobold Worker slain: 0/10", type = "monster", need = 10, done = true },
      { text = "Kobold Vermin slain: 2/10", type = "monster", need = 10, done = false },
      { text = "Red Burlap Bandana: 0/8", type = "item", need = 8, done = false },
    }
    local m = QMm.Match(objs, list, { [1] = 10, [2] = 10, [5] = 12 })
    assert(m[1] == objs[2] and m[2] == objs[1], "two kills of ten: told apart by name")
    assert(m[5] == objs[3], "the bandanas: the count changed, the name still fits")
    m = QMm.Match({ { text = "Something else", type = "event", need = 1 } }, list, { [1] = 10, [2] = 10, [5] = 12 })
    assert(next(m) == nil, "nothing fits: nothing matched, so the spots keep showing")
  end
  -- grey quests: the game's own range when the client says, else Classic's rule
  do
    local Qg = { lvl = 13 }
    assert(QMm.Grey(Qg, 20) and not QMm.Grey({ lvl = 14 }, 20) and not QMm.Grey({ lvl = 1 }, 5), "Classic: grey from 7 levels below at 20, never at 5")
    M.env.UnitQuestTrivialLevelRange = function() return 5 end
    assert(QMm.Grey({ lvl = 14 }, 20) and not QMm.Grey({ lvl = 15 }, 20), "the client's range when it gives one")
    M.env.UnitQuestTrivialLevelRange = nil
  end

  -- only zone maps (and Zephras Isle): not a continent; a spot is drawn on its own map only
  M.map:SetMapID(1415)
  assert(#icons() == 0, "no icons on a continent")
  M.mapTypes = { [2521] = 6 }
  MD.SPOT[18] = SPOT[18] .. ";c,5,2521,300,300,10,w,2"
  M.map:SetMapID(2521)
  assert(#icons("obj") == 1 and icons("obj")[1].data.id == 18, "Zephras Isle draws its own spots")
  -- (since 3.6.2 Wowhead's NPC tooltips place the island's own quest givers too, so their ! show there as well: each
  -- one for a giver who stands on the island, with a quest you can take now)
  for _, pin in ipairs(icons("give")) do
    for _, q in ipairs(pin.data.quests) do
      assert(q.give and q.give.m == 2521 and MQ:Status(q).code == "todo", "an island ! is for a giver standing there: " .. q.name)
    end
  end
  M.map:SetMapID(1453)
  for _, pin in ipairs(icons("obj")) do assert(pin.data.id == 18 and near(pin, 0.5, 0.5), "Stormwind: the spot tagged to Stormwind") end
  MD.SPOT[18] = SPOT[18]
  M.map:SetMapID(1429)
  assert(#icons("obj") == 4, "back on Elwynn")
  -- a hidden map builds nothing
  M.map.shown = false
  local draws = QMm.provider.draws
  redraw()
  assert(QMm.provider.draws == draws, "a hidden map builds nothing")
  M.map.shown = true
  redraw()

  -- QuestBank's own frames: on the canvas, at the map's frame level for their kind, placed and scaled as the map's
  -- own pins are, a right-click passing through to the map; never the canvas's pins (the mock's AcquirePin, its
  -- RemoveAllPinsByTemplate and the scroll container's MarkCanvasDirty error)
  MQ:Settings().pins = true
  redraw()
  local canvas = M.map:GetCanvas()
  assert(#routePins() > 0 and #icons() > 0 and #areas() == 0, "both layers drawn, no areas of QuestBank's own")
  local dungeons = 0
  for _, f in ipairs(ours(M)) do
    assert(f.__parent == canvas and f.__frameLevel == M.map.levels.Valid(f.levelType, f.levelIndex), "on the canvas at its level: " .. tostring(f.levelType))
    assert(f.kind.mouse and f.__mouse, "every pin takes the mouse")
    if f.kind.rightClick then
      -- a dungeon's entrance keeps the right button, as the game's does (the Adventure Guide; here the Dungeon Journal)
      dungeons = dungeons + 1
      assert(f.data.kind == "dungeon" and not f.__passThrough, "a dungeon's entrance takes the right button")
    else
      assert(f.__passThrough and f.__passThrough[1] == "RightButton", "a right-click passes through to zoom the map out")
    end
  end
  assert(dungeons == 0 or dungeons == #icons("dungeon"), "the entrances alone keep the right button")
  -- zoomed halfway in on a canvas at twice its scale: as MapCanvasPinMixin:ApplyCurrentScale and ApplyPinPosition would
  M.map:Zoom(2, 0.5)
  local function placed(f, scale)
    local pt = f.__points[1]
    return #f.__points == 1 and pt.point == "CENTER" and pt.rel == canvas and pt.relPoint == "TOPLEFT"
      and math.abs(pt.x - 1002 * (f.qX or f.mapX) / scale) < 1e-6 and math.abs(pt.y + 668 * (f.qY or f.mapY) / scale) < 1e-6
  end
  local ic, rp, ob = icons("give")[1], routePins()[1], icons("obj")[1]
  local s1, s2 = (1 + 0.2 * 0.5) / 2, 1 / 2
  assert(math.abs(ic.__scale - s1) < 1e-9 and placed(ic, s1), "a !: smaller against the canvas zoom, a little bigger zoomed in, as the game's offers (1.0 to 1.2)")
  assert(math.abs(rp.__scale - s2) < 1e-9 and placed(rp, s2) and math.abs(ob.__scale - s2) < 1e-9, "a route pin and an objective's mark: the same size on screen at every zoom, as the game's quest pins")
  M.map:Zoom(1, 0)
  assert(math.abs(ic.__scale - 1) < 1e-9 and placed(ic, 1) and math.abs(rp.__scale - 1) < 1e-9, "zoomed out again")
  -- the game's quantizer (WorldMapPOIQuantizer, 75 cells high): two quest pins on one spot snap to neighbouring cells'
  -- centres, so neither lies on the other; a pin with nothing near it stays where it stands; the ! are left alone, as
  -- the game leaves its offers; a ? of the other layer on a stop's spot is kept off it too
  do
    local keep = MQ.Pins.list
    MQ.Pins.list = { { m = 1429, x = 50, y = 50, num = 1, name = "One", ids = {}, lines = {}, quests = {} }, { m = 1429, x = 50.2, y = 50.1, num = 2, name = "Two", ids = {}, lines = {}, quests = {} },
                     { m = 1429, x = 20, y = 20, num = 3, name = "Lone", ids = {}, lines = {}, quests = {} }, { m = 1429, x = 20.1, y = 20.1, name = "A giver", ids = {}, lines = {}, quests = {} } }
    MQ.Pins.provider:RefreshAllData()
    local byName = {}
    for _, f in ipairs(routePins()) do byName[f.data.name] = f end
    local one, two, lone, giver = byName.One, byName.Two, byName.Lone, byName["A giver"]
    local wide = math.ceil(75 * 1002 / 668)
    assert(one.qX and two.qX and one.qX ~= two.qX or one.qY ~= two.qY, "two stops on one spot: snapped to cells of their own")
    for _, f in ipairs({ one, two }) do
      assert(math.abs(f.qX - f.mapX) <= 1 / wide + 1e-9 and math.abs(f.qY - f.mapY) <= 1 / 75 + 1e-9 and placed(f, 1), "within a cell of its spot: " .. f.data.name)
    end
    assert(lone.qX == nil and lone.cell and placed(lone, 1), "nothing near: left where it stands")
    assert(giver.qX == nil and giver.cell == nil and not giver.kind.quantize, "a ! is never snapped")
    -- the icons' layer: a ? that would share a stop's cell goes beside it
    local q = MQ.Quest.Get(33)
    local tx, ty = q.turn.x, q.turn.y
    q.turn.x, q.turn.y = 50, 50
    MQ:Settings().pins = true
    QMm.provider:RefreshAllData()
    local e2 = icons("turn")[1]
    if e2 then
      assert(e2.qX and (e2.qX ~= one.qX or e2.qY ~= one.qY) and (e2.qX ~= two.qX or e2.qY ~= two.qY), "a ? on the stops' spot: a cell of its own")
    end
    q.turn.x, q.turn.y = tx, ty
    MQ.Pins.list = keep
    redraw()
  end
  -- the route's stops as the game's quest pins: stop 1 as the quest the game super-tracks (its gold disc, the brown
  -- glyph while in progress, on the super-tracked quest's level above every other pin), the rest on the quest pins'
  -- levels in their order; a stop whose quests are all done shows the turn-in glyph
  do
    local stops = {}
    for _, f in ipairs(routePins()) do if f.data.num then stops[f.data.num] = f end end
    local one = stops[1]
    assert(one and one.kind.template == "QuestBankPoiTemplate" and one.Disc.__atlas == "UI-QuestPoi-QuestNumber-SuperTracked" and one.Disc.__w == 16
      and one.levelType == "PIN_FRAME_LEVEL_SUPER_TRACKED_QUEST" and one.__frameLevel == M.map.levels.PIN_FRAME_LEVEL_SUPER_TRACKED_QUEST
      and (one.Glyph.__atlas == (one.data.ready and "UI-QuestIcon-TurnIn-Normal" or "Quest-In-Progress-Icon-Brown")),
      "stop 1: the game's super-tracked quest pin: " .. tostring(one and one.Glyph.__atlas))
    local n = 0
    for num, f in pairs(stops) do
      if num > 1 then
        n = n + 1
        assert(f.Disc.__atlas == "UI-QuestPoi-QuestNumber" and f.levelType == "PIN_FRAME_LEVEL_ACTIVE_QUEST" and f.levelIndex == num
          and f.__frameLevel == M.map.levels.Valid("PIN_FRAME_LEVEL_ACTIVE_QUEST", num)
          and f.Glyph.__atlas == (f.data.ready and "UI-QuestIcon-TurnIn-Normal" or "Quest-In-Progress-Icon-yellow"), "stop " .. num .. ": the game's quest pin on its level")
        assert(rawget(f, "Num") == nil, "no number on the disc: the game draws none")
      end
    end
    -- the tooltip: the place, each quest as the game titles it with its XP, which stop it is, the click
    local t = tipOf(one)
    assert(t:find("^" .. one.data.name:gsub("%p", "%%%0") .. "\n%[%d+%] ") and t:find("Stop 1 of %d+, at ") and t:find("<Click to show it on the arrow for now>", 1, true) and not t:find("Click: ", 1, true),
      "a stop's tooltip: " .. t)
    -- the mouse on a quest pin: the inner glow, as the game's HighlightTexture; the button held: the pressed disc and
    -- the glyph a pixel right and down; let go: as it was
    one.__scripts.OnEnter(one)
    assert(one.Hi:IsShown() and one.Hi.__atlas == "UI-QuestPoi-InnerGlow" and one.Hi.__blend == "ADD", "hovered: the inner glow")
    one.__scripts.OnMouseDown(one, "LeftButton")
    assert(one.Disc.__atlas == "UI-QuestPoi-QuestNumber-Pressed-SuperTracked" and one.Glyph.__points[1].x == 1 and one.Glyph.__points[1].y == -1, "held: the pressed disc")
    one.__scripts.OnMouseUp(one, "LeftButton", false)
    assert(one.Disc.__atlas == "UI-QuestPoi-QuestNumber-SuperTracked" and one.Glyph.__points[1].x == 0, "let go: the disc back")
    one.__scripts.OnLeave(one)
    assert(not one.Hi:IsShown(), "left: no glow")
    -- a planned pick-up: the game's offer pin, its tooltip the game's Available quest
    local pick
    for _, f in ipairs(routePins()) do if not f.data.num then pick = f end end
    if pick then
      assert(pick.kind.template == "QuestBankOfferTemplate" and pick.Texture.__atlas == "QuestNormal" and pick.levelType == "PIN_FRAME_LEVEL_QUEST_OFFER", "a planned pick-up: the game's !")
      local tp = tipOf(pick)
      assert(tp:find("\nAvailable [Qq]uests?\n%[%d+%] ") and tp:find("<Click to show it on the arrow for now>", 1, true), "its tooltip: " .. tp)
    end
  end
  -- a dungeon's entrance as the game's own pin: the Dungeon atlas at its 32 px, the frame sized to it, on the
  -- entrances' level, 1.0 to 1.2 as you zoom in; its tooltip the game's (name, kind and levels, the green instruction
  -- for the right button), QuestBank's quest list between; a left click a waypoint, the right the Dungeon Journal
  do
    local wasId = M.map.id
    M.map:SetMapID(1436)
    local dm
    for _, f in ipairs(icons("dungeon")) do if f.data.cat.key == "d1581" then dm = f end end
    assert(dm and dm.kind.template == "QuestBankMarkTemplate" and dm.Texture.__atlas == "Dungeon" and dm.Texture.__w == 32 and dm.__w == 32
      and dm.hi and dm.hi.__atlas == "Dungeon" and dm.levelType == "PIN_FRAME_LEVEL_DUNGEON_ENTRANCE"
      and dm.__frameLevel == M.map.levels.PIN_FRAME_LEVEL_DUNGEON_ENTRANCE and dm.kind.scale[3] == 1.2 and dm.kind.rightClick,
      "the Deadmines' entrance as the game's dungeon pin")
    local td = tipOf(dm)
    assert(td:find("^" .. dm.data.cat.name:gsub("%p", "%%%0") .. " | %d+/%d+ quests done\nDungeon, level %d+%-%d+\n") and td:find("<Click to show it on the arrow for now>", 1, true)
      and td:find("<Right Click to open the Dungeon Journal>", 1, true), "its tooltip: " .. td)
    local SetWaypoint, got = MQ.API.SetWaypoint, nil
    MQ.API.SetWaypoint = function(...) got = { ... } end
    dm:OnMouseClickAction("LeftButton")
    assert(got and got[1] == 1436 and got[4] == dm.data.cat.name, "left: a waypoint on the entrance")
    MQ.API.SetWaypoint = SetWaypoint
    dm:OnMouseClickAction("RightButton")
    assert(MQ.UI.tab == 7 and M.env.QuestBankDungeonMap.cat.key == "d1581", "right: the Dungeon Journal on it")
    MQ.UI.frame:Hide()
    M.map:SetMapID(wasId)
  end

  -- combat: nothing made or drawn (SetPassThroughButtons errors in combat here, as the game's restricted call is
  -- blocked); a redraw waits for the end of combat; zooming still moves what is there
  local made = (MQ.Pins.provider.made or 0) + (QMm.provider.made or 0)
  M.combat = true
  local d1, d2 = MQ.Pins.provider.draws, QMm.provider.draws
  M.objectives[7][1].finished = true
  redraw()
  assert(MQ.Pins.provider.draws == d1 and QMm.provider.draws == d2 and marksFor(7) == 3, "in combat the frames stay as they were")
  M.map:Zoom(1.5, 0.3)
  assert(math.abs(ic.__scale - (1 + 0.2 * 0.3) / 1.5) < 1e-9, "zooming in combat moves and scales them")
  M.map:Zoom(1, 0)
  -- the map changes in combat: the frames drawn for the old one hide, and show again on it
  M.map:SetMapID(1453)
  for _, f in ipairs(ours(M)) do assert(not f:IsShown(), "frames drawn for another map hide in combat") end
  M.map:SetMapID(1429)
  for _, f in ipairs(ours(M)) do assert(f:IsShown(), "and show again back on their map") end
  M.map:SetMapID(1453)
  -- the map opened in combat: the same, nothing made
  M.map:Close(); M.map:Open()
  assert((MQ.Pins.provider.made or 0) + (QMm.provider.made or 0) == made and MQ.Pins.provider.draws == d1, "no frame made or drawn in combat")
  -- combat ends: both layers draw again, for the map on show
  M.combat = false
  local f = MQ.Pins.combatFrame
  f.__scripts.OnEvent(f, "PLAYER_REGEN_ENABLED")
  assert(MQ.Pins.provider.draws > d1 and QMm.provider.draws > d2 and MQ.Pins.provider.drawnFor == 1453 and QMm.provider.drawnFor == 1453,
    "after combat both layers draw the map on show")
  for _, fr in ipairs(ours(M)) do assert(fr:IsShown() and (fr.kind.rightClick or fr.__passThrough[1] == "RightButton"), "every frame shown, right-click passing through") end
  M.map:SetMapID(1429)
  assert(marksFor(7) == 1, "and the kills done in combat are off the map now")
  M.objectives[7][1].finished = false
  -- the frames are kept and drawn again, not made anew each time
  local before = (MQ.Pins.provider.made or 0) + (QMm.provider.made or 0)
  for _ = 1, 3 do redraw() end
  assert((MQ.Pins.provider.made or 0) + (QMm.provider.made or 0) == before, "a redraw makes no new frames")

  -- the game's own map pin: with Ctrl held, or the map's pin button on, QuestBank's frames let the mouse through, so the
  -- player's click lands on the map and the game places its pin as its own code (the cursor over them is the map's pin
  -- cursor then). Let go, they take it again; in combat too (EnableMouse is restricted on protected frames only).
  -- Not on a map the game has no pins for: a click there is QuestBank's waypoint, as without Ctrl
  do
    local function mice()
      local on, off = 0, 0
      for _, fr in ipairs(ours(M)) do
        if fr.kind.mouse then if fr.__mouse then on = on + 1 else off = off + 1 end end
      end
      return on, off
    end
    local on0, off0 = mice()
    assert(on0 > 0 and off0 == 0, "every icon and route pin takes the mouse")
    M.ctrl = true; tick(M, 0)
    local on1, off1 = mice()
    assert(on1 == 0 and off1 == on0, "Ctrl held: each lets the mouse through to the map")
    for _, fr in ipairs(ours(M)) do if not fr.kind.mouse then assert(fr.__mouse == false, "an area still takes none") end end
    redraw()
    assert(mice() == 0, "drawn again with Ctrl held: still through")
    M.combat = true
    M.ctrl = false; tick(M, 0)
    assert(select(2, mice()) == 0, "let go, in combat: they take it again")
    M.ctrl = true; tick(M, 0)
    assert(mice() == 0, "and Ctrl again, in combat: through")
    M.combat = false
    M.ctrl = false; tick(M, 0)
    M.map.WorldMapTrackingPinButton.isActive = true; tick(M, 0)
    assert(mice() == 0, "the map's pin button on: through")
    M.noPins = { [1453] = true }
    M.map:SetMapID(1453); tick(M, 0)
    assert(select(2, mice()) == 0, "a map the game has no pins for: they keep the mouse")
    M.map:SetMapID(1429); tick(M, 0)
    assert(mice() == 0, "back on Elwynn: through")
    M.noPins = nil
    M.map.WorldMapTrackingPinButton.isActive = false; tick(M, 0)
    assert(select(2, mice()) == 0, "the button off: they take it again")
    -- EnableMouse isn't restricted on plain frames: a client whose CheckAllowProtectedFunctions says no (in combat, say)
    -- changes nothing, and isn't asked. A frame that says it is protected keeps the mouse
    local asked = 0
    M.env.C_RestrictedActions = { CheckAllowProtectedFunctions = function() asked = asked + 1; return false end }
    M.combat = true
    M.ctrl = true; tick(M, 0); tick(M, 0)
    assert(mice() == 0 and asked == 0, "a no for protected calls, in combat: through all the same, and not asked")
    M.ctrl = false; tick(M, 0)
    assert(select(2, mice()) == 0, "and back")
    M.combat = false
    M.env.C_RestrictedActions = nil
    local prot = ours(M)[1]
    for _, fr in ipairs(ours(M)) do if fr.kind.mouse then prot = fr; break end end
    prot.IsProtected = function() return true end
    M.ctrl = true; tick(M, 0)
    local on2 = mice()
    assert(on2 == 1 and prot.__mouse, "a protected one keeps the mouse; the rest let it through")
    M.ctrl = false; tick(M, 0)
    prot.IsProtected = nil
    -- the map shut with Ctrl held: drawn with the mouse when it opens; Ctrl still down, through again
    M.ctrl = true; tick(M, 0)
    M.map:Close()
    assert(select(2, mice()) == 0, "the map shut: they take the mouse again")
    tick(M, 0)
    assert(select(2, mice()) == 0, "and the keys aren't watched while it is shut")
    M.map:Open(); tick(M, 0)
    assert(mice() == 0, "opened with Ctrl down: through")
    M.ctrl = false; tick(M, 0)
    assert(select(2, mice()) == 0 and not MQ.Pins.through, "let go")
  end

  -- the game holding addons back as in combat without InCombatLockdown (C_RestrictedActions, an encounter): the layers
  -- wait the same way, and draw when the restriction ends (ADDON_RESTRICTION_STATE_CHANGED, inactive); the frames'
  -- right-click pass-through is set only when the client allows protected calls on the frame (asked silently)
  do
    local E = M.env.Enum
    E.AddOnRestrictionType = { Combat = 0, Encounter = 1, ChallengeMode = 2, PvPMatch = 3, Map = 4, Chat = 5 }
    E.AddOnRestrictionState = { Inactive = 0, Activating = 1, Active = 2 }
    local active, allow = {}, true
    M.env.C_RestrictedActions = {
      IsAddOnRestrictionActive = function(kind) return active[kind] or false end,
      CheckAllowProtectedFunctions = function(obj, silent) assert(silent == true, "asked silently: asking never trips the block"); return allow end,
    }
    local pv, cf = MQ.Pins.provider, MQ.Pins.combatFrame
    assert(not MQ.Pins.InCombat(), "nothing held back: not combat")
    active[1] = true
    assert(MQ.Pins.InCombat(), "an encounter's restriction counts as combat")
    local d = pv.draws
    M.map:SetMapID(1453)
    assert(pv.draws == d, "nothing drawn while the game holds addons back")
    cf.__scripts.OnEvent(cf, "ADDON_RESTRICTION_STATE_CHANGED", 1, 1)
    assert(pv.draws == d, "the event before a restriction starts: nothing")
    active[1] = nil
    cf.__scripts.OnEvent(cf, "ADDON_RESTRICTION_STATE_CHANGED", 1, 0)
    assert(pv.draws > d and pv.drawnFor == 1453, "drawn when it ends, for the map on show")
    -- a frame made while the client says no: no pass-through call; set on its next draw once allowed
    allow = false
    local fr = pv:Make(MQ.Pins.ROUTE)
    assert(fr and not fr.passSet and not fr.__passThrough, "made, the protected call left out")
    pv.free[MQ.Pins.ROUTE] = pv.free[MQ.Pins.ROUTE] or {}
    table.insert(pv.free[MQ.Pins.ROUTE], fr)
    allow = true
    local got = pv:Add(MQ.Pins.ROUTE, { name = "Test stop", num = 1, icon = 1 }, 0.5, 0.5)
    assert(got == fr and fr.passSet and fr.__passThrough and fr.__passThrough[1] == "RightButton", "allowed again: set when it is next drawn, once")
    pv:RefreshAllData()
    M.env.C_RestrictedActions = nil
    E.AddOnRestrictionType, E.AddOnRestrictionState = nil, nil
    M.map:SetMapID(1429)
  end

  -- the recorder: a call the game blocked and blamed on QuestBank is kept in QuestBankDB.diag.blocked, its stack with
  -- QuestBank's own files by name and no other path, and said once in chat; another addon's is none of QuestBank's
  do
    local bf = MQ.blockedFrame
    M.env.debugstack = function() return table.concat({
      "[C]: in function 'SetPassThroughButtons'",
      "[Interface/AddOns/Blizzard_MapCanvas/MapCanvas_DataProviderBase.lua]:290: in function 'CheckMouseButtonPassthrough'",
      "[Interface/AddOns/Blizzard_MapCanvas/Blizzard_MapCanvas.lua]:331: in function 'AcquirePin'",
      '[string "@Interface/AddOns/QuestBank/Pins.lua"]:164: in function <Interface/AddOns/QuestBank/Pins.lua:160>',
      "[Interface/AddOns/SomeOtherAddon/Core.lua]:12: in function 'Thing'",
      "C:\\Users\\Someone\\World of Warcraft\\_classic_\\Interface\\AddOns\\QuestBank\\Core.lua:50: in function <...aceBlizzard_MapCanvas/Blizzard_MapCanvas.lua:116>",
      "*Blizzard_WorldMap.xml:78_OnLoad:1: in function 'onCloseCallback'",
    }, "\n") end
    local said = #M.chat
    M.combat = true
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_BLOCKED", "QuestBank", "Frame:SetPassThroughButtons()")
    local list = M.env.QuestBankDB.diag.blocked
    local b = list and list[1]
    assert(b and b.fn == "Frame:SetPassThroughButtons()" and b.combat == true and type(b.at) == "number" and b.kind == "blocked" and b.qb == MQ.version,
      "a blocked call is kept: what, when, in combat")
    local st = b.stack
    assert(not st:find("Interface", 1, true) and not st:find("SomeOtherAddon", 1, true) and not st:find("Users", 1, true) and not st:find("Blizzard_", 1, true)
      and st:find("[QuestBank/Pins.lua]:164: in function <QuestBank/Pins.lua:160>", 1, true) and st:find("[(game)]:331: in function 'AcquirePin'", 1, true)
      and st:find("[(addon)]:12: in function 'Thing'", 1, true) and st:find("QuestBank/Core.lua:50", 1, true) and st:find("[C]: in function 'SetPassThroughButtons'", 1, true),
      "its stack: QuestBank's files by name, no other path:\n" .. st)
    assert(#M.chat == said + 1 and M.chat[#M.chat]:find("calling Frame:SetPassThroughButtons() in combat", 1, true) and M.chat[#M.chat]:find("/qb errors", 1, true),
      "said in chat: " .. M.chat[#M.chat])
    print("blocked, kept:", (st:gsub("\n", " | ")))
    -- the same call again: counted. Others: kept, the last 10. Said once
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_BLOCKED", "QuestBank", "Frame:SetPassThroughButtons()")
    assert(#list == 1 and list[1].n == 2, "the same call again: counted")
    M.combat = false
    for i = 1, 11 do bf.__scripts.OnEvent(bf, "ADDON_ACTION_BLOCKED", "QuestBank", "Thing" .. i .. "()") end
    assert(#list == 10 and list[10].fn == "Thing11()" and list[1].fn == "Thing2()" and list[1].combat == false, "the last 10 kept")
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_FORBIDDEN", "QuestBank", "UseQuestLogSpecialItem()")
    assert(list[#list].kind == "forbidden" and list[#list].fn == "UseQuestLogSpecialItem()", "forbidden ones too")
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_BLOCKED", "SomeOtherAddon", "CastSpellByName()")
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_FORBIDDEN", "SomeOtherAddon", "CastSpellByName()")
    assert(list[#list].fn == "UseQuestLogSpecialItem()" and #M.chat == said + 1, "another addon's: not kept, nothing said")
    -- /qb errors lists them to copy, newest first; /qb errors clear forgets them
    M.env.SlashCmdList.QUESTBANK("errors")
    local text = M.env.QuestBankErrors.eb:GetText()
    assert(text:find("the game forbade UseQuestLogSpecialItem()", 1, true) and text:find("the game blocked Thing11()", 1, true)
      and text:find("the game forbade", 1, true) < text:find("the game blocked Thing11()", 1, true), "/qb errors lists them: " .. text:sub(1, 300))
    M.env.QuestBankErrors:Hide()
    M.env.SlashCmdList.QUESTBANK("errors clear")
    assert(M.env.QuestBankDB.diag.blocked == nil, "/qb errors clear forgets them")
    M.env.debugstack = nil
    -- a long chain: both ends kept. The game cuts debugstack(2, 8, 8) to the top 8 lines and the bottom 8 with "..."
    -- between; the top shows the blocked call, the bottom where the chain began (here an event handler, in another
    -- addon's file: a stale taint has no QuestBank frame in it at all)
    local chain = { "[C]: in function 'SetPassThroughButtons'" }
    for i = 2, 20 do chain[#chain + 1] = "[Interface/AddOns/Blizzard_MapCanvas/Blizzard_MapCanvas.lua]:" .. (100 + i) .. ": in function 'Step" .. i .. "'" end
    chain[#chain + 1] = "[Interface/AddOns/SomeOtherAddon/Libs/AceEvent-3.0.lua]:120: in function <...AceEvent-3.0.lua:119>"
    local asked
    M.env.debugstack = function(start, top, bottom)
      asked = { start, top, bottom }
      local out = {}
      for i = 1, top do out[#out + 1] = chain[i] end
      out[#out + 1] = "..."
      for i = #chain - bottom + 1, #chain do out[#out + 1] = chain[i] end
      return table.concat(out, "\n") .. "\n"
    end
    bf.__scripts.OnEvent(bf, "ADDON_ACTION_BLOCKED", "QuestBank", "Frame:SetPassThroughButtons()")
    assert(asked and asked[1] == 2 and asked[2] == 8 and asked[3] == 8, "the recorder asks for both ends: debugstack(2, 8, 8)")
    local kept = M.env.QuestBankDB.diag.blocked[#M.env.QuestBankDB.diag.blocked].stack
    local rows = {}
    for row in kept:gmatch("[^\n]+") do rows[#rows + 1] = row end
    assert(#rows == 17 and rows[1] == "[C]: in function 'SetPassThroughButtons'" and rows[9] == "..." and rows[17]:find("[(addon)]:120:", 1, true)
      and kept:find("Step8'", 1, true) and not kept:find("Step9'", 1, true) and not kept:find("Step13'", 1, true) and kept:find("Step14'", 1, true),
      "the top 8 and the bottom 8 kept, the middle left out:\n" .. kept)
    -- a stack longer than that however it comes: cut the same way, 16 frames at most
    local long = {}
    for i = 1, 30 do long[#long + 1] = "[Interface/AddOns/QuestBank/UI.lua]:" .. i .. ": in function 'f" .. i .. "'" end
    local cut = MQ.Err.CleanStack(table.concat(long, "\n"))
    rows = {}
    for row in cut:gmatch("[^\n]+") do rows[#rows + 1] = row end
    assert(#rows == 17 and rows[1] == "[QuestBank/UI.lua]:1: in function 'f1'" and rows[8]:find("'f8'", 1, true) and rows[9] == "..."
      and rows[10]:find("'f23'", 1, true) and rows[17]:find("'f30'", 1, true), "a long stack: its two ends:\n" .. cut)
    M.env.debugstack = nil
    M.env.SlashCmdList.QUESTBANK("errors clear")
  end

  -- an older Data.lua: no spots at all, still the ! and ?
  MQ:Settings().pins = false
  MD.SPOT, MD.START, MD.SN, MD.SREQ = nil, nil, nil, nil
  redraw()
  assert(#icons("give") == #give and #icons("turn") == 1 and #icons("obj") == 0 and #icons("start") == 0, "no D.SPOT: the ! and ? still show")
  inject()
  redraw()
  assert(#icons("obj") == 4 and #icons("start") == 1, "and the spots are back")
  -- the atlas missing: the file id
  M.noAtlas = { QuestNormal = true }
  redraw()
  assert(icons("give")[1].Texture.__tex == MD.TEX.questAvail and icons("give")[1].Texture.__w == 16, "no atlas: the gossip ! file, at the icons' size")
  M.noAtlas = { ["UI-QuestPoi-QuestNumber"] = true, ["UI-QuestIcon-TurnIn-Normal"] = true }
  redraw()
  local tp0 = icons("turn")[1]
  assert(tp0.Disc.__tex == 334391 and tp0.Disc.__tc[1] == 0.875 and tp0.Disc.__tc[3] == 0.875 and tp0.Glyph.__tex == MD.TEX.questActive,
    "no atlas: the disc from UI-QuestPoi-NumberIcons as POIButton.xml cuts it, the gossip ?")
  M.noAtlas = nil

  -- a tie nothing settles is never guessed by order: on a German client the names don't help, so neither slot is
  -- matched and the spots of both keep showing until the quest is complete
  do
    local list = QMm.Spots("c,5,1429,1,1,0,c,2;c,6,1429,1,1,0,c,3")
    local objs = { { text = "Defiasmaske: 12/12", type = "item", need = 12, done = true },
                   { text = "Rotes Leinenkopftuch: 2/12", type = "item", need = 12, done = false } }
    local m = QMm.Match(objs, list, { [5] = 12, [6] = 12 })
    assert(m[5] == nil and m[6] == nil, "deDE: two items of twelve and no name to tell them apart: neither is guessed")
    -- one settled leaves the other one line: the kill fits only the monster's, then the use has the object's
    local l2 = QMm.Spots("u,1,1429,1,1,0,c,4;k,2,1429,1,1,0,c,1")
    local o2 = { { text = "Kiste benutzt: 0/1", type = "object", need = 1 }, { text = "Koboldungeziefer: 0/1", type = "monster", need = 1 } }
    m = QMm.Match(o2, l2, { [1] = 1, [2] = 1 })
    assert(m[2] == o2[2] and m[1] == o2[1], "deDE: the kill settled by its kind, the use by what is left")
  end

  -- slot 0 is no objective of the catalog's (players' games for a quest it doesn't know, or a spot no slot was found
  -- for): never matched against the game's lines, so its spots show until the quest is complete
  do
    local list = QMm.Spots("k,0,1429,1,1,0,g;e,0,1429,1,1,0,g;k,1,1429,1,1,0,c,1")
    local objs = { { text = "Kobold Vermin slain: 10/10", type = "monster", need = 10, done = true },
                   { text = "Camp explored", type = "event", need = 1, done = true } }
    local m = QMm.Match(objs, list, { [1] = 10 })
    assert(m[0] == nil and m[1] == objs[1], "slot 0 is never matched; slot 1 is")
    m = QMm.Match(objs, QMm.Spots("k,0,1429,1,1,0,g"), {})
    assert(next(m) == nil, "a quest the catalog doesn't know: nothing matched")
    MD.SPOT[7] = SPOT[7] .. ";k,0,1429,300,300,15,g"
    M.objectives[7][1] = { text = "Kobold Vermin slain: 10/10", type = "monster", finished = true, numFulfilled = 10, numRequired = 10 }
    MQ:Settings().pins = false
    redraw()
    local zero
    for _, pin in ipairs(icons("obj")) do if pin.data.id == 7 and pin.data.spot.slot == 0 then zero = pin end end
    assert(marksFor(7) == 2 and zero and near(zero, 0.3, 0.3) and tipOf(zero):find("Position: seen in players' games", 1, true),
      "the kills done: the crate and the players' slot-0 spot stay")
    M.log[1] = { 7, 1 }
    redraw()
    assert(marksFor(7) == 0, "until the quest is complete")
    M.log[1] = { 7, 0 }
    M.objectives[7][1] = { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 }
    MD.SPOT[7] = SPOT[7]
    redraw()
    assert(marksFor(7) == 3, "back as it was")
  end

  -- a quest the catalog doesn't know (Forever's own) has all its spots in slot 0, each of the kind of the game's line
  -- it was seen for (gen_data: monster k, item c, object u, event e). Where only one line is of that kind and no slot
  -- of the catalog's could be it, the spots are that line's: they go once it is done, and say how far along it is.
  -- Two lines of a kind can't be told apart: their spots stay until the quest is complete. Each kind has its nearest
  -- mark before any has a second, as each slot of the catalog's does
  do
    local objs = { { text = "Gnoll slain: 10/10", type = "monster", need = 10, done = true },
                   { text = "Gnoll Paw: 2/8", type = "item", need = 8 }, { text = "Gnoll Tooth: 0/8", type = "item", need = 8 } }
    local z = QMm.Loose(objs, QMm.Spots("k,0,1429,1,1,0,g;c,0,1429,1,1,0,g;e,0,1429,1,1,0,g"))
    assert(z.k == objs[1] and z.c == nil and z.e == nil, "one kill line: the k spots'; two item lines: neither; no event line: none")
    z = QMm.Loose(objs, QMm.Spots("k,0,1429,1,1,0,g;k,1,1429,1,1,0,c,1"))
    assert(z.k == nil, "a slot of the catalog's could be the kill line: not guessed")
    z = QMm.Loose({ { text = "Something: 0/1", need = 1 }, objs[1] }, QMm.Spots("k,0,1429,1,1,0,g"))
    assert(z.k == nil, "a line whose kind the game doesn't say could be a kill: not guessed")
    MD.SREQ[7], MD.SPOT[7] = nil, "k,0,1429,300,300,15,g;k,0,1429,340,300,15,g;e,0,1429,700,700,15,g;e,0,1429,740,700,15,g"
    M.objectives[7] = { { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 },
                        { text = "Camp scouted: 0/1", type = "event", finished = false, numFulfilled = 0, numRequired = 1 } }
    MQ:Settings().pins = false
    redraw()
    local order, kill = {}, nil
    for _, d in ipairs(QMm:Build(1429)) do if d.kind == "obj" and d.id == 7 then order[#order + 1] = d.spot.kind end end
    for _, pin in ipairs(icons("obj")) do if pin.data.id == 7 and pin.data.spot.kind == "k" then kill = pin end end
    assert(table.concat(order) == "keke", "each kind its nearest mark first: " .. table.concat(order))
    assert(kill and tipOf(kill):find("%- Kobold Vermin slain: 3/10\n%- Camp scouted: 0/1\nKill here\nPosition: seen in players' games"),
      "the kills' spot says how far along they are, the game's lines first: " .. tipOf(kill))
    M.objectives[7][1] = { text = "Kobold Vermin slain: 10/10", type = "monster", finished = true, numFulfilled = 10, numRequired = 10 }
    redraw()
    local left = {}
    for _, pin in ipairs(icons("obj")) do if pin.data.id == 7 then left[#left + 1] = pin.data.spot.kind end end
    assert(table.concat(left) == "ee", "the kills done: only the event's spots stay")
    MD.SREQ[7], MD.SPOT[7] = "1:10,2:1", SPOT[7]
    M.objectives[7] = { { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 } }
    redraw()
    assert(marksFor(7) == 3, "back as it was")
  end

  -- an item slot is named by its item (D.SREQ's third field, an index into D.SN), not by what drops it: the masks
  -- (done, listed first) and the bandanas both ask for 12, and the spots are named for the Defias who drop them
  do
    MD.SN[11], MD.SN[12] = "Defias Thug", "Defias Footpad"
    MD.SPOT[18] = "c,5,1429,540,300,40,w,11;c,6,1429,560,320,0,g,12"
    MQ:Settings().pins = false
    redraw()
    assert(marksFor(18) == 2, "named for the creatures: a tie, so both keep showing")
    MD.SREQ[18] = "5:12:2,6:12:3"
    redraw()
    local left
    for _, pin in ipairs(icons("obj")) do if pin.data.id == 18 then left = pin end end
    assert(marksFor(18) == 1 and left.data.spot.slot == 5 and near(left, 0.54, 0.30) and left.data.line.text == "Red Burlap Bandana: 2/12",
      "the masks are done, told by their item's name: only the bandanas' spot")
    assert(tipOf(left):find("%- Red Burlap Bandana: 2/12\nLoot Defias Thug\n"), "its tooltip: the game's line, then who drops it: " .. tipOf(left))
    local list = QMm.Spots("c,5,1429,1,1,0,c,11;c,6,1429,1,1,0,c,12")
    local objs = { { text = "Defias Mask: 12/12", type = "item", need = 12, done = true }, { text = "Red Burlap Bandana: 2/12", type = "item", need = 12 } }
    local m = QMm.Match(objs, list, { [5] = 12, [6] = 12 }, { [5] = "Red Burlap Bandana", [6] = "Defias Mask" })
    assert(m[5] == objs[2] and m[6] == objs[1], "QM.Match takes the item names")
    MD.SPOT[18], MD.SREQ[18] = SPOT[18], "5:12,6:12"
    redraw()
  end

  -- a log too big for the cap: every ! and ? stays, each objective has its nearest mark first, the farthest marks go
  do
    local keep = MD.SPOT[7]
    local parts = {}
    for i = 1, 250 do parts[#parts + 1] = string.format("k,1,1429,%d,%d,20,c,1", 100 + (i % 10) * 70, 100 + math.floor(i / 10) * 30) end
    parts[#parts + 1] = "u,2,1429,450,380,0,g,4" -- the crate, last of 251
    MD.SPOT[7] = table.concat(parts, ";")
    MQ:Settings().pins = false
    local full = QMm:Build(1429)
    local n, crate = {}, false
    for _, d in ipairs(full) do
      n[d.kind] = (n[d.kind] or 0) + 1
      if d.kind == "obj" and d.spot.slot == 2 then crate = true end
    end
    local others = (n.give or 0) + (n.turn or 0) + (n.start or 0) + (n.dungeon or 0)
    assert(#full == 200 and n.give == #give and n.turn == 1 and n.start == 1 and n.obj == 200 - others and full.cut == 251 + 1 - n.obj,
      "at the cap: every !, ? and drop still there, the marks cut to what is left: " .. #full .. ", " .. tostring(full.cut))
    assert(crate, "the crate's mark comes in its turn, not after 250 kills")
    MD.SPOT[7] = keep
  end

  -- an older Data.lua (no D.QLOCK): the "Other quests" of the Classic database stand in for what QuestBank doesn't
  -- check (a profession, a book): no !
  local realLock = MD.QLOCK
  MD.QLOCK = nil
  do
    local gearing, kaldorei, zephras = MQ.Quest.Get(1618), MQ.Quest.Get(4161), MQ.Quest.Get(92514)
    assert(MQ:Status(gearing).code == "todo" and QMm.Unchecked(gearing) and QMm.Unchecked(kaldorei), "Gearing Redridge: todo, and unchecked")
    for _, m in ipairs({ gearing.give.m, kaldorei.give.m }) do
      for _, d in ipairs(QMm:Build(m)) do
        for _, q in ipairs(d.quests or {}) do assert(q.id ~= 1618 and q.id ~= 4161, "no ! for a profession's quest: " .. q.name) end
      end
    end
    assert(zephras and not QMm.Unchecked(zephras), "Forever's own quests keep theirs (Zephras Isle's on a card of their own)")
  end

  -- D.QLOCK (gen_data: the quests that need a profession's skill or a reputation) replaces that stand-in: a quest
  -- it lists gets no !, an "Other quest" it doesn't list gets its !. Read by quest id, as a list or as "id,id"
  do
    MQ:Settings().pins = false
    local gearing = MQ.Quest.Get(1618)
    local function offered(m, id)
      for _, d in ipairs(QMm:Build(m)) do
        for _, q in ipairs(d.quests or {}) do if d.kind == "give" and q.id == id then return true end end
        for _, q in ipairs(d.offers or {}) do if q.id == id then return true end end
      end
      return false
    end
    local gid = give[1].data.quests[1].id
    assert(offered(1429, gid) and not offered(gearing.give.m, 1618), "no D.QLOCK: the stand-in hides Gearing Redridge")
    MD.QLOCK = { [gid] = "s:202:1" }
    assert(not offered(1429, gid) and QMm.Unchecked(MQ.Quest.Get(gid)), "a quest D.QLOCK lists: no !")
    assert(offered(gearing.give.m, 1618) and not QMm.Unchecked(gearing), "with D.QLOCK the stand-in goes: an Other quest it doesn't list keeps its !")
    MD.QLOCK = { gid, 1618 }
    assert(not offered(1429, gid) and not offered(gearing.give.m, 1618) and not QMm.Unchecked(MQ.Quest.Get(7)), "D.QLOCK as a list of ids")
    MD.QLOCK = gid .. ",1618"
    assert(not offered(1429, gid) and not offered(gearing.give.m, 1618) and not QMm.Unchecked(MQ.Quest.Get(7)), "D.QLOCK as a string")
    MD.QLOCK = {}
    assert(offered(1429, gid) and offered(gearing.give.m, 1618), "an empty D.QLOCK locks nothing")
    MD.QLOCK = nil
    assert(offered(1429, gid) and QMm.Unchecked(gearing), "and without it, as before")
    -- gen_data's own, when this Data.lua has it: Gearing Redridge needs Blacksmithing
    if realLock then
      MD.QLOCK = realLock
      assert(realLock[1618] and QMm.Unchecked(gearing) and not offered(gearing.give.m, 1618), "Data.lua's D.QLOCK: Gearing Redridge is locked")
    end
  end
  MD.QLOCK = realLock

  -- where an NPC's place comes from: Data.lua's letter for it; without one, Classic, or Wowhead on a map new in Forever
  local realSrc = MD.NSRC
  do
    MD.NSRC = nil
    redraw()
    local e = icons("turn")[1]
    local idx = e.data.npc
    assert(e.data.title == "Eagan Peltskinner" and tipOf(e):find("Position: Classic data (may have moved in Forever)", 1, true), "no D.NSRC: Classic")
    MD.NSRC = { [idx] = "w" }
    assert(tipOf(e):find("Position: Wowhead Forever", 1, true), "D.NSRC says Wowhead")
    MD.NSRC = string.rep("c", idx - 1) .. "g"
    assert(tipOf(e):find("Position: seen in players' games", 1, true), "D.NSRC as a string of letters")
    MD.NSRC = nil
    local zi
    for i, rec in ipairs(MD.NPC) do if rec[2] == 2521 then zi = i break end end
    assert(zi and QMm.NpcSource({ npc = zi, m = 2521 }) == "w" and QMm.NpcSource({ npc = idx, m = 1429 }) == "c", "Zephras Isle: Wowhead's")
    -- gen_data's own, when this Data.lua has it: one letter for every NPC
    if realSrc then
      assert(type(realSrc) == "string" and #realSrc == #MD.NPC and not realSrc:find("[^wcg]"), "Data.lua's D.NSRC: one of w, c, g per NPC")
      MD.NSRC = realSrc
      assert(QMm.NpcSource({ npc = idx, m = 1429 }) == realSrc:sub(idx, idx), "and it is what the tooltip says")
    end
  end
  MD.NSRC = nil -- the tests below name their own

  -- the route's pins, at level 10: the NPC a pin stands on is theirs, and what the pin doesn't list goes on its
  -- tooltip; an NPC a step away (the Wanted Poster beside Deputy Rainer) keeps its own !; one at the very spot
  -- (Priestess Josetta where William Pestle stands) goes on the pin's tooltip, as her ! would lie under the pin
  do
    M.level = 10
    MQ:Settings().pins = false
    redraw()
    -- the icon an NPC is on (NPCs at the same spot share one), and that NPC's part of it
    local function iconOf(title)
      for _, pin in ipairs(icons()) do
        for _, w in ipairs(pin.data.who or {}) do if w.title == title then return pin, w end end
      end
    end
    local function routeOn(who) for _, pin in ipairs(routePins()) do if pin.data.who == who then return pin end end end
    local thomas, rainer, pestle = iconOf("Guard Thomas"), iconOf("Deputy Rainer"), iconOf("William Pestle")
    assert(thomas and #thomas.data.quests == 2 and rainer and pestle and iconOf("Wanted Poster") and iconOf("Priestess Josetta"), "level 10: the NPCs this needs")
    -- NPCs at the same spot share one icon (two would lie on top of each other, only the top one to hover): Priestess
    -- Josetta stands where William Pestle does, so one ! lists each of them with their own quests
    do
      local _, pw = iconOf("William Pestle")
      local jp, jw = iconOf("Priestess Josetta")
      assert(jp == pestle and #pestle.data.who == 2 and #pw.give > 0 and #jw.give > 0 and #pestle.data.quests == #pw.give + #jw.give
        and pestle.data.kind == "give", "Pestle and Josetta: one ! for both")
      local t = tipOf(pestle)
      assert(t:find("William Pestle\nAvailable [Qq]uests?\n") and t:find("Priestess Josetta\nAvailable [Qq]uests?\n") and t:find(jw.give[1].name, 1, true)
        and t:find(pw.give[1].name, 1, true), "its tooltip names each NPC with its quests: " .. t)
      local _, nPos = t:gsub("Position: ", "")
      assert(nPos == 1 and t:find("<Shift-click: add to my route>", 1, true), "one Position line when both places come from the same data")
      -- their places from different data: a line under each
      MD.NSRC = { [pw.npc] = "w", [jw.npc] = "c" } -- (none before this: one line above)
      t = tipOf(pestle)
      _, nPos = t:gsub("Position: ", "")
      assert(nPos == 2 and t:find("Available [Qq]uests?\n.-Position: Wowhead Forever\nPriestess Josetta", 1) and t:find("Position: Classic data", 1, true), "a Position line under each: " .. t)
      MD.NSRC = nil
      print("map icons, two NPCs at one spot:", (tipOf(pestle):gsub("\n", " | ")))
      -- Kobold Candles done and in the log: Pestle takes it, so their icon is a ?, Josetta's quests on it to pick up
      table.insert(M.log, { 60, 1 })
      redraw()
      local tp = iconOf("Priestess Josetta")
      t = tipOf(tp)
      assert(tp.data.kind == "turn" and tp.Glyph.__atlas == "UI-QuestIcon-TurnIn-Normal" and #tp.data.quests == 1 and tp.data.quests[1].id == 60 and #tp.data.offers >= #jw.give
        and t:find("William Pestle\nReady for turn%-in\n%[7%] Kobold Candles") and t:find("Priestess Josetta\nAvailable [Qq]uests?\n")
        and t:find("<Click to show it on the arrow for now>", 1, true) and t:find("<Shift%-click: skip this quest>"), "a ? at the spot, each NPC's part on it: " .. t)
      print("map icons, a ? and a ! at one spot:", (t:gsub("\n", " | ")))
      table.remove(M.log)
      redraw()
      -- the Stonefields' farm: Ma Stonefield and "Auntie" Bernice, 0.14 % apart, one icon too when both have quests
      local ma, bernice = iconOf("Ma Stonefield"), iconOf('"Auntie" Bernice Stonefield')
      assert(not (ma and bernice) or ma == bernice, "the Stonefields share an icon")
    end
    local other = thomas.data.quests[2]
    local _, pw = iconOf("William Pestle")
    local listed = { thomas.data.quests[1].id, rainer.data.quests[1].id, pw.give[1].id }
    for _, id in ipairs(listed) do MQ:ToggleAdd(id) end
    -- /qb pins: the icons follow without being told
    M.env.SlashCmdList.QUESTBANK("pins")
    assert(MQ:Settings().pins and routeOn("Guard Thomas") and not iconOf("Guard Thomas"), "/qb pins: Guard Thomas has the route's pin, and no icon")
    local tip = tipOf(routeOn("Guard Thomas"))
    assert(tip:find("Also to pick up here:", 1, true) and tip:find(other.name, 1, true), "what his pin doesn't list is on its tooltip: " .. tip)
    M.map:SetMapID(1415)
    assert(routeOn("Guard Thomas") and not tipOf(routeOn("Guard Thomas")):find("Also to", 1, true), "on the continent, where no icon draws, his pin says only its own")
    M.map:SetMapID(1429)
    assert(routeOn("Deputy Rainer") and iconOf("Wanted Poster") and not tipOf(routeOn("Deputy Rainer")):find("Wanted Poster", 1, true),
      "the Wanted Poster beside Deputy Rainer keeps its own !")
    assert(routeOn("William Pestle") and not iconOf("Priestess Josetta") and tipOf(routeOn("William Pestle")):find("Priestess Josetta, to pick up:", 1, true),
      "Priestess Josetta, at the very spot of William Pestle's pin: on its tooltip")
    M.env.SlashCmdList.QUESTBANK("pins")
    assert(not MQ:Settings().pins and #routePins() == 0 and iconOf("Guard Thomas") and iconOf("Priestess Josetta"), "/qb pins off: their icons are back")
    -- the Settings box: the same, untold
    MQ.UI:Open(5); MQ.UI:Refresh()
    local v = MQ.UI.views[5]
    v.pins:SetChecked(true); v.pins.__scripts.OnClick(v.pins, "LeftButton")
    assert(MQ:Settings().pins and not iconOf("Guard Thomas") and iconOf("Wanted Poster"), "the Settings box: route pins on, the icons follow")
    v.pins:SetChecked(false); v.pins.__scripts.OnClick(v.pins, "LeftButton")
    assert(not MQ:Settings().pins and iconOf("Guard Thomas"), "and off")
    MQ.UI.frame:Hide()
    for _, id in ipairs(listed) do MQ:ToggleAdd(id) end
    M.level = 3
    redraw()
    print(string.format("map icons, the route's pin on Guard Thomas: %s", (tip:gsub("\n", " | "))))
  end
end

----------------------------------------------------------------------------
-- players' objective spots (Discover.lua): where an objective of a quest in the log ticks, as the map and the
-- position in thousandths; a sighting within 15 of a point on the same map is that point; at most 8 points an
-- objective and 400 quests. The Forever client only, never in an instance, at the bank or mailbox, for an item made
-- at a crafting window, just after a loading screen or a quest came into the log, or when the client hides the
-- position; no names. gen_data shows them on the map as "seen in players' games"
----------------------------------------------------------------------------
do
  local M, MQ = maren, maren.QB
  local Dz = MQ.Discover
  local f = Dz.frame
  local DB = M.env.QuestBankDB
  local C = M.env.C_Map
  local savePos, saveBest = C.GetPlayerMapPosition, C.GetBestMapForUnit
  local px, py, map = 0.4, 0.5, 1429
  C.GetPlayerMapPosition = function(m, unit)
    assert(m == map and unit == "player", "the position on the map you are on")
    return { x = px, y = py, GetXY = function(self) return self.x, self.y end }
  end
  C.GetBestMapForUnit = function() return map end
  local function update(event, unit) f.__scripts.OnEvent(f, event or "QUEST_LOG_UPDATE", unit); tick(M, 0) end
  local kills = M.objectives[7][1]
  local have = 3
  local function kill() have = have + 1; kills.numFulfilled = have; kills.text = "Kobold Vermin slain: " .. have .. "/10" end
  local function spotsOf() return DB.disc.os end
  local function pts(id, i) local q = spotsOf() and spotsOf()[id]; return q and q[i] and q[i].p or {} end
  local function total() local n = 0; for _, q in pairs(spotsOf() or {}) do for _, o in pairs(q) do for _, p in ipairs(o.p) do n = n + p[4] end end end; return n end
  local errs0 = #(DB.errors or {})

  kills.numFulfilled, kills.finished = have, false
  update()
  assert(spotsOf() == nil or next(spotsOf()) == nil, "the first look only learns where things stand")
  tick(M, 4)
  update()
  assert(spotsOf() == nil or next(spotsOf()) == nil, "nothing moved: nothing noted")
  kill()
  update()
  local p = pts(7, 1)
  assert(spotsOf()[7][1].t == "monster" and #p == 1 and p[1][1] == 1429 and p[1][2] == 400 and p[1][3] == 500 and p[1][4] == 1,
    "a kill: noted where you stand, in thousandths of the map")
  -- a step away: the same point, now at the middle of its sightings; further: a point of its own; another map: another
  px = 0.41; kill(); update()
  p = pts(7, 1)
  assert(#p == 1 and p[1][2] == 405 and p[1][3] == 500 and p[1][4] == 2, "within 15 thousandths: the same point")
  px = 0.44; kill(); update()
  p = pts(7, 1)
  assert(#p == 2 and p[2][2] == 440 and p[2][4] == 1, "further off: a point of its own")
  map = 1453; px = 0.405; kill(); update()
  p = pts(7, 1)
  assert(#p == 3 and p[3][1] == 1453 and p[1][4] == 2, "the same place on another map is another point")
  map, px = 1429, 0.4
  -- many updates at once (a loot window): one look, one sighting
  kill()
  for _ = 1, 3 do f.__scripts.OnEvent(f, "QUEST_LOG_UPDATE") end
  f.__scripts.OnEvent(f, "UNIT_QUEST_LOG_CHANGED", "player")
  tick(M, 0)
  assert(pts(7, 1)[1][4] == 3, "four updates, one sighting")
  kill(); update("UNIT_QUEST_LOG_CHANGED", "player")
  assert(pts(7, 1)[1][4] == 4, "the log changing for you counts too")
  -- an item objective, as the game numbers its lines (the bandanas are its second); the masks didn't move
  local bandanas = M.objectives[18][2]
  bandanas.numFulfilled, bandanas.text = 3, "Red Burlap Bandana: 3/12"
  px, py = 0.54, 0.3
  update()
  assert(spotsOf()[18][2].t == "item" and #pts(18, 2) == 1 and pts(18, 2)[1][2] == 540 and spotsOf()[18][1] == nil, "an item looted: the game's second line")
  -- finished without a count (an area reached, an event): noted too
  M.objectives[7][2] = { text = "Camp scouted", type = "event", finished = false }
  update()
  assert(spotsOf()[7][2] == nil, "a new line: where it stands is learned first")
  M.objectives[7][2].finished = true
  update()
  assert(spotsOf()[7][2].t == "event" and #pts(7, 2) == 1, "the event done: noted")
  M.objectives[7][2] = nil
  -- a quest new to your log brings what you had already: not noted; nor what comes for it a look later (the server
  -- can send an item objective's count a moment after the quest); nor what comes just after it is accepted again
  table.insert(M.log, { 4242, 0 })
  M.objectives[4242] = { { text = "Linen Cloth: 5/10", type = "item", finished = false, numFulfilled = 5, numRequired = 10 } }
  update()
  assert(spotsOf()[4242] == nil, "a quest just taken: its progress so far isn't from here")
  table.insert(M.log, { 4244, 0 })
  M.objectives[4244] = { { text = "Wool Cloth: 0/10", type = "item", finished = false, numFulfilled = 0, numRequired = 10 } }
  update()
  tick(M, 1)
  M.objectives[4244][1].numFulfilled, M.objectives[4244][1].text = 6, "Wool Cloth: 6/10"
  update()
  assert(spotsOf()[4244] == nil, "its count a look after the quest: not from here either")
  tick(M, 4)
  f.__scripts.OnEvent(f, "QUEST_ACCEPTED", 4244)
  M.objectives[4244][1].numFulfilled = 7
  update()
  assert(spotsOf()[4244] == nil, "accepted again (abandoned in between): what it has now isn't from here")
  tick(M, 4)
  M.objectives[4244][1].numFulfilled = 8
  update()
  assert(#pts(4244, 1) == 1, "a moment later, a rise is")
  table.remove(M.log)
  M.objectives[4244] = nil
  -- less than before (an item sold or destroyed): nothing; back up again: noted
  M.objectives[4242][1].numFulfilled = 4; update()
  assert(spotsOf()[4242] == nil, "less: nothing")
  M.objectives[4242][1].numFulfilled = 5; update()
  assert(#pts(4242, 1) == 1, "more again: noted")
  table.remove(M.log)
  M.objectives[4242] = nil

  -- not where it was found: the bank, the mailbox, a trade; nor in an instance; nor where the client hides the place
  local n0 = total()
  M.env.MailFrame = { IsShown = function() return true end }
  kill(); update()
  M.env.MailFrame = nil
  MQ.bankOpen = true
  kill(); update()
  MQ.bankOpen = nil
  M.env.IsInInstance = function() return true, "party" end
  kill(); update()
  M.env.IsInInstance = function() return false, "none" end
  assert(total() == n0, "the mailbox, the bank, an instance: nothing noted")
  local asking = C.GetPlayerMapPosition
  C.GetPlayerMapPosition = function() return { x = px, y = py } end -- a place on any map, so only the map id is hidden
  C.GetBestMapForUnit = function() return SECRET.num() end
  kill(); update()
  C.GetBestMapForUnit = function() return nil end
  kill(); update()
  C.GetPlayerMapPosition = asking
  C.GetBestMapForUnit = function() return map end
  C.GetPlayerMapPosition = function() return SECRET.str() end
  kill(); update()
  C.GetPlayerMapPosition = function() return nil end
  kill(); update()
  C.GetPlayerMapPosition = function() return { x = SECRET.num(), y = 0.5 } end
  kill(); update()
  C.GetPlayerMapPosition = function() return { x = 0, y = 0 } end
  kill(); update()
  assert(total() == n0, "a hidden map or position, or none: nothing noted, and no error")
  -- the client hides the objectives themselves: nothing, no error; once they show again they are a fresh start
  C.GetPlayerMapPosition = function() return { x = px, y = py } end
  kills.numFulfilled = SECRET.num(); update()
  kills.numFulfilled = have; update()
  assert(total() == n0, "hidden counts: nothing noted")
  kill(); update()
  assert(total() == n0 + 1, "and counted again once they show")
  M.env.IsInInstance = nil
  -- a hidden "finished" is not "not finished": the line showing finished again, with nothing done, is no progress
  M.objectives[7][2] = { text = "Camp scouted", type = "event", finished = true }
  update()
  M.objectives[7][2].finished = SECRET.bool(); update()
  M.objectives[7][2].finished = true; update()
  assert(total() == n0 + 1, "finished, hidden, finished again: nothing noted")
  M.objectives[7][2].finished = SECRET.bool(); update()
  M.objectives[7][2].finished = false; update()
  M.objectives[7][2].finished = true; update()
  assert(total() == n0 + 2, "not finished, then finished: noted")
  M.objectives[7][2] = nil

  -- what you make is not found where you stand: an item objective that ticks with a crafting window open, or a moment
  -- after it shut or after a craft was cast ("create all" can go on with the window shut), is not noted. A kill
  -- meanwhile is; so is an item bought (the vendor is where it is got), or one that comes after a spell that makes
  -- nothing (a fish, an herb, a hide are found where you stand)
  table.insert(M.log, { 4245, 0 })
  local bandage = { text = "Linen Bandage: 0/10", type = "item", finished = false, numFulfilled = 0, numRequired = 10 }
  M.objectives[4245] = { bandage }
  update()
  tick(M, 4)
  local function make() bandage.numFulfilled = bandage.numFulfilled + 1; update() end
  local function cast(spell) f.__scripts.OnEvent(f, "UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-" .. spell, spell) end
  local n1 = total()
  local window = { IsShown = function() return true end }
  M.env.ProfessionsFrame = window
  M.env.C_TradeSkillUI = { GetRecipeInfo = function(spell) return spell == 3275 and { recipeID = 3275 } or nil end }
  f.__scripts.OnEvent(f, "TRADE_SKILL_SHOW")
  tick(M, 6)
  make()
  assert(total() == n1, "made at the crafting window: nothing noted")
  kill(); update()
  assert(total() == n1 + 1, "a kill with the window open: noted")
  cast(3275) -- Linen Bandage, made at the window
  cast(133) -- a spell cast with the window open that makes nothing: no recipe
  tick(M, 6)
  window.IsShown = function() return false end
  f.__scripts.OnEvent(f, "TRADE_SKILL_CLOSE")
  tick(M, 1); make()
  assert(total() == n1 + 1, "made as the window shut: nothing noted")
  tick(M, 6)
  cast(3275) -- create all goes on, the window shut
  tick(M, 1); make()
  assert(total() == n1 + 1, "made with the window shut: nothing noted")
  tick(M, 6)
  f.__scripts.OnEvent(f, "UNIT_SPELLCAST_SUCCEEDED", "player", "Cast-hidden", SECRET.num()) -- a cast the client hides
  cast(133)
  tick(M, 1); make()
  assert(total() == n1 + 2, "after a spell that makes nothing: noted")
  M.env.ProfessionsFrame = nil
  M.env.MerchantFrame = { IsShown = function() return true end }
  make()
  assert(total() == n1 + 3, "bought: noted, at the vendor")
  M.env.MerchantFrame = nil
  M.env.TradeSkillFrame = { IsShown = function() return true end }
  make()
  assert(total() == n1 + 3, "the Classic crafting window too")
  M.env.TradeSkillFrame, M.env.C_TradeSkillUI = nil, nil
  table.remove(M.log)
  M.objectives[4245] = nil

  -- no names: a kind and numbers, nothing else
  for id, q in pairs(spotsOf()) do
    assert(type(id) == "number", "by quest id")
    for i, o in pairs(q) do
      assert(type(i) == "number" and (o.t == nil or ({ monster = true, item = true, object = true, event = true })[o.t]), "the game's kind of objective")
      for k in pairs(o) do assert(k == "t" or k == "p", "only t and p: " .. tostring(k)) end
      for _, pt in ipairs(o.p) do
        assert(#pt == 4, "map, x, y, sightings")
        for _, v in ipairs(pt) do assert(type(v) == "number" and v == math.floor(v), "whole numbers") end
        assert(pt[2] >= 0 and pt[2] <= 1000 and pt[3] >= 0 and pt[3] <= 1000, "in thousandths")
      end
    end
  end

  -- at most 8 points an objective: a ninth place puts out the oldest of those seen fewest times; once every point
  -- was seen more than once, a new place is the one left out
  for i = 1, 8 do Dz.NoteSpot(4243, 1, "monster", 1429, i * 100, 100) end
  Dz.NoteSpot(4243, 1, "monster", 1429, 205, 100) -- the second place, seen twice
  Dz.NoteSpot(4243, 1, "monster", 1429, 950, 950)
  p = pts(4243, 1)
  assert(#p == 8 and p[1][2] == 203 and p[1][4] == 2 and p[2][2] == 300 and p[8][2] == 950, "the first place (seen once) went for the ninth")
  for _, pt in ipairs(p) do if pt[4] == 1 then Dz.NoteSpot(4243, 1, "monster", pt[1], pt[2], pt[3]) end end
  assert(Dz.NoteSpot(4243, 1, "monster", 1429, 50, 900) == nil and #pts(4243, 1) == 8, "every point seen twice: the new place is left out")
  -- at most 400 quests: the one touched longest ago goes
  local function count(t) local n = 0; for _ in pairs(t) do n = n + 1 end; return n end
  for id = 500001, 500400 do Dz.NoteSpot(id, 1, "item", 1429, 10, 10) end
  assert(count(spotsOf()) == 400 and spotsOf()[7] == nil and spotsOf()[4243] == nil and spotsOf()[500001], "400 quests: the oldest went")
  Dz.NoteSpot(500001, 1, "item", 1429, 10, 10)
  Dz.NoteSpot(500401, 1, "item", 1429, 10, 10)
  assert(count(spotsOf()) == 400 and spotsOf()[500001] and spotsOf()[500002] == nil and spotsOf()[500401], "touched again, it stays; the next oldest goes")
  assert(count(DB.disc.osAt) == 400, "and nothing is kept for a quest that went")
  print(string.format("objective spots: %d quests kept, %d points for the last", count(spotsOf()), #pts(500401, 1)))
  assert(#(DB.errors or {}) == errs0, "objective spots: no errors, " .. tostring(((DB.errors or {})[errs0 + 1] or {}).msg))
  DB.disc.os, DB.disc.osAt, DB.disc.osN = nil, nil, nil
  C.GetPlayerMapPosition, C.GetBestMapForUnit = savePos, saveBest
  kills.numFulfilled, kills.text, kills.finished = 3, "Kobold Vermin slain: 3/10", false
  bandanas.numFulfilled, bandanas.text = 2, "Red Burlap Bandana: 2/12"
end

-- a fresh login: for its first seconds the log only learns where things stand (the server fills objectives in
-- after the quest list); then a kill is noted
do
  local tam = newClient({
    name = "Tamsin", level = 3, cap = 60, faction = "Alliance", className = "Mage", class = "MAGE", classID = 8, race = "Human",
    log = { { 7, 0 } }, done = { [783] = true }, group = false, guild = false, world = { 0, -8914, -133 }, bind = "Northshire Abbey",
    riding = false, bagSlots = {}, xp = 100, map = 1429,
  })
  tam.objectives = { [7] = { { text = "Kobold Vermin slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } } }
  tam.ev(tam.QB.eventFrame, "ADDON_LOADED", "QuestBank")
  tam.ev(tam.QB.eventFrame, "PLAYER_LOGIN")
  local f = tam.QB.Discover.frame
  local function update() f.__scripts.OnEvent(f, "QUEST_LOG_UPDATE"); tick(tam, 1) end
  update()
  tam.objectives[7][1].numFulfilled = 4
  update()
  local d = tam.env.QuestBankDB.disc
  assert(d.os == nil or next(d.os) == nil, "just logged in: the counts the server sends now are no progress")
  tick(tam, 15)
  tam.objectives[7][1].numFulfilled = 5
  update()
  assert(d.os and d.os[7] and d.os[7][1].p[1][1] == 1429 and d.os[7][1].p[1][2] == 660 and d.os[7][1].p[1][3] == 620, "settled: a kill is noted")
end

-- a slow load: the loading screen outlasts those first seconds, so the wait starts again when the world shows; and
-- every loading screen after it (a boat, a portal: the server can send the objectives anew) starts it again
do
  local tove = newClient({
    name = "Tove", level = 3, cap = 60, faction = "Alliance", className = "Mage", class = "MAGE", classID = 8, race = "Human",
    log = { { 7, 0 } }, done = { [783] = true }, group = false, guild = false, world = { 0, -8914, -133 }, bind = "Northshire Abbey",
    riding = false, bagSlots = {}, xp = 100, map = 1429,
  })
  local line = { text = "Kobold Vermin slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 }
  tove.objectives = { [7] = { line } }
  tove.ev(tove.QB.eventFrame, "ADDON_LOADED", "QuestBank")
  tove.ev(tove.QB.eventFrame, "PLAYER_LOGIN")
  local f = tove.QB.Discover.frame
  local function on(event, ...) f.__scripts.OnEvent(f, event, ...) end
  local function update() on("QUEST_LOG_UPDATE"); tick(tove, 1) end
  local d = tove.env.QuestBankDB.disc
  local function noted() local p = d.os and d.os[7] and d.os[7][1] and d.os[7][1].p[1]; return p and p[4] or 0 end
  on("PLAYER_ENTERING_WORLD", true, false)
  update()
  tick(tove, 12) -- still loading
  on("LOADING_SCREEN_DISABLED")
  line.numFulfilled = 4
  update()
  assert(noted() == 0, "a slow load: the counts that come as the world shows are no progress")
  tick(tove, 11)
  line.numFulfilled = 5
  update()
  assert(noted() == 1, "then a kill is noted")
  on("PLAYER_ENTERING_WORLD", false, false)
  line.numFulfilled = 6
  update()
  assert(noted() == 1, "just through a loading screen: not noted")
  tick(tove, 11)
  line.numFulfilled = 7
  update()
  assert(noted() == 2, "a moment later: noted again")
  assert(#(tove.env.QuestBankDB.errors or {}) == 0, "loading screens: no errors")
end

-- Classic Era: nothing noted (gen_data shows these as Forever's)
do
  local c = sigrun
  local f = c.QB.Discover.frame
  c.log = { { 7, 0 } }
  c.objectives = { [7] = { { text = "Kobold Vermin slain: 3/10", type = "monster", finished = false, numFulfilled = 3, numRequired = 10 } } }
  f.__scripts.OnEvent(f, "QUEST_LOG_UPDATE"); tick(c, 0)
  c.objectives[7][1].numFulfilled = 4
  f.__scripts.OnEvent(f, "QUEST_LOG_UPDATE"); tick(c, 0)
  c.QB.Discover.Look(); c.objectives[7][1].numFulfilled = 5; c.QB.Discover.Look()
  assert(c.env.QuestBankDB.disc.os == nil, "Classic Era: no objective spots")
  c.log, c.objectives = {}, nil
end

-- the Horde shaman in the Barrens sees no Alliance quests; the owner in Stormwind, how long a full redraw takes
do
  local H = horde.QB
  horde.map.id = 1413
  H:Settings().pins = false
  H:Recompute(true); H.Model.Finish(); H.Pins:Update(); H.QuestMap:Update()
  local n = 0
  for _, pin in ipairs(ours(horde, "QuestBankQuestPinTemplate")) do
    for _, q in ipairs(pin.data.quests or {}) do assert(q.side ~= 1, "no Alliance quest on the Horde's map: " .. q.name) end
    n = n + 1
  end
  assert(n > 0, "the Horde has icons in the Barrens")
  print("map icons, the Barrens for the Horde shaman:", n)
  local O = owner.QB
  owner.map.id = 1453
  local t0 = owner.env.debugprofilestop()
  for _ = 1, 10 do O.QuestMap.provider:RefreshAllData() end
  print(string.format("map icons, Stormwind for the owner: %d icons, %.1f ms a redraw", #ours(owner, "QuestBankQuestPinTemplate"), (owner.env.debugprofilestop() - t0) / 10))
  -- the real data, whatever gen_data has written so far: every map with a spot draws without an error
  local D0 = O.Data
  if D0.SPOT then
    local maps, spots = {}, 0
    for _, str in pairs(D0.SPOT) do for _, sp in ipairs(O.QuestMap.Spots(str) or {}) do maps[sp.m] = true; spots = spots + 1 end end
    for _, str in pairs(D0.START or {}) do for _, sp in ipairs(O.QuestMap.Spots(str) or {}) do maps[sp.m] = true; spots = spots + 1 end end
    local drawn = 0
    for m in pairs(maps) do drawn = drawn + #O.QuestMap:Build(m) end
    print(string.format("map icons, real data: %d spots on %d maps; %d icons for the owner", spots, (function() local k = 0 for _ in pairs(maps) do k = k + 1 end return k end)(), drawn))
  end
end

-- 5.4: the camp bar's campfire (Cooking's Basic Campfire, or a kit) and the missing-buffs banner when you leave a town
do
  local Camp, env, D = owner.QB.Camp, owner.env, owner.QB.Data
  c = owner
  c.combat = false
  local f = Camp.frame
  local function ev(e, ...) f.__scripts.OnEvent(f, e, ...) end
  local function ic(k) return env["QuestBankCamp_" .. k] end
  local function btn(i) return env["QuestBankBuff_" .. i] end
  local function said() return owner.chat[#owner.chat] or "" end
  local saveBags, saveClass = owner.o.bagSlots, owner.o.class
  local saveTex, saveCD, saveInst = env.C_Spell.GetSpellTexture, env.C_Spell.GetSpellCooldown, env.IsInInstance
  env.C_Spell.GetSpellTexture = function(id) return ({ [818] = 135805, [1460] = 135932 })[id] or 134400 end
  local spellCD = {}
  env.C_Spell.GetSpellCooldown = function(id) local s = spellCD[id]; return { startTime = s or 0, duration = s and 300 or 0, isEnabled = true, modRate = 1 } end
  -- the camp features' shared hour from the camp bar's own test runs out first
  tick(owner, Camp.QUIET + 3600)
  local SMITH = { { "Blacksmithing", 150 }, { "Alchemy", 10 }, { "Fishing", 0 }, { "Cooking", 60 }, { "First Aid", 30 } }
  assert(Camp.FIRE_SPELL == 818 and Camp.WOOD == 4470 and D.CAMP[Camp.BASIC_KIT] and D.CAMP[Camp.BASIC_KIT].t == "kit", "Basic Campfire, Simple Wood, the Basic Campfire Kit")
  -- every class's buffs: names, an icon, ranks lowest first, each id once
  local ids = {}
  for class, list in pairs(Camp.SELF) do
    for _, entry in ipairs(list) do
      for _, sp in ipairs(entry) do
        assert(type(sp[1]) == "string" and type(sp[2]) == "number" and #sp[3] > 0, "a buff: " .. class)
        for _, id in ipairs(sp[3]) do assert(not ids[id], "each rank once: " .. id); ids[id] = true end
      end
    end
  end
  assert(not Camp.SELF.WARRIOR and not Camp.SELF.ROGUE, "Battle Shout is short: nothing for a warrior or a rogue")

  -- (a) the fire: a cook who knows Basic Campfire, with Simple Wood and the sharpening wheel to place, no kit
  c.profs, c.known, c.buffs = SMITH, { [818] = true }, {}
  owner.o.bagSlots = { { 279944, 1 }, { 4470, 3 } }
  ev("PLAYER_ENTERING_WORLD")
  local fire, camp = ic("fire"), ic("camp")
  assert(fire:IsShown() and fire:GetAttribute("type") == "spell" and fire:GetAttribute("spell") == 818 and fire:GetAttribute("item") == nil,
    "Basic Campfire known: a click casts the spell")
  assert(fire.icon.__tex == 135805 and fire.count:GetText() == "3" and fire.state.lit and fire.state.tip[2] == "Click to light a campfire.",
    "the spell's own icon, the Simple Wood, lit while the wheel waits for a fire")
  assert(camp:IsShown() and camp:GetAttribute("item") == "item:279944" and not camp.state.lit, "the wheel, waiting")
  spellCD[818] = env.GetTime() - 60
  Camp.Refresh()
  assert(fire.state.cd and fire.cd.__cd[2] == 300 and fire.time:GetText() == "4m" and not fire.state.lit, "the spell's own cooldown: four minutes left, not lit")
  spellCD[818] = nil
  ev("UNIT_SPELLCAST_SUCCEEDED", "player", nil, 818)
  assert(camp.state.lit and not fire.state.lit, "the fire cast: the wheel lights up, the fire doesn't")
  owner.o.bagSlots = { { 279944, 1 } }
  Camp.Refresh()
  assert(fire.state.grey and fire.state.tip[2] == "Needs Simple Wood.", "no Simple Wood: grey")
  -- a kit too: the kit, a feature waiting or not (a kit's fire holds camp features; on Forever the kit is the fire)
  owner.o.bagSlots = { { 279944, 1 }, { 4470, 3 }, { 279981, 2 } }
  Camp.Refresh()
  assert(fire:GetAttribute("type") == "item" and fire:GetAttribute("item") == "item:279981" and fire:GetAttribute("spell") == nil, "a feature to place: the kit")
  owner.o.bagSlots = { { 4470, 3 }, { 279981, 2 } }
  Camp.Refresh()
  assert(fire:GetAttribute("type") == "item" and fire:GetAttribute("item") == "item:279981" and fire:GetAttribute("spell") == nil, "nothing to place: the kit still")
  c.known = {}
  Camp.Refresh()
  assert(fire:GetAttribute("type") == "item" and fire:GetAttribute("item") == "item:279981" and fire.count:GetText() == "2", "the spell unknown: the kit, as before")
  -- a feature to place and no way to light a fire: grey, with where a kit comes from, no click
  owner.o.bagSlots = { { 279944, 1 } }
  Camp.Refresh()
  assert(fire:IsShown() and fire.state.grey and fire:GetAttribute("type") == nil and fire.state.tip[1] == "No campfire kit"
    and fire.state.tip[2]:find("Simple Wood", 1, true), "no kit, no spell: grey, saying how to get one")
  owner.o.bagSlots = {}
  Camp.Refresh()
  assert(not fire:IsShown(), "nothing to place, nothing to light: no fire icon")
  -- in a fight the click stays as it was; after it, the new one
  c.known, owner.o.bagSlots = { [818] = true }, { { 4470, 3 } }
  Camp.Refresh()
  c.combat = true; ev("PLAYER_REGEN_DISABLED")
  owner.o.bagSlots = { { 279981, 1 } }; c.known = {}
  Camp.Refresh()
  assert(fire:GetAttribute("type") == "spell" and fire:GetAttribute("spell") == 818, "in a fight the fire's click stays")
  c.combat = false; ev("PLAYER_REGEN_ENABLED")
  assert(fire:GetAttribute("type") == "item" and fire:GetAttribute("item") == "item:279981" and fire:GetAttribute("spell") == nil, "after the fight: the kit")

  -- (b) the banner: a mage who knows two ranks of Arcane Intellect, ribs in the bag, nothing on, in town
  owner.o.class, c.profs, c.buffs = "MAGE", nil, {}
  c.known = { [1459] = true, [1460] = true }
  owner.o.bagSlots = { { 2888, 5 } }
  c.resting = true
  ev("PLAYER_ENTERING_WORLD")
  local shows = Camp.shows
  c.resting = false; ev("PLAYER_UPDATE_RESTING")
  local B = env.QuestBankBuffBanner
  assert(B and B:IsShown() and Camp.shows == shows + 1 and B.title:GetText() == "Missing buffs", "left town without buffs: the banner")
  assert(btn(1):IsShown() and btn(1):GetAttribute("type") == "item" and btn(1):GetAttribute("item") == "item:2888" and btn(1).count:GetText() == "5",
    "Well Fed missing: the ribs, a click eats one")
  assert(btn(2):IsShown() and btn(2):GetAttribute("type") == "spell" and btn(2):GetAttribute("spell") == 1460 and btn(2):GetAttribute("unit") == "player"
    and btn(2):GetAttribute("item") == nil and btn(2).icon.__tex == 135932, "Arcane Intellect missing: the highest rank known, cast on yourself, its own icon")
  assert(not (btn(3) and btn(3):IsShown()), "two icons")
  for _, pr in ipairs(checkLayout(B, "Missing buffs banner")) do problems[#problems + 1] = pr end
  layouts[#layouts + 1] = dumpLayout(B, "Missing buffs banner")
  ev("PLAYER_UPDATE_RESTING")
  assert(Camp.shows == shows + 1, "the same departure: once")
  -- a buff cast takes its icon away; all on, the banner goes
  c.buffs = { "Arcane Intellect" }
  ev("UNIT_AURA", "player")
  assert(B:IsShown() and btn(1):GetAttribute("item") == "item:2888" and not btn(2):IsShown(), "Arcane Intellect on: only the food is left")
  c.buffs = { "Well Fed", "Arcane Intellect" }
  ev("UNIT_AURA", "player")
  assert(not B:IsShown(), "everything on: the banner goes")
  -- the next departure, after the quiet minute: up, and gone after 12 seconds
  c.buffs = {}
  tick(owner, Camp.QUIET + 1)
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(B:IsShown() and Camp.shows == shows + 2, "the next departure: the banner again")
  tick(owner, Camp.BANNER_SECS - 1)
  assert(B:IsShown() and B.left:GetWidth() < B:GetWidth() / 4, "after 11 s: still up, its time line nearly run out")
  tick(owner, 1.5)
  assert(not B:IsShown(), "after 12 s: gone")
  -- a town's edge crossed back and forth: not again within the minute
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(not B:IsShown() and Camp.shows == shows + 2, "within the minute: not again")
  -- /qb buffs: any time; its X closes it
  env.SlashCmdList.QUESTBANK("buffs")
  assert(B:IsShown() and Camp.shows == shows + 3 and btn(2):GetAttribute("spell") == 1460, "/qb buffs shows it")
  B.close.__scripts.OnClick(B.close, "LeftButton")
  assert(not B:IsShown(), "the X closes it")
  -- not in a fight: after it, within the minute
  tick(owner, Camp.QUIET + 1)
  c.combat = true; ev("PLAYER_REGEN_DISABLED")
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(not B:IsShown() and Camp.shows == shows + 3, "left town in a fight: no banner")
  local n = #owner.chat
  env.SlashCmdList.QUESTBANK("buffs")
  assert(not B:IsShown() and #owner.chat == n + 1 and said():find("Not in a fight", 1, true), "/qb buffs in a fight: says so")
  c.combat = false; ev("PLAYER_REGEN_ENABLED")
  assert(B:IsShown() and Camp.shows == shows + 4, "the fight over: the banner, once")
  -- a fight while it is up: dimmed, its buttons left alone, gone when the fight is over
  c.combat = true; ev("PLAYER_REGEN_DISABLED")
  tick(owner, Camp.BANNER_SECS + 1)
  assert(B:IsShown() and B:GetAlpha() < 1 and btn(2):GetAttribute("spell") == 1460, "in a fight: dimmed, kept")
  c.combat = false; ev("PLAYER_REGEN_ENABLED")
  assert(not B:IsShown(), "the fight over: gone")
  -- not in a dungeon
  tick(owner, Camp.QUIET + 1)
  env.IsInInstance = function() return true, "party" end
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(not B:IsShown() and Camp.shows == shows + 4, "in a dungeon: no banner")
  env.IsInInstance = saveInst
  -- everything on: nothing to say
  c.buffs = { "Well Fed", "Arcane Brilliance" }
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(not B:IsShown() and Camp.shows == shows + 4, "all on (Arcane Brilliance counts): no banner")
  n = #owner.chat
  env.SlashCmdList.QUESTBANK("buffs")
  assert(not B:IsShown() and said():find("No buffs missing.", 1, true), "/qb buffs with all on: says so")
  -- the switch in Settings
  c.buffs = {}
  local v5 = owner.QB.UI.views[5]
  owner.QB.UI:Open(5)
  assert(v5.remind.buffs and v5.remind.buffs:GetChecked() and v5.remind.buffs.label:GetText() == "Tell me when I leave town without my buffs", "the switch, on")
  v5.remind.buffs:SetChecked(false); v5.remind.buffs.__scripts.OnClick(v5.remind.buffs, "LeftButton")
  assert(owner.QB:Settings().remind.buffs == false, "switched off")
  c.resting = true; ev("PLAYER_UPDATE_RESTING"); c.resting = false; ev("PLAYER_UPDATE_RESTING")
  assert(not B:IsShown() and Camp.shows == shows + 4, "switched off: no banner")
  v5.remind.buffs:SetChecked(true); v5.remind.buffs.__scripts.OnClick(v5.remind.buffs, "LeftButton")
  -- the armor: Ice Armor before Frost Armor; the one last seen on you first; any rank, by name or id
  c.known = { [1459] = true, [168] = true, [7300] = true, [7302] = true, [6117] = true }
  local m = Camp.SelfMissing({}, {})
  assert(#m == 2 and m[1].id == 1459 and m[2].id == 7302 and m[2].name == "Ice Armor", "the armor: Ice Armor first")
  c.buffs = { "Mage Armor" }; Camp.Refresh(); c.buffs = {}
  m = Camp.SelfMissing({}, {})
  assert(m[2].id == 6117 and m[2].name == "Mage Armor", "the armor last seen on you: Mage Armor")
  assert(#Camp.SelfMissing({}, { [10157] = true }) == 1 and #Camp.SelfMissing({ ["Frost Armor"] = true }, {}) == 1, "any rank counts, by name or by spell id")
  owner.o.class, c.known = "WARRIOR", {}
  assert(#Camp.SelfMissing({}, {}) == 0, "a warrior: no class buffs")
  -- a camp feature ready and no fire near: the click lights the kit, then places the feature
  owner.o.bagSlots, c.profs, c.buffs = { { 279944, 1 }, { 279981, 1 } }, SMITH, { "Well Fed" }
  tick(owner, 301)
  env.SlashCmdList.QUESTBANK("buffs")
  assert(B:IsShown() and btn(1):GetAttribute("item") == "item:279981" and btn(1).state.tip[1] == "Sharpening Wheel" and btn(1).state.tip[2] == "Needs a campfire first."
    and not btn(2):IsShown(), "the wheel ready, no fire: the kit first")
  ev("UNIT_SPELLCAST_SUCCEEDED", "player", nil, D.CAMP[279981].sp)
  assert(B:IsShown() and btn(1):GetAttribute("item") == "item:279944" and btn(1).state.tip[3] == "Click to place it.", "the fire lit: the wheel")
  for _, pr in ipairs(checkLayout(B, "Missing buffs banner, one icon")) do problems[#problems + 1] = pr end
  -- the wheel's aura is its buff's own spell, Extra Strength: the feature's name on you is no buff
  assert(D.CAMP[279944].b == 1230172 and D.CAMP[279944].bn == "Extra Strength" and D.CAMP[279955].b == 1230172, "the wheel's buff, and the Master Forge's (its base)")
  c.buffs = { "Well Fed", "Sharpening Wheel" }
  ev("UNIT_AURA", "player")
  assert(B:IsShown() and btn(1):GetAttribute("item") == "item:279944", "an aura named after the wheel is not its buff")
  c.buffs = { "Well Fed", "Extra Strength" }
  ev("UNIT_AURA", "player")
  assert(not B:IsShown(), "the wheel's buff on: gone")
  -- a feature that gives no buff (the Repair Bot: repairs and reagents) is no missing buff
  assert(D.CAMP[279949] and not D.CAMP[279949].b, "the Repair Bot gives no aura")
  owner.o.bagSlots, c.profs, c.buffs = { { 279949, 1 }, { 279981, 1 } }, { { "Engineering", 150 } }, { "Well Fed" }
  tick(owner, Camp.QUIET + 3601)
  env.SlashCmdList.QUESTBANK("buffs")
  assert(not B:IsShown() and said():find("No buffs missing.", 1, true), "an engineer's Repair Bot: nothing missing")
  -- the Expert Campfire Kit ("Builds an expert campfire") is a kit too: the fire icon uses it
  assert(D.CAMP[279974] and D.CAMP[279974].t == "kit" and D.CAMP[279974].cap == 10 and D.CAMP[279974].sp == 1307237, "the Expert Campfire Kit")
  owner.o.bagSlots, c.profs = { { 279974, 2 } }, { { "Cooking", 225 } }
  Camp.Refresh()
  assert(ic("fire"):IsShown() and ic("fire"):GetAttribute("item") == "item:279974" and ic("fire").count:GetText() == "2", "an Expert Campfire Kit on the fire icon")
  owner.o.bagSlots, owner.o.class, c.profs, c.known, c.buffs, c.resting = saveBags, saveClass, nil, nil, nil, nil
  env.C_Spell.GetSpellTexture, env.C_Spell.GetSpellCooldown = saveTex, saveCD
  Camp.Refresh()
  print(string.format("camp bar and banner: Basic Campfire and kits on the fire icon; the banner %d times, %d classes with buffs", Camp.shows, (function() local k = 0 for _ in pairs(Camp.SELF) do k = k + 1 end return k end)()))
end

----------------------------------------------------------------------------
-- the quest survey (Survey.lua): out of combat and outside instances QuestBank asks the game about the quests of
-- D.SURVEY by id, two a second, and uses what it tells at once. A level-50 rogue on the Forever client; the server
-- below knows a Forever quest no list has (99999, the Shimmerwine Shanker, item 276903, level 52), a catalog quest
-- nobody knew the rewards of (10), a quest whose rewards come late, one with none; it says no to 99001 and never
-- answers 99004, and knows nothing of 80001
----------------------------------------------------------------------------
local function d0(c) return c.env.QuestBankDB.disc end
local function deepCopy(t)
  if type(t) ~= "table" then return t end
  local o = {}
  for k, v in pairs(t) do o[k] = deepCopy(v) end
  return o
end
-- the server's quests on a client, and the client's calls about them by id. c.server[id] = { t, lvl, xp, money, c, r,
-- late = reads before the rewards are all there, fail = the server says no, silent = it never answers, sync = the
-- answer comes inside the call, cached = the client has the quest already, noIds = its reward slots never give an id }
local function surveyClient(c, server)
  local env = c.env
  c.server, c.loadedQ, c.qAsked, c.wrongTime = server, {}, {}, {}
  for id, s in pairs(server) do if s.cached then c.loadedQ[id] = true end end
  local function known(id) return c.loadedQ[id] and c.server[id] or nil end
  env.HaveQuestData = function(id) return c.loadedQ[id] and true or false end
  env.C_QuestLog.RequestLoadQuestByID = function(id)
    -- (counted, not asserted: the survey's pcall would swallow an error here)
    local inside = env.IsInInstance and env.IsInInstance()
    if c.combat or inside then c.wrongTime[#c.wrongTime + 1] = "asked " .. id end
    local ask = { id = id, t = c.clock }
    c.qAsked[#c.qAsked + 1] = ask
    local s = c.server[id]
    if s and s.silent then return end
    local ok = s ~= nil and not s.fail
    if ok then c.loadedQ[id] = true end
    local function reply()
      ask.back = c.clock
      local f = c.QB.Survey.frame
      f.__scripts.OnEvent(f, "QUEST_DATA_LOAD_RESULT", id, ok)
    end
    -- data the client has answers inside the call (the event is synchronous); the rest a moment later
    if s and s.sync then reply() else env.C_Timer.After(0.2, reply) end
  end
  env.C_QuestLog.GetTitleForQuestID = function(id) local s = known(id); return s and s.t end
  env.C_QuestLog.GetQuestDifficultyLevel = function(id) local s = known(id); return s and s.lvl or 0 end
  env.HaveQuestRewardData = function(id)
    -- (it can ask the server for the rewards: never in a fight or an instance)
    if c.combat or (env.IsInInstance and env.IsInInstance()) then c.wrongTime[#c.wrongTime + 1] = "read " .. id end
    local s = known(id)
    if not s then return false end
    if (s.late or 0) > 0 then s.late = s.late - 1; return false end
    return true
  end
  env.GetNumQuestLogChoices = function(id) local s = known(id); return s and #(s.c or {}) or 0 end
  env.GetNumQuestLogRewards = function(id) local s = known(id); return s and #(s.r or {}) or 0 end
  env.GetQuestLogChoiceInfo = function(i, id)
    local s = known(id); local item = s and s.c[i]
    if item then return "Item " .. item, 133328, 1, 2, true, (not s.noIds) and item or nil end
  end
  env.GetQuestLogRewardInfo = function(i, id)
    local s = known(id); local item = s and s.r[i]
    if item then return "Item " .. item, 133328, 1, 2, true, item end
  end
  local logXP = env.GetQuestLogRewardXP
  env.GetQuestLogRewardXP = function(id) local s = known(id); if s then return s.xp or 0 end return logXP(id) end
  env.GetQuestLogRewardMoney = function(id) local s = known(id); return s and s.money or 0 end
  -- what the finder needs of an item without its cache: a dagger, leather and cloth chests, a leather belt; armor otherwise
  local INSTANT = { [276903] = { "INVTYPE_WEAPONMAINHAND", 2, 15 }, [2470] = { "INVTYPE_CHEST", 4, 2 }, [2435] = { "INVTYPE_CHEST", 4, 1 },
                    [2471] = { "INVTYPE_WAIST", 4, 2 } }
  env.C_Item.GetItemInfoInstant = function(id)
    local i = INSTANT[id] or { "INVTYPE_CHEST", 4, 1 }
    return id, "Armor", "Cloth", i[1], 133328, i[2], i[3]
  end
  local itemInfo = env.GetItemInfo
  env.GetItemInfo = function(id) local name, link = itemInfo(id); return c.itemName[id] or name, link end
  c.itemName[276903], c.itemLevel[276903] = "Shimmerwine Shanker", 52
  c.itemLevel[2470], c.itemLevel[2435], c.itemLevel[2471] = 50, 50, 50
end
local SERVER = {
  [99999] = { t = "Shimmerwine Shakedown", lvl = 51, xp = 6150, money = 4500, c = { 276903 }, r = {} },
  [99002] = { t = "Late Rewards", lvl = 30, c = { 2470 }, r = {}, late = 2 },
  [99003] = { t = "Empty Hands", lvl = 30, c = {}, r = {}, sync = true },
  [10] = { t = "The Scrimshank Redemption", lvl = 48, xp = 4400, c = { 2470, 2435 }, r = { 2471 } },
  [99001] = { fail = true },
  [99004] = { silent = true },
  [99006] = { t = "Already Here", lvl = 40, c = { 2435 }, r = {}, cached = true },
  [99007] = { t = "Never Whole", lvl = 40, c = { 2435 }, r = {}, noIds = true },
}
local RUNA = { name = "Runa", level = 50, cap = 60, faction = "Alliance", className = "Rogue", class = "ROGUE", classID = 4, race = "Human",
               log = {}, done = {}, group = false, guild = false, world = { 0, -8914, -133 }, bind = "Stormwind City", riding = true,
               bagSlots = {}, xp = 100, map = 1453 }
local runa = newClient(deepCopy(RUNA))
do
  local c, Q2 = runa, runa.QB
  local S, D2 = Q2.Survey, Q2.Data
  -- the real list: three ascending runs, the catalog's run exactly its quests with no Forever rewards known (none known,
  -- or only the Classic database's: the game's answer replaces those)
  local real = {}
  for run, s in ipairs(D2.SURVEY) do
    local ids = S.Decode(s)
    assert(#ids > 0, "run " .. run .. " has ids")
    for k, id in ipairs(ids) do
      assert(k == 1 or id > ids[k - 1], "each run ascends")
      assert(not real[id], "an id once")
      real[id] = run
      if run == 2 then assert(D2.Q[id] and (D2.RUNK[id] or D2.RCLASSIC[id]), "the catalog's run: a catalog quest with no Forever rewards known: " .. id)
      elseif run == 4 then assert(D2.Q[id] and D2.RITEMS[id], "the check: catalog quests whose items Wowhead lists: " .. id)
      else assert(not D2.Q[id] and (run == 1) == (id >= 90000), "the other runs: ids the catalog lacks, the new range first: " .. id) end
    end
  end
  for id in pairs(D2.RUNK) do if D2.Q[id] then assert(real[id] == 2, "every catalog quest with no rewards known is asked about: " .. id) end end
  for id in pairs(D2.RCLASSIC) do if D2.Q[id] then assert(real[id] == 2, "every catalog quest with Classic's rewards alone is asked about: " .. id) end end
  assert(S.Decode(S.Encode({ 1, 2, 33, 1057, 99999 }))[5] == 99999 and #S.Encode({ 99999 }) == 4, "the encoding reads back")
  assert(D2.RUNK[10] and not D2.RITEMS[10], "quest 10's rewards are not known before the survey")
  -- the check: three Forever quests whose items Wowhead lists, asked first
  local CHECK = S.Decode(D2.SURVEY[4])
  assert(#CHECK == 3, "three quests to check")
  for _, id in ipairs(CHECK) do
    local R = D2.RITEMS[id]
    assert(D2.Q[id] and R and ((R.c and #R.c > 0) or (R.r and #R.r > 0)), "a check quest has items on Wowhead's list: " .. id)
  end
  -- this test's list: the server's quests, and 80001, which it knows nothing of
  D2.SURVEY = { S.Encode({ 99001, 99002, 99003, 99004, 99006, 99007, 99999 }), S.Encode({ 10 }), S.Encode({ 80001 }), D2.SURVEY[4] }
  local WANT = { [99001] = true, [99002] = true, [99003] = true, [99004] = true, [99006] = true, [99007] = true, [99999] = true, [10] = true, [80001] = true }
  local server = deepCopy(SERVER)
  for _, id in ipairs(CHECK) do
    WANT[id] = true
    server[id] = { t = Q2.Data.QN[id], lvl = D2.Q[id][1], c = deepCopy(D2.RITEMS[id].c or {}), r = deepCopy(D2.RITEMS[id].r or {}) }
  end
  surveyClient(c, server)
  c.unloaded[2470] = true -- not in the item cache yet: its level comes once the server sends the item
  login(c)
  assert(S.frame and S.On() and #c.qAsked == 0, "nothing is asked in the first seconds after login")
  tick(c, 16)
  local first = #c.qAsked
  assert(first >= 2 and first <= 3 and c.qAsked[1].t >= 1000 + S.START, "it starts half a minute after login: " .. first)
  -- a fight: nothing is asked until it ends
  c.combat = true
  tick(c, 30)
  assert(#c.qAsked == first and S.state == "fight", "nothing in a fight")
  c.combat = false
  S.frame.__scripts.OnEvent(S.frame, "PLAYER_REGEN_ENABLED")
  tick(c, 1)
  assert(#c.qAsked > first, "it goes on when the fight ends")
  -- an instance: it stops, and the loading screen on the way out starts it again after a few seconds
  local inside = true
  c.env.IsInInstance = function() return inside, inside and "party" or "none" end
  tick(c, 1)
  local n = #c.qAsked
  tick(c, 40)
  assert(#c.qAsked == n and S.state == "instance", "nothing inside an instance")
  inside = false
  S.frame.__scripts.OnEvent(S.frame, "PLAYER_ENTERING_WORLD", false, false)
  tick(c, S.SETTLE - 1)
  assert(#c.qAsked == n, "not in the seconds after the loading screen")
  tick(c, 2)
  assert(#c.qAsked > n, "and on after them")
  -- a secret id, or an answer to a quest it never asked about (Blizzard's own requests fire the event too): nothing
  S.frame.__scripts.OnEvent(S.frame, "QUEST_DATA_LOAD_RESULT", SECRET.num(), true)
  S.frame.__scripts.OnEvent(S.frame, "QUEST_DATA_LOAD_RESULT", 4242, true)
  tick(c, 300)
  assert(S.state == "done", "done: " .. tostring(S.state))
  -- only the list's ids, PACE apart at the least, never more than FLIGHT waiting for an answer
  local count = {}
  for k = 1, 3 do assert(c.qAsked[k].id == CHECK[k], "the check is asked first") end
  assert(Q2.Survey.Checked() == "trusted", "the game showed the check quests' items")
  for k, a in ipairs(c.qAsked) do
    assert(WANT[a.id], "asked only about the list's quests: " .. a.id)
    count[a.id] = (count[a.id] or 0) + 1
    assert(k == 1 or a.t - c.qAsked[k - 1].t >= S.PACE - 1e-9, "paced: " .. (a.t - (c.qAsked[k - 1] or a).t))
    local waiting = 0
    for j = 1, k - 1 do
      local b = c.qAsked[j]
      if (not b.back or b.back > a.t) and a.t - b.t < S.TIMEOUT then waiting = waiting + 1 end
    end
    assert(waiting < S.FLIGHT, "at most " .. S.FLIGHT .. " waiting for an answer")
  end
  -- a quest the server says no to, one it never answers and one it doesn't know: three tries each, no more
  assert(count[99001] == S.TRIES and count[99004] == S.TRIES and count[80001] == S.TRIES, "three tries for a failure")
  for id, s in pairs(SERVER) do if not s.fail and not s.silent and not s.cached then assert(count[id] == 1, "asked once: " .. id) end end
  -- a quest the client has already is read without a question (its answer would come inside QuestBank's call)
  assert(not count[99006] and d0(c).survey[99006].c[1] == 2435, "read as the client has it")
  -- rewards that never come whole: the try fails, the title stays, three reads in all and the quest rests
  assert(d0(c).surveyNo[99007] == 3 and d0(c).survey[99007].t == "Never Whole" and d0(c).survey[99007].c == nil, "never whole: three tries")
  local d = c.env.QuestBankDB.disc
  assert(d.surveyB == 70170 and d.surveyNo[99001] == 3 and d.surveyNo[99004] == 3 and d.surveyNo[80001] == 3, "the tries are kept for this build")
  -- what the game told, kept per account
  local rec = d.survey[99999]
  assert(rec.t == "Shimmerwine Shakedown" and rec.lvl == 51 and rec.xp == 6150 and rec.pl == 50 and rec.money == 4500 and rec.b == 70170
    and #rec.c == 1 and rec.c[1] == 276903 and #rec.r == 0 and rec.at == nil, "the title, rewards, XP, money and level are kept")
  assert(d.survey[99002].c[1] == 2470, "rewards that come late are read again until they are all there")
  assert(#d.survey[99003].c == 0 and #d.survey[99003].r == 0, "no item rewards: two empty lists (answered inside the call)")
  assert(d.survey[10].c[2] == 2435 and d.survey[10].r[1] == 2471, "a catalog quest's lists")
  assert(not d.q[99999] and not d.q[10], "the survey is no sighting: the quest notes stay as they were")
  local dg = c.env.QuestBankDB.diag.survey
  assert(dg.asked == #c.qAsked and dg.loaded == 11 and dg.rewards == 7 and dg.failed == 12, "the counts: " .. dg.asked .. " " .. dg.loaded .. " " .. dg.rewards .. " " .. dg.failed)
  for _, id in ipairs(CHECK) do assert(not D2.RSURV[id], "a check quest's lists stay Wowhead's: " .. id) end
  -- an item the client didn't have: asked of the server in turn (never in one go), and the quests waiting on its level
  -- are rated again when it comes
  local reqs = 0
  for _, i in ipairs(c.loadRequests) do if i == 2470 then reqs = reqs + 1 end end
  assert(reqs == 1 and D2.REWARD[99002] and D2.REWARD[99002][1] == 0, "the leather chest's level is asked for once")
  c.unloaded[2470] = nil
  S.frame.__scripts.OnEvent(S.frame, "ITEM_DATA_LOAD_RESULT", 2470, true)
  assert(D2.REWARD[99002][1] == 50 and D2.REWARD[99002][3] == 2470, "and it comes")
  -- used at once: the catalog quest's rewards in its tooltip and in the finders' facts (Available's gear chip reads them)
  assert(D2.RITEMS[10] and not D2.RUNK[10] and D2.REWARD[10][1] == 50 and D2.REWARD[10][2] % 2 == 1, "quest 10's rewards are in the catalog's tables")
  local q10 = Q2.Quest.Get(10)
  local _, how = Q2.Quest.Rewards(q10)
  assert(how == "survey", "and they say where they come from")
  lines = {}; Q2.UI.QuestTooltip(c.env.GameTooltip, q10, Q2:Status(q10), 1000)
  local t = table.concat(lines, "\n")
  assert(t:find("Choose one:", 1, true) and t:find("You get:", 1, true) and t:find("As the game told QuestBank.", 1, true), t)
  local function found(level)
    for _, row in ipairs(Q2.UI:FindRewards("gear", level)) do if row.q.id == 99999 then return row end end
  end
  -- the Forever quest no list has: Best gear finds it for the rogue at 51, its dagger judged item by item as every
  -- quest's (and at 50: the finders list what you can take now, whatever the quest's level)
  local hit = found(51)
  assert(hit and hit.ilvl == 52 and hit.item == 276903 and hit.q.name == "Shimmerwine Shakedown" and hit.q.surveyOnly, "Best gear at 51")
  assert(found(50), "and at 50")
  assert(hit.q.cat and hit.q.cat.name == "Seen in game" and not hit.q.give and not hit.q.turn, "seen in game, no giver")
  for _, cand in ipairs(Q2.UI:Candidates(nil, 51)) do assert(cand.id ~= 99999, "nothing but the finders suggests it") end
  -- on the page: the weapons, the dagger first
  local U = Q2.UI
  U.findMode, U.gearSlot = "gear", "Weapon"
  U:Open(1); U:Refresh()
  local row
  for _, r in ipairs(U.views[1].swaps) do if r:IsShown() and r.add and r.add.id == 99999 then row = r end end
  assert(row and row.gain:GetText() == "iL 52" and row.cutName:GetText():find("Shimmerwine Shanker", 1, true)
    and row.cutName:GetText():find("Seen in game", 1, true), "the row: " .. tostring(row and row.cutName:GetText()))
  for _, p in ipairs(checkLayout(U.frame, "Quest Log, Best gear, seen in game")) do problems[#problems + 1] = p end
  lines = {}; row.__scripts.OnEnter(row)
  t = table.concat(lines, "\n")
  assert(t:find("Seen in game: QuestBank asked the game about it", 1, true) and t:find("Level 51", 1, true) and not t:find("needs", 1, true)
    and t:find("As the game told QuestBank.", 1, true), t)
  local said = #c.chat
  row.__scripts.OnClick(row, "LeftButton")
  assert(#c.chat == said + 1 and c.chat[#c.chat]:find("Who gives Shimmerwine Shakedown isn't known yet", 1, true), "no waypoint: it says so")
  U.findMode, U.gearSlot = "xp", nil
  -- the item's own tooltip names the quest
  lines = {}; Q2.Link.ItemTip(c.env.GameTooltip, { id = 276903 })
  assert(table.concat(lines, "\n"):find("Reward of: Shimmerwine Shakedown (L51, Seen in game)", 1, true), table.concat(lines, "\n"))
  -- /qb survey
  said = #c.chat
  c.env.SlashCmdList.QUESTBANK("survey")
  assert(c.chat[said + 1]:find("12 of 12 quests done on this build", 1, true) and c.chat[said + 1]:find("Done for this game build.", 1, true), c.chat[said + 1])
  -- the Settings box: ticked by default here; unticked, nothing more is asked
  U:Open(5); U:Refresh()
  local v5 = U.views[5]
  assert(v5.survey:IsEnabled() and v5.survey:GetChecked() and v5.survey.label:GetText() == "Learn quests from the game", "the box")
  lines = {}; v5.survey.__scripts.OnEnter(v5.survey)
  assert(table.concat(lines, "\n"):find("12 of 12 quests done on this build, 7 with item rewards.", 1, true), table.concat(lines, "\n"))
  v5.survey:SetChecked(false); v5.survey.__scripts.OnClick(v5.survey, "LeftButton")
  assert(Q2:Settings().survey == false and S.state == "off" and not S.On(), "unticked: off")
  v5.survey:SetChecked(true); v5.survey.__scripts.OnClick(v5.survey, "LeftButton")
  assert(Q2:Settings().survey == true and S.On(), "ticked again")
  for _, p in ipairs(checkLayout(U.frame, "Settings, with the survey")) do problems[#problems + 1] = p end
  assert(#c.wrongTime == 0, "nothing asked or read in a fight or an instance: " .. table.concat(c.wrongTime, ", "))
  print(string.format("quest survey: %d questions, %d quests answered, the Shimmerwine Shanker in Best gear at iL %d", #c.qAsked, dg.loaded, hit.ilvl))
end

-- after a reload the account's survey stands: what it learned is in the finders before any question, and only what is
-- new on the list is asked. A new build asks everything again. Quests in a row that really pay alike (four of different
-- levels the same XP, six the same items) are kept while the check's quests tell their own apart; a client that answers
-- every id with one quest's XP and rewards (the check's quests too) gives itself away, and the earlier readings stand
do
  local saved = deepCopy(runa.env.QuestBankDB)
  local again = newClient(deepCopy(RUNA))
  again.env.QuestBankDB = saved
  local Q2, S = again.QB, again.QB.Survey
  local server = deepCopy(SERVER)
  local CHECK = S.Decode(Q2.Data.SURVEY[4])
  for _, id in ipairs(CHECK) do
    -- (the client has them from the first session: they can be read again without a question)
    server[id] = { t = Q2.Data.QN[id], lvl = Q2.Data.Q[id][1], xp = 30 + id, c = deepCopy(Q2.Data.RITEMS[id].c or {}), r = deepCopy(Q2.Data.RITEMS[id].r or {}),
                   cached = true }
  end
  for k = 0, 3 do server[99010 + k] = { t = "Same Pay " .. k, lvl = 46 + k, xp = 5000, c = {}, r = {} } end
  for k = 0, 5 do server[99020 + k] = { t = "Same Items " .. k, lvl = 40, c = { 2435 }, r = {} } end
  server[99005] = { t = "New On The List", lvl = 45, c = { 2471 }, r = {}, late = 3 }
  surveyClient(again, server)
  local list = { 99001, 99002, 99003, 99004, 99005, 99999 }
  for k = 0, 3 do list[#list + 1] = 99010 + k end
  for k = 0, 5 do list[#list + 1] = 99020 + k end
  table.sort(list)
  Q2.Data.SURVEY = { S.Encode(list), S.Encode({ 10 }), S.Encode({ 80001 }), Q2.Data.SURVEY[4] }
  login(again)
  local row
  for _, r in ipairs(Q2.UI:FindRewards("gear", 51)) do if r.q.id == 99999 then row = r end end
  assert(row and row.ilvl == 52 and row.item == 276903 and #again.qAsked == 0, "after a reload: in Best gear at once, before any question")
  assert(Q2.Data.RITEMS[10] and not Q2.Data.RUNK[10], "and the catalog quest's rewards too")
  -- a fight while a quest's rewards are still on their way: the reads wait for its end
  for _ = 1, 1000 do if #again.qAsked > 0 then break end tick(again, 0.05) end
  assert(again.qAsked[1].id == 99005, "the first new quest on the list")
  tick(again, 0.3) -- answered and read once (its rewards not all there yet), the next question not yet asked
  assert(#again.qAsked == 1, "one question so far")
  again.combat = true
  tick(again, 12)
  assert(not again.env.QuestBankDB.disc.survey[99005] and #again.wrongTime == 0, "nothing read in a fight")
  again.combat = false
  S.frame.__scripts.OnEvent(S.frame, "PLAYER_REGEN_ENABLED")
  tick(again, 400)
  local asked = {}
  for _, a in ipairs(again.qAsked) do asked[a.id] = (asked[a.id] or 0) + 1 end
  assert(not asked[99999] and not asked[10] and not asked[99001] and not asked[99004] and not asked[80001] and asked[99005] == 1,
    "only what is new on the list is asked on the same build")
  local d = again.env.QuestBankDB.disc
  assert(d.survey[99005].c[1] == 2471 and Q2.Data.REWARD[99005], "the new one is kept, and in the finders")
  for k = 0, 3 do assert(d.survey[99010 + k].xp == 5000 and d.survey[99010 + k].t == "Same Pay " .. k, "four quests that really pay alike: kept") end
  for k = 0, 5 do
    assert(d.survey[99020 + k].c[1] == 2435 and Q2.Data.RITEMS[99020 + k] and Q2.Data.RITEMS[99020 + k].c[1] == 2435, "six in a row with one list, really: kept")
  end
  assert(d.survey[99999].xp == 6150, "the readings before stay")
  -- a new build: every quest is asked again. This one shows no items for the check's quests: then no answer that a
  -- quest gives no items is kept (the earlier build's stands), and /qb survey says why
  again.env.GetBuildInfo = function() return "1.60.1", "70400", "Oct 14 2026", 16001 end
  for _, id in ipairs(CHECK) do server[id].c, server[id].r = {}, {}; again.loadedQ[id] = nil end
  again.loadedQ[99003] = nil
  server[99002].late = 0 -- (all there at once this time: the reads come in the order asked, the run of one list unbroken)
  S.Start(0)
  tick(again, 400)
  local fresh = 0
  for _, a in ipairs(again.qAsked) do if a.id == 99999 then fresh = fresh + 1 end end
  assert(fresh == 1 and d.surveyB == 70400 and d.survey[99999].b == 70400, "a new build asks again")
  assert(S.Checked() == "failed" and d.surveyNo[99003] == 3 and d.survey[99003].b == 70170, "no-item answers aren't kept when the check failed")
  for k = 0, 5 do assert(d.survey[99020 + k].b == 70400 and d.survey[99020 + k].c[1] == 2435, "a run of one list, nothing wrong seen: kept") end
  local said = #again.chat
  again.env.SlashCmdList.QUESTBANK("survey")
  assert(again.chat[said + 1]:find("no-reward answers aren't kept", 1, true), again.chat[said + 1])
  -- another build, on a client that answers every quest with one quest's rewards and XP (the Shimmerwine Shakedown's),
  -- the check's quests too: they come back wrong, the run of one list and the run of one XP are dropped, and what this
  -- account read on the build before stands, in the saved file and in the finders
  local env = again.env
  env.GetBuildInfo = function() return "1.60.1", "70500", "Oct 15 2026", 16001 end
  env.GetNumQuestLogChoices = function() return 1 end
  env.GetNumQuestLogRewards = function() return 0 end
  env.GetQuestLogChoiceInfo = function(i) if i == 1 then return "Item 276903", 133328, 1, 2, true, 276903 end end
  env.GetQuestLogRewardXP = function() return 6150 end
  S.Start(0)
  tick(again, 400)
  local k5 = d.surveyCheck
  assert(d.surveyB == 70500 and S.Checked() == "failed" and k5.b == 70500, "the check's quests came back wrong")
  for _, id in ipairs(CHECK) do assert(k5.ids[id] == "wrong", "wrong: " .. id .. " " .. tostring(k5.ids[id])) end
  for k = 0, 5 do
    assert(d.survey[99020 + k].c[1] == 2435 and d.survey[99020 + k].b == 70400 and Q2.Data.RITEMS[99020 + k].c[1] == 2435, "the earlier lists stand: " .. (99020 + k))
  end
  assert(d.survey[99005].c[1] == 2471 and Q2.Data.RITEMS[99005].c[1] == 2471 and Q2.Data.RITEMS[99002].c[1] == 2470, "and those the run took back")
  assert(Q2.Data.RITEMS[10] and Q2.Data.RITEMS[10].c[1] == 2470 and d.survey[10].b == 70400, "the catalog quest keeps its lists")
  for k = 0, 3 do assert(d.survey[99010 + k].xp == 5000, "the earlier XP stands: " .. (99010 + k) .. " " .. tostring(d.survey[99010 + k].xp)) end
  assert(#again.wrongTime == 0, "nothing asked or read in a fight or an instance: " .. table.concat(again.wrongTime, ", "))
  print(string.format("quest survey after a reload: %d questions in all, the new build's with them", #again.qAsked))
end

-- the merge of the finders and the survey: the game's answer replaces rewards only the Classic database had (and the
-- tooltip stops calling them Classic data), and a surveyed quest's items are judged one by one like any quest's: the
-- rogue is offered a leather chest, never a cloth one
do
  local Q2 = runa.QB
  local D2, S, U = Q2.Data, Q2.Survey, Q2.UI
  local cid
  for id in pairs(D2.RCLASSIC) do if D2.Q[id] and not D2.RSURV[id] and (not cid or id < cid) then cid = id end end
  assert(cid and D2.RITEMS[cid], "a catalog quest with Classic's rewards alone")
  local q = Q2.Quest.Get(cid)
  lines = {}; runa.env.GameTooltip:ClearLines(); U.RewardLines(runa.env.GameTooltip, q)
  assert(table.concat(lines, "\n"):find("Rewards from Classic data", 1, true), "before: Classic data")
  assert(S.Use(cid, { t = D2.QN[cid], lvl = D2.Q[cid][1], c = { 2470 }, r = {} }), "the game's answer is taken")
  assert(D2.RITEMS[cid].c[1] == 2470 and not D2.RCLASSIC[cid] and D2.RSURV[cid] and not D2.RUNK[cid], "it replaces Classic's list")
  local _, how = Q2.Quest.Rewards(q)
  lines = {}; runa.env.GameTooltip:ClearLines(); U.RewardLines(runa.env.GameTooltip, q)
  local t = table.concat(lines, "\n")
  assert(how == "survey" and not t:find("Classic data", 1, true) and t:find("As the game told QuestBank.", 1, true), t)
  -- a quest no list has, with a cloth chest alone, and one with a leather chest: the rogue's Best gear has the second
  local CLOTH, LEATHER = 199050, 199051 -- (ids the catalog doesn't have)
  assert(not D2.Q[CLOTH] and not D2.Q[LEATHER])
  assert(S.Use(CLOTH, { t = "Cloth Only", lvl = 50, c = { 2435 }, r = {} }) and S.Use(LEATHER, { t = "Leather Too", lvl = 50, c = { 2435, 2470 }, r = {} }))
  assert(U.ItemUse(2470, 51) == "gear" and U.ItemUse(2435, 51) == nil, "leather for the rogue, cloth not")
  Q2.surveyVer = Q2.surveyVer + 1 -- (as the survey's own answers do: the finders' list is made again)
  local seen = {}
  for _, row in ipairs(U:FindRewards("gear", 51)) do seen[row.q.id] = row end
  assert(not seen[CLOTH] and seen[LEATHER] and seen[LEATHER].item == 2470 and seen[LEATHER].ilvl == 50,
    "judged item by item: " .. tostring(seen[CLOTH]) .. " " .. tostring(seen[LEATHER] and seen[LEATHER].item))
  print(string.format("survey and finder: quest %d's Classic rewards replaced by the game's; seen-in-game rows judged per item", cid))
end

-- the other end: players' uploads with survey answers (tools/fixtures/probe/QuestBank-survey.lua and a later build's,
-- merged by probe_pull.py) as gen_data.py builds them into Data.lua: a catalog quest with no rewards known takes the
-- game's lists, Wowhead's lists stand, the newest build's list wins, and a quest no list has goes to D.SURVEYED (in
-- the finders) with the Shimmerwine Shanker's facts. Where the generator's inputs are (research/), with python3
do
  local inputs = io.open(HERE .. "/../../research/questbank/manifest.json")
  if inputs then
    inputs:close()
    local p = io.popen("cd '" .. HERE .. "' && python3 gen_data.py --selftest-survey 2>&1")
    local out = p and p:read("*a") or ""
    if p then p:close() end
    assert(out:find("selftest-survey: OK", 1, true), "gen_data.py --selftest-survey:\n" .. out)
    print((out:match("(selftest%-survey: OK[^\n]*)")))
  else
    print("gen_data.py --selftest-survey: skipped (no research/ here)")
  end
end

----------------------------------------------------------------------------
-- calls QuestBank's code never makes, read from the files themselves (code only, comments left out). Each one runs
-- the game's own code as QuestBank, where the game later blocks it and blames QuestBank:
--   the game's waypoint and tracking (USER_WAYPOINT_UPDATED, SUPER_TRACKING_CHANGED and QUEST_WATCH_LIST_CHANGED run
--   Blizzard's listeners inside the call), Blizzard's popups (their list of popups on screen), opening the chat box
--   (the game's chat globals), the escort prompt's Yes with no click behind it and its count of a full log (MAX_QUESTS:
--   read, never written; the prompt reads it as it opens), the map canvas's pin calls, the world map laid out or moved
--   as QuestBank (ToggleWorldMap sizes it and fills its quest log, SetMapID redraws its pins; the Map opens through
--   OpenWorldMap, which the game's own panel code shows), and the loot window's actions (taking a slot, closing it,
--   rolling, the loot method: the drop-source notes only read the window)
----------------------------------------------------------------------------
do
  -- whole names (CanSetUserWaypointOnMap, a question, is fine; so is GetLootSlotInfo next to LootSlot), and the start of
  -- a family (StaticPopup_Show, _Hide...)
  local NEVER = { "SetUserWaypoint", "ClearUserWaypoint", "C_SuperTrack", "AddQuestWatch", "RemoveQuestWatch",
    "AddWorldQuestWatch", "AddQuestWatchForQuestID", "StaticPopupDialogs", "OpenChat", "ChatFrame_OpenChat", "ActivateChat",
    "ACTIVE_CHAT_EDIT_BOX", "LAST_ACTIVE_CHAT_EDIT_BOX", "ConfirmAcceptQuest", "AcquirePin", "RemoveAllPinsByTemplate",
    "RemovePin", "SetPinPosition", "MarkCanvasDirty", "UpdateQuestAcceptLogFullDialog", "MAX_QUESTLOG_QUESTS",
    "LootSlot", "CloseLoot", "ConfirmLootSlot", "ConfirmLootRoll", "RollOnLoot", "SetLootMethod", "ToggleWorldMap" }
  -- SetMapID only on QuestBank's own frames: the Map page's canvas (MapPage.lua) and the minimap's quest areas
  -- (MinimapView.lua: a QuestPOIFrame of its own). The world map's, never
  local OWN_MAPID = { ["MapPage.lua"] = { "Canvas:SetMapID", "canvas:SetMapID" }, ["MinimapView.lua"] = { "part[:.]SetMapID" } }

  local FAMILIES = { "StaticPopup_", "SetSuperTracked" }
  local PATTERNS = {}
  for _, name in ipairs(NEVER) do PATTERNS[#PATTERNS + 1] = { "%f[%w_]" .. name .. "%f[^%w_]", name } end
  for _, name in ipairs(FAMILIES) do PATTERNS[#PATTERNS + 1] = { "%f[%w_]" .. name, name .. "*" } end
  -- ChatFrameUtil's LinkItem opens the box when none is open: the name in a string is how QuestBank would reach it
  PATTERNS[#PATTERNS + 1] = { "[\"']LinkItem[\"']", "ChatFrameUtil LinkItem" }
  -- the game's MAX_QUESTS is read (the escort prompt's count), never written: the prompt reads it as it opens
  PATTERNS[#PATTERNS + 1] = { "%f[%w_]MAX_QUESTS%s*=%f[^=]", "MAX_QUESTS =" }
  -- a line without its comment (a "--" outside a string)
  local function code(line)
    local q, i = nil, 1
    while i <= #line do
      local ch = line:sub(i, i)
      if q then
        if ch == "\\" then i = i + 1 elseif ch == q then q = nil end
      elseif ch == '"' or ch == "'" then q = ch
      elseif line:sub(i, i + 1) == "--" then return line:sub(1, i - 1) end
      i = i + 1
    end
    return line
  end
  local found, files = {}, 0
  for line in io.lines(HERE .. "/QuestBank/QuestBank.toc") do
    local f = line:match("^%s*([%w_]+%.lua)%s*$")
    if f and f ~= "Data.lua" then
      files = files + 1
      local n = 0
      for src in io.lines(HERE .. "/QuestBank/" .. f) do
        n = n + 1
        local c = code(src)
        for _, pat in ipairs(PATTERNS) do
          if c:find(pat[1]) then found[#found + 1] = string.format("%s:%d %s", f, n, pat[2]) end
        end
        if c:find("%f[%w_]SetMapID%f[^%w_]") then
          local mine = false
          for _, ok in ipairs(OWN_MAPID[f] or {}) do if c:find("%f[%w_]" .. ok .. "%f[^%w_]") then mine = true end end
          if not mine or c:find("WorldMapFrame[:.]SetMapID") then found[#found + 1] = string.format("%s:%d SetMapID", f, n) end
        end
      end
    end
  end
  assert(files >= 10, "every Lua file the TOC lists was read")
  assert(#found == 0, "QuestBank's code makes a call that runs the game's code as QuestBank:\n  " .. table.concat(found, "\n  "))
  print("calls QuestBank never makes:", #PATTERNS, "names, none in", files, "files")
end

----------------------------------------------------------------------------
-- 5.4.4: one sticky target. The owner, after 5.4.3: "map is still broken, lines on map go haywire sometimes, and
-- routing just swaps mid zone if I run, so the objective completely changes running from Southshore to Alterac". The
-- arrow, the minimap and the Map page each picked their own target, again and again: the planner's first stop flipped
-- on a tie as the flight master nearest you (as the crow flies, known or not) changed, the minimap took the nearest spot
-- of any quest 20 times a second, finished objectives too, and the travel guide re-planned at each zone's border. Each
-- case below failed on 5.4.3's files (run them alone against an older QuestBank: the cases are in RCASES, in order) and
-- passes now. Hillsbrad and Alterac as the client has them: each map's corners in the world, fitted to the catalog's
-- NPCs (the world map's own GetWorldPosFromMapPos does this in game)
----------------------------------------------------------------------------
;(function()
  local RCASES = {}
  local HILLS = {
    [1424] = { wy0 = 1066.91, wyx = -32.0059, wx0 = 400.10, wxy = -21.3354 },   -- Hillsbrad Foothills
    [1416] = { wy0 = 783.55, wyx = -28.0005, wx0 = 1499.91, wxy = -18.6646 },   -- Alterac Mountains
  }
  -- a client standing in Hillsbrad: where it stands (c.me, continent yards) is read by the game's map calls through the
  -- two maps above; the map it is on is the one whose edges hold it (Alterac north of Hillsbrad's top)
  local function hillsClient(name, log, done)
    local c = newClient({ name = name, level = 30, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1,
      race = "Human", log = log, done = done or {}, world = { 0, -852, -517 }, map = 1424, bagSlots = {}, bind = "Southshore" })
    local env = c.env
    c.me = { wx = -852, wy = -517 }
    local function toMap(m, wx, wy)
      local t = HILLS[m]
      if not t then return nil end
      return (wy - t.wy0) / t.wyx / 100, (wx - t.wx0) / t.wxy / 100
    end
    local function mapAt(wx, wy)
      local _, y = toMap(1424, wx, wy)
      return y < 0.14 and 1416 or 1424
    end
    c.mapAt = mapAt
    env.C_Map.GetBestMapForUnit = function() return mapAt(c.me.wx, c.me.wy) end
    env.MapUtil.GetDisplayableMapForPlayer = function() return mapAt(c.me.wx, c.me.wy) end
    env.C_Map.GetPlayerMapPosition = function(m)
      local x, y = toMap(m, c.me.wx, c.me.wy)
      if not x then return nil end
      return { x = x, y = y, GetXY = function(self) return self.x, self.y end }
    end
    local wpos = env.C_Map.GetWorldPosFromMapPos
    env.C_Map.GetWorldPosFromMapPos = function(m, v)
      local t = HILLS[m]
      if not t then return wpos(m, v) end
      return 0, { x = t.wx0 + t.wxy * v.y * 100, y = t.wy0 + t.wyx * v.x * 100, GetXY = function(self) return self.x, self.y end }
    end
    env.C_Map.GetMapPosFromWorldPos = function(cont, pos, m)
      local x, y = toMap(m, pos.x, pos.y)
      if cont ~= 0 or not x then return nil end
      return m, env.CreateVector2D(x, y)
    end
    -- (zones beside each other: neither lies inside the other)
    env.C_Map.GetMapRectOnMap = function() return nil end
    env.IsInInstance = function() return false, "none" end
    login(c)
    return c
  end
  -- one frame of play: the clock, the timers due, every shown frame's OnUpdate once
  local function frame(c, dt)
    c.clock = c.clock + dt
    table.sort(c.timers, function(a, b) return a.t < b.t end)
    while c.timers[1] and c.timers[1].t <= c.clock do table.remove(c.timers, 1).f() end
    for _, f in ipairs(c.frames) do
      local u = f.__scripts.OnUpdate
      if u and f:IsVisible() then u(f, dt) end
    end
  end
  -- you walk to a spot: a new zone is the game's event to QuestBank's frames (its events, the travel guide's, the Map page's)
  local function walkTo(c, wx, wy)
    local was = c.mapAt(c.me.wx, c.me.wy)
    c.me.wx, c.me.wy = wx, wy
    c.o.world = { 0, wx, wy }
    if c.mapAt(wx, wy) ~= was then
      c.ev(c.QB.eventFrame, "ZONE_CHANGED_NEW_AREA")
      for _, f in ipairs({ c.QB.Travel.frame, c.QB.MapPage and c.QB.MapPage.events }) do
        if f and f.__scripts.OnEvent then f.__scripts.OnEvent(f, "ZONE_CHANGED_NEW_AREA") end
      end
    end
  end
  -- a minimap entry's place: continent yards (Target.lua's entries), else its map's spot through the world
  local function worldOf(QB, d)
    if not d then return nil end
    if d.wx then return d end
    return d.m and QB.Model.World(d.m, d.x, d.y)
  end
  local function firstStop(QB)
    local r = QB.Target and QB.Target.Route() or (QB.routeNow and QB.routeNow.legs[1] and QB.routeNow or QB.routePlan)
    return r and r.legs[1] and r.legs[1].stop.name
  end

  -- R1: two objective spots of stop 1's quest either side of a straight walk, stop 1 farther. 5.4.3's minimap took the
  -- nearer spot at each look: the stroke flipped at every crossing of the line halfway, and went to a finished
  -- objective's spot as readily. Now the spot is kept until another is clearly nearer, and a finished one leads nowhere
  RCASES[#RCASES + 1] = { "R1 objective spots: no flip on the midline, no finished objective", function()
    local c = hillsClient("Rone", { { 500, 0 }, { 504, 0 } })
    local QB, D = c.QB, c.QB.Data
    local Mini, P = QB.Mini, QB.Pins
    QB.Arrow:Set(true)
    -- 500's two spots on Alterac's map, either side of a walk north along wy = -700: A west (wy -640), B east (wy -760);
    -- the walk crosses the line halfway between them at wx = 300; stop 1 (Southshore) is far south
    local function spot(wx, wy) local t = HILLS[1416]; return string.format("%d,%d", math.floor((wy - t.wy0) / t.wyx * 10 + 0.5), math.floor((wx - t.wx0) / t.wxy * 10 + 0.5)) end
    local saveSpot = { D.SPOT[500], D.SPOT[504] }
    D.SPOT[500] = "k,1,1416," .. spot(270, -640) .. ",20,c;k,2,1416," .. spot(330, -760) .. ",20,c"
    D.SPOT[504] = nil
    -- (two lines the game tells apart by their counts)
    c.objectives = { [500] = { { text = "Crushridge Ogre slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 },
                               { text = "Crushridge Brute slain: 0/6", type = "monster", finished = false, numFulfilled = 0, numRequired = 6 } } }
    local saveReq = D.SREQ[500]
    D.SREQ[500] = "1:10,2:6"
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE"); frame(c, 1); QB.Model.Finish(); frame(c, 1)
    assert(firstStop(QB) == "Southshore", "stop 1 is Southshore, where both quests go: " .. tostring(firstStop(QB)))
    walkTo(c, 200, -700)
    -- (put there in one step: a jump in place, which the next look counts and picks the spot afresh for; the walk
    -- across the line starts after it)
    frame(c, 1.1)
    for _ = 1, 3 do frame(c, 0.1) end
    Mini.Place()
    local start = Mini.target and Mini.target.kind == "obj" and Mini.target.id == 500 and Mini.target
    assert(start, "the stroke goes to a spot of stop 1's quest: " .. tostring(Mini.target and Mini.target.kind))
    -- back and forth across the line halfway, 20 yards each way
    local flips, last = 0, nil
    for _, wx in ipairs({ 290, 310, 290, 310, 290, 312, 288, 310 }) do
      walkTo(c, wx, -700)
      frame(c, 0.1)
      Mini.Place()
      local w = worldOf(QB, Mini.target)
      local key = w and string.format("%s:%.0f:%.0f", tostring(Mini.target.kind), w.wx, w.wy)
      if last and key ~= last then flips = flips + 1 end
      last = key
    end
    assert(flips == 0, "the stroke keeps its spot across the line halfway: " .. flips .. " flips")
    -- the kept spot's objective done: it leads nowhere any more, the other spot takes over at once
    local kept = worldOf(QB, Mini.target).wy > -700 and 1 or 2
    c.objectives[500][kept].finished, c.objectives[500][kept].numFulfilled = true, c.objectives[500][kept].numRequired
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE"); frame(c, 1)
    Mini.Invalidate(); Mini.Place()
    local w = worldOf(QB, Mini.target)
    assert(Mini.target and Mini.target.kind == "obj" and w and (w.wy > -700) == (kept == 2), "its objective done, the other spot is the target")
    for _, d in ipairs(Mini.ListCached()) do
      if d.kind == "obj" and d.id == 500 then
        local w = QB.Model.World(d.m, d.x, d.y)
        assert(w and ((kept == 1) == (w.wy < -700)), "and the finished objective's spot is gone from the minimap")
      end
    end
    D.SREQ[500], D.SPOT[500], D.SPOT[504] = saveReq, saveSpot[1], saveSpot[2]
  end }

  -- R2: hand-ins at Southshore, Tarren Mill and Alterac and one far away, planned again at each step of a walk north and
  -- back over the point where two tours tie. 5.4.3 kept nothing: the first stop flipped at each crossing. Now another
  -- first stop must be 5% and half a minute quicker (or reach a higher level by 5%), and walking back over the tie flips
  -- nothing
  RCASES[#RCASES + 1] = { "R2 the planner keeps its first stop unless clearly better", function()
    local c = hillsClient("Rtwo", { { 7, 0 } })
    local M = c.QB.Model
    local function fake(id, npc) return { q = { id = id, turnIdx = npc, lvl = 30, base = 3000, mult = 1, name = "Q" .. id }, st = { code = "banked" } } end
    local entries = { fake(990001, 279), fake(990002, 276), fake(990003, 288), fake(990004, 5) } -- Redpath, Lydon, Valik, Northshire
    local from, to = { -852, -517 }, { 203, -818 }
    local prev, changes, back = nil, 0, 0
    local path = {}
    for k = 0, 24 do path[#path + 1] = k / 24 end                                                  -- north to Alterac
    for _, f in ipairs({ 0.5, 0.54, 0.5, 0.46, 0.5, 0.54, 0.58, 0.54, 0.5, 0.46, 0.5 }) do path[#path + 1] = f end -- to and fro by the tie
    for i, f in ipairs(path) do
      local wx, wy = from[1] + (to[1] - from[1]) * f, from[2] + (to[2] - from[2]) * f
      local r = M.Plan(entries, { level = 30, xp = 0, goal = "route", fac = "A", start = { c = 0, wx = wx, wy = wy }, mounted = false }, prev)
      if prev and r.legs[1].stop.name ~= prev.legs[1].stop.name then
        changes = changes + 1
        if i > 25 then back = back + 1 end
        local alt = r.alt
        assert(alt and alt.first == prev.legs[1].stop.name and alt.t - r.t >= math.max(M.SWITCH * alt.t, 0.5) - 1e-9,
          string.format("a new first stop only when clearly quicker: %s, %.2f min against %s first %s", r.legs[1].stop.name, r.t,
            prev.legs[1].stop.name, alt and string.format("%.2f", alt.t) or "(not weighed)"))
      end
      prev = r
    end
    assert(changes == 1 and back == 0, string.format("north to Alterac the first stop changes once, and to and fro by the tie never: %d, %d", changes, back))
    -- a first stop that is gone (its quest handed in) gives way at once, margin or none
    local keptName, rest = prev.legs[1].stop.name, {}
    for _, e in ipairs(entries) do if e.q.turnIdx ~= prev.legs[1].stop.npcs[1] then rest[#rest + 1] = e end end
    local r = M.Plan(rest, { level = 30, xp = 0, goal = "route", fac = "A", start = { c = 0, wx = -350, wy = -660 }, mounted = false }, prev)
    assert(#rest == 3 and r.legs[1].stop.name ~= keptName and not r.held, "the kept stop handed in: another first at once: " .. r.legs[1].stop.name)
  end }

  -- R3: the same log and XP, 230 yards north from Tarren Mill into Alterac: 5.4.3's signature held the flight master
  -- nearest you (Southshore's, then Chillwind Camp's, which an Alliance player there rarely knows) and planned again. Now
  -- walking plans nothing again: the route, and its first stop, stay as they were
  RCASES[#RCASES + 1] = { "R3 walking 230 yards plans nothing again", function()
    local c = hillsClient("Rthree", { { 500, 1 }, { 504, 1 }, { 501, 1 }, { 509, 1 }, { 535, 1 } })
    local QB = c.QB
    walkTo(c, -6, -899)
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE"); frame(c, 1); QB.Model.Finish(); frame(c, 1)
    QB:Recompute(true)
    local route, sig, first = QB.routeNow, QB.sigNow, firstStop(QB)
    assert(QB.Model.Place("A", 0, -6, -899).hub == 21 and QB.Model.Place("A", 0, 203, -818).hub == 4, "the nearest flight master as the crow flies: Southshore's, then Chillwind Camp's")
    walkTo(c, 203, -818)
    c.xp = (c.xp or 0) + 900; c.ev(QB.eventFrame, "PLAYER_XP_UPDATE", "player")
    c.ev(QB.eventFrame, "BAG_UPDATE_DELAYED")
    for _ = 1, 20 do frame(c, 0.1) end
    QB.Model.Finish()
    QB:Recompute()
    assert(QB.routeNow == route and QB.sigNow == sig, "no plan again for walking, a kill's XP or the bags")
    assert(firstStop(QB) == first, "the first stop is the same: " .. tostring(first) .. ", " .. tostring(firstStop(QB)))
  end }

  -- R4: a target where flying and walking come out about even, a zone's border crossed: 5.4.3 planned the way again
  -- forced, at a hard cut-off, and the first step flipped between the flight and the walk. Now a new zone plans again as
  -- walking does (kept unless clearly better), and a way that flies keeps flying while that saves 5%
  RCASES[#RCASES + 1] = { "R4 the arrow's first step at the walk-or-fly cut-off", function()
    local c = newClient({ name = "Rfour", level = 30, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1, race = "Dwarf",
      log = { { 7, 0 } }, done = {}, world = { 0, -8833, 479 }, bind = "Goldshire", bagSlots = {}, map = 1453 })
    c.ev(c.QB.eventFrame, "ADDON_LOADED", "QuestBank"); c.ev(c.QB.eventFrame, "PLAYER_LOGIN"); tick(c, 1)
    local TV = c.QB.Travel
    c.taxiKnown = { [2] = true, [5] = true }
    local f = TV.frame
    f.__scripts.OnEvent(f, "PLAYER_ENTERING_WORLD"); tick(c, 3.1)
    local sw, lake = hubOf(c, "Stormwind"), hubOf(c, "Lakeshire")
    local me0 = { c = 0, wx = sw[3], wy = sw[4] }
    local function at(k) return { name = "Spot", c = 0, wx = sw[3] + (lake[3] - sw[3]) * k, wy = sw[4] + (lake[4] - sw[4]) * k } end
    local function flies(me, t) local p = TV.Route(me, t, TV.Opts("pin")); return p and #p.legs > 1 end
    -- the cut-off on the way from Stormwind's flight master toward Lakeshire's
    local lo, hi = 0.05, 1
    assert(not flies(me0, at(lo)) and flies(me0, at(hi)), "near Stormwind a walk, at Lakeshire a flight")
    for _ = 1, 40 do local mid = (lo + hi) / 2; if flies(me0, at(mid)) then hi = mid else lo = mid end end
    local t = at(hi + 0.002)
    -- 12 yards on toward it: under the hard cut-off a walk
    local dx, dy = t.wx - me0.wx, t.wy - me0.wy
    local len = math.sqrt(dx * dx + dy * dy)
    local me1 = { c = 0, wx = me0.wx + dx / len * 12, wy = me0.wy + dy / len * 12 }
    assert(flies(me0, t) and not flies(me1, t), "the spot lies at the cut-off")
    standAt(c, 0, me0.wx, me0.wy)
    local g = TV.Guide(me0, t, "pin")
    assert(g.leg and g.leg.kind == "fly", "at Stormwind's flight master: fly")
    standAt(c, 0, me1.wx, me1.wy)
    f.__scripts.OnEvent(f, "ZONE_CHANGED_NEW_AREA")
    g = TV.Guide(me1, t, "pin")
    assert(g.leg and g.leg.kind == "fly", "a zone's border 12 yards on: still fly, not a walk: " .. tostring(g.leg and g.leg.kind))
  end }

  -- R5: more trail segments within the minimap's reach than it draws (160): 5.4.3 took them cell by cell from a corner of
  -- the window and stopped at 160, and the trail you stand on was left out. Now the nearest to you are drawn
  RCASES[#RCASES + 1] = { "R5 the trails nearest you are drawn", function()
    local c = hillsClient("Rfive", { { 7, 0 } })
    local Walk = c.QB.Walk
    local W = Walk.DB()
    local far, near = {}, {}
    for i = 0, 240 do far[#far + 1] = -300; far[#far + 1] = -120 + i end         -- 240 segments 300 yards west, in the window's first cells
    for i = 0, 4 do near[#near + 1] = 15 * i; near[#near + 1] = 5 end              -- your trail: 4 segments where you stand
    W[0] = { far, near }
    Walk.dirty = true
    local got = Walk.Near(0, 0, 0, 400)
    local mine, worst = 0, 0
    for _, s in ipairs(got) do
      if s[2] == 5 and s[4] == 5 then mine = mine + 1 end
      worst = math.max(worst, math.min(s[1] ^ 2 + s[2] ^ 2, s[3] ^ 2 + s[4] ^ 2))
    end
    assert(#got == 160 and mine == 4, string.format("160 drawn, your own trail's 4 among them: %d, %d", #got, mine))
    -- and none drawn is farther than one left out
    local left = 0
    for i = 1, #far - 3, 2 do
      local d = math.min(far[i] ^ 2 + far[i + 1] ^ 2, far[i + 2] ^ 2 + far[i + 3] ^ 2)
      local drawn = false
      for _, s in ipairs(got) do if s[1] == far[i] and s[2] == far[i + 1] then drawn = true end end
      if not drawn and d < worst then left = left + 1 end
    end
    assert(left == 0, "the 160 nearest: " .. left .. " nearer ones left out")
    W[0] = nil
    Walk.dirty = true
  end }

  -- the golden path at its edges: 5.4.3 found your trails within 80 yards of you and kept you on the way within 20, and
  -- at either edge the path came and went, and was searched again, with each step. Now a band at each: a way shown keeps
  -- to 110 yards of your trails, and you stay on the way to 35 yards of it
  RCASES[#RCASES + 1] = { "the golden path keeps across the 80-yard and 20-yard edges", function()
    local c = hillsClient("Rgold", { { 7, 0 } })
    local QB = c.QB
    local Walk, MR = QB.Walk, QB.MiniRoute
    local W = Walk.DB()
    local trail = {}
    for i = 0, 100 do trail[#trail + 1] = i * 15; trail[#trail + 1] = 0 end -- 1,500 yards east along wy = 0
    W[0] = { trail }
    Walk.dirty = true
    local searches, path = 0, Walk.Path
    Walk.Path = function(...) searches = searches + 1; return path(...) end
    local goal = { c = 0, wx = 1500, wy = 0 }
    local function look(wx, wy) c.clock = c.clock + 2.1; return MR.Gold({ c = 0, wx = wx, wy = wy }, goal) end
    -- beside your trails, 75 and 85 yards off them in turn, 40 yards a step (off the way found a step before)
    local shown, changes, was = 0, 0, nil
    for k = 0, 9 do
      local on = look(100 + k * 40, k % 2 == 0 and 75 or 85)
      if on then shown = shown + 1 end
      if was ~= nil and on ~= was then changes = changes + 1 end
      was = on
    end
    assert(shown == 10 and changes == 0, string.format("75 and 85 yards off your trails: the way shown all along: %d shown, %d changes", shown, changes))
    -- along them, 18 and 22 yards off in turn (within the 15 seconds after which the way is searched again anyway, for
    -- trails noted meanwhile): on the way all along, no search again
    look(300, 0)
    searches = 0
    for k = 1, 6 do look(300 + k * 12, k % 2 == 0 and 18 or 22) end
    assert(searches == 0, "18 and 22 yards off the way: you stay on it, nothing searched again: " .. searches)
    Walk.Path = path
    W[0] = nil
    Walk.dirty = true
  end }

  -- the minimap's objective marks, at most 120: 5.4.3 filled them in the quest log's order, and a first quest's far spots
  -- crowded out the ones round you. Now the nearest
  RCASES[#RCASES + 1] = { "the minimap's 120 objective spots are the nearest", function()
    local c = hillsClient("Rspots", { { 500, 0 }, { 504, 0 } })
    local QB, D, Mini = c.QB, c.QB.Data, c.QB.Mini
    local saveSpot = { D.SPOT[500], D.SPOT[504] }
    local far = {}
    for i = 1, 130 do far[#far + 1] = string.format("k,1,1416,%d,%d,10,c", 300 + i, 300) end -- 130 spots up in Alterac
    D.SPOT[500] = table.concat(far, ";")
    D.SPOT[504] = "k,1,1424,500,590,10,c;k,1,1424,505,590,10,c" -- 2 where you stand, in Southshore
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE"); frame(c, 1)
    Mini.Invalidate()
    local n, mine = 0, 0
    for _, d in ipairs(Mini.List(true)) do
      if d.kind == "obj" then n = n + 1; if d.id == 504 then mine = mine + 1 end end
    end
    assert(n == 120 and mine == 2, string.format("120 marks, the 2 round you among them: %d, %d", n, mine))
    D.SPOT[500], D.SPOT[504] = saveSpot[1], saveSpot[2]
  end }

  -- R6: the Map page on Alterac (it follows you over the border), stop 1 back in Southshore on Hillsbrad's map, stops 2
  -- and 3 on Alterac's: 5.4.3 drew 2 to 3 only (a stop off the map had no place). Now the stroke from you to stop 1 runs to
  -- the map's edge the way it lies, then on from there to stop 2
  RCASES[#RCASES + 1] = { "R6 the Map page's strokes to a stop in the next zone", function()
    local c = hillsClient("Rsix", { { 7, 0 } })
    local QB, P, MP = c.QB, c.QB.Pins, c.QB.MapPage
    walkTo(c, -6, -899) -- Tarren Mill, on Alterac's map
    c.QB.UI:Open(8)
    assert(MP.canvas and MP.lines, "the Map page is built")
    local saveList = P.list
    P.list = { { m = 1424, x = 49.5, y = 58.7, num = 1, name = "Southshore", ids = {}, quests = {}, lines = {} },
               { m = 1416, x = 57.2, y = 69.5, num = 2, name = "Henchman Valik", ids = {}, quests = {}, lines = {} },
               { m = 1416, x = 45, y = 50, num = 3, name = "Crushridge Hold", ids = {}, quests = {}, lines = {} } }
    MP.Go(1416, "user")
    MP.lines:RefreshAllData()
    local strokes = MP.lines.active[1]
    local drawn, ends = {}, {}
    -- (each stroke's first and last line: one crossing a quest's icon is a line for each part)
    local seen = {}
    for _, l in ipairs(strokes and strokes.ctx.lines or {}) do
      if l.__shown then
        if not seen[l.of or l] then seen[l.of or l] = true; drawn[#drawn + 1] = l end
        ends[#drawn] = l
      end
    end
    assert(#drawn == 3, "you to stop 1 (to the map's edge), stop 1 to 2 (from it), 2 to 3: " .. #drawn)
    local h = strokes:GetHeight()
    assert(math.abs(ends[1].__stop[4] + h / 2) < 1 and math.abs(drawn[2].__start[4] + h / 2) < 1,
      "the strokes to and from stop 1 meet the map's bottom edge, the way Southshore lies")
    P.list = saveList
    P:Update()
  end }

  -- The walk the owner made: from Southshore north into Alterac, the Crushridge quests' objectives up there, their
  -- hand-in in Southshore. At every step the arrow (on the route), the minimap's stroke and the Map page's first stroke
  -- lead to one and the same place; the route is not planned again for walking, a kill, the bags or the zone's border,
  -- and what they lead to changes only when something real happens: a step of another quest's objective, an objective
  -- done, a quest complete. A quest done as the game reports it (complete in the log) keeps the target on the other
  -- quest's spot: 5.4.4 as first built then followed what was ready to hand in, and sent the arrow, the minimap and the
  -- Map page back to Southshore, 1,300 yards off, the other quest's spot at hand (the case set the objective done but
  -- not the quest complete, which the game never shows, and missed it); a delivery taken on the way (complete as you
  -- take it, handed in at Stormwind) sent them 9,000 yards off
  RCASES[#RCASES + 1] = { "the walk from Southshore to Alterac: one target, changed only by what you do", function()
    local c = hillsClient("Rwalk", { { 500, 0 }, { 504, 0 }, { 535, 0 } })
    local QB, D, A, Mini, MP = c.QB, c.QB.Data, c.QB.Arrow, c.QB.Mini, c.QB.MapPage
    local function spot(wx, wy) local t = HILLS[1416]; return string.format("%d,%d", math.floor((wy - t.wy0) / t.wyx * 10 + 0.5), math.floor((wx - t.wx0) / t.wxy * 10 + 0.5)) end
    local saveSpot, saveReq = { D.SPOT[500], D.SPOT[504], D.SPOT[535] }, { D.SREQ[500], D.SREQ[504] }
    D.SPOT[500] = "k,1,1416," .. spot(420, -700) .. ",20,c;k,1,1416," .. spot(520, -660) .. ",20,c"
    D.SPOT[504] = "k,1,1416," .. spot(470, -760) .. ",20,c"
    D.SPOT[535] = nil
    D.SREQ[500], D.SREQ[504] = "1:10", "1:10"
    c.objectives = { [500] = { { text = "Crushridge Ogre slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } },
                     [504] = { { text = "Crushridge Mage slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish()
    QB.Arrow:Set(true)
    QB.UI:Open(8)
    for _ = 1, 5 do frame(c, 0.1) end
    local plans = 0
    local sigNow, sigPlan = QB.sigNow, QB.sigPlan
    local function replans()
      if QB.sigNow ~= sigNow then plans = plans + 1; sigNow = QB.sigNow end
      if QB.sigPlan ~= sigPlan then plans = plans + 1; sigPlan = QB.sigPlan end
    end
    -- one look: the arrow, the minimap and the Map page lead to the same place (the Map page's first stroke drawn, at
    -- every look: a look with no stroke there checks nothing, and counts as a failure)
    local function agree(label)
      local t = A.t
      assert(t and t.kind == "route" and t.name, label .. ": the arrow is on the route")
      local aim = Mini.aim
      assert(aim and aim.name == t.name and math.abs((aim.wx or 0) - t.wx) + math.abs((aim.wy or 0) - t.wy) < 40 or (aim and aim.kind == "stop" and aim.name == t.name),
        label .. ": the minimap leads where the arrow does: " .. tostring(aim and aim.name) .. " / " .. tostring(t.name))
      local lines = MP.lines and MP.lines.active[1]
      assert(lines and lines.data, label .. ": the Map page draws its strokes")
      local d = lines.data
      local toward = d.via[#d.via] or d.stops[1]
      local m = MP.canvas:GetMapID()
      local x, y = QB.Model.MapPos(t.c, t.wx, t.wy, m)
      if not x then
        local tt = HILLS[m]
        x, y = (t.wy - tt.wy0) / tt.wyx / 100, (t.wx - tt.wx0) / tt.wxy / 100
      end
      assert(toward and math.abs(toward.x - x) < 0.02 and math.abs(toward.y - y) < 0.02,
        string.format("%s: the Map page's first stroke leads there too: %.3f, %.3f against %.3f, %.3f", label, toward and toward.x or -1, toward and toward.y or -1, x, y))
    end
    local function look()
      for _ = 1, 6 do frame(c, 0.1) end
      QB.Model.Finish(); Mini.Place(); MP.Tick(1)
    end
    frame(c, 0.1); Mini.Place(); MP.Tick(1)
    local first, target = firstStop(QB), A.t and A.t.name
    local targetAt = A.t and string.format("%.0f:%.0f", A.t.wx, A.t.wy)
    local startQ = A.t and A.t.obj and A.t.qid
    assert(startQ == 500 or startQ == 504, "at Southshore: a spot of one of the Crushridge quests: " .. tostring(A.t and A.t.name))
    local otherQ = startQ == 500 and 504 or 500
    agree("at Southshore")
    -- north, 40 yards a step, with what play brings on the way: a kill's XP, the bags, a step of that quest's objective
    local from, to = { -852, -517 }, { 470, -700 }
    for k = 1, 34 do
      local f = k / 34
      walkTo(c, from[1] + (to[1] - from[1]) * f, from[2] + (to[2] - from[2]) * f)
      if k % 3 == 0 then c.xp = (c.xp or 0) + 450; c.ev(QB.eventFrame, "PLAYER_XP_UPDATE", "player") end
      if k % 5 == 0 then c.ev(QB.eventFrame, "BAG_UPDATE_DELAYED") end
      if k % 7 == 0 then c.objectives[startQ][1].numFulfilled = c.objectives[startQ][1].numFulfilled + 1; c.ev(QB.eventFrame, "QUEST_LOG_UPDATE") end
      for _ = 1, 6 do frame(c, 0.1) end
      QB.Model.Finish()
      replans()
      Mini.Place(); MP.Tick(1)
      agree("step " .. k)
      assert(firstStop(QB) == first, string.format("step %d: the first stop stays %s: %s", k, first, tostring(firstStop(QB))))
      assert(A.t.name == target and string.format("%.0f:%.0f", A.t.wx, A.t.wy) == targetAt,
        string.format("step %d: what they lead to stays %s: %s", k, target, A.t.name))
    end
    assert(plans == 0, "walking, kills, the bags and the zone's border planned nothing again: " .. plans)
    -- a kill for the other quest: the quest kept stays (the first stop too). 5.4.4 as first built took the target to
    -- the other quest's spot: you were doing that one now; and a mob that counted for the quest kept and dropped an
    -- item for the other flipped it on every mob (the review's fourth round, B6CASES)
    c.objectives[otherQ][1].numFulfilled = 1
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    look()
    agree("a kill for the other quest")
    assert(A.t.obj and A.t.qid == startQ and firstStop(QB) == first, "a kill for the other quest: the quest kept, the same first stop: " .. tostring(A.t.name))
    c.objectives[otherQ][1].numFulfilled = 0
    -- the ogres done, as the game reports it: the objective finished and the quest complete. The target is the mages'
    -- spot, by the planned route (Log and pick-ups), whose first stop, Southshore, stays
    c.objectives[500][1].finished, c.objectives[500][1].numFulfilled = true, 10
    c.log = { { 500, 1 }, { 504, 0 }, { 535, 0 } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    look()
    agree("the ogres done")
    assert(QB.Target.Route() == QB.routePlan and #QB.routeNow.legs > 0, "questing: the route on screen is the planned one, a quest ready or not")
    assert(A.t.obj and A.t.qid == 504 and firstStop(QB) == first and math.sqrt((A.t.wx - 470) ^ 2 + (A.t.wy + 760) ^ 2) < 1,
      "the ogres done: the mages' spot, the same first stop: " .. tostring(A.t.name) .. ", " .. tostring(firstStop(QB)))
    -- both complete: everything goes back to Southshore to hand them in, and the three agree on it
    c.log = { { 500, 1 }, { 504, 1 }, { 535, 0 } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    look()
    agree("both complete")
    assert(not A.t.obj and A.t.name == "Southshore", "both complete: back to Southshore: " .. tostring(A.t.name))
    -- a delivery taken on the way: complete as you take it, handed in at Stormwind. The route is planned again for it,
    -- and the target is no hand-in of what is ready that the planner did not put first (Stormwind, 9,000 yards off):
    -- Southshore still, or, where the planner found the first stop it kept clearly worse (the hearthstone now best
    -- kept for Stormwind), the one it found better
    local deliver
    local ids = {}
    for id in pairs(D.Q) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do
      local q = QB.Quest.Get(id)
      local n = q and q.turnIdx and q.turnIdx > 0 and D.NPC[q.turnIdx]
      if n and n[2] == 1453 and QB.Quest.ForMe(q) and not q.repeatable and (q.req or 1) <= 30 and not (q.turn and q.turn.inside) then deliver = q break end
    end
    assert(deliver, "a quest handed in at Stormwind")
    c.log = { { 500, 1 }, { 504, 1 }, { 535, 0 }, { deliver.id, 1 } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    look()
    agree("a delivery taken")
    local r = QB.Target.Route()
    local alt = r.alt
    assert(r == QB.routePlan and A.t.name ~= "Stormwind" and A.t.name == firstStop(QB), "a delivery for Stormwind taken: the route's first stop: " .. tostring(A.t.name))
    assert(firstStop(QB) == first or (alt and alt.first == first and alt.t - r.t >= math.max(QB.Model.SWITCH * alt.t, 0.5) - 1e-9),
      "Southshore still, or a first stop clearly better: " .. tostring(firstStop(QB)))
    D.SPOT[500], D.SPOT[504], D.SPOT[535] = saveSpot[1], saveSpot[2], saveSpot[3]
    D.SREQ[500], D.SREQ[504] = saveReq[1], saveReq[2]
  end }

  -- Two quests of the stop, their spots strung along the walk north (the mages' passed on the way, the ogres' at its
  -- end), nothing done: 5.4.4 as first built kept the spot but not the quest, handed over to any spot of any of the
  -- stop's quests a quarter and 30 yards nearer, and three quarters of the way the objective went from one quest to the
  -- other with nothing done ("the objective completely changes running from Southshore to Alterac"). Now the quest is
  -- kept: one quest all the way, a kill for the other too (the review's fourth round: 5.4.4 as first built took the
  -- target to the other quest at that, and a mob that counted for one and dropped an item for the other flipped it)
  RCASES[#RCASES + 1] = { "two quests' spots along the walk: one quest all the way", function()
    local c = hillsClient("Rtwo", { { 500, 0 }, { 504, 0 } })
    local QB, D, A, Mini = c.QB, c.QB.Data, c.QB.Arrow, c.QB.Mini
    local function spot(wx, wy) local t = HILLS[1416]; return string.format("%d,%d", math.floor((wy - t.wy0) / t.wyx * 10 + 0.5), math.floor((wx - t.wx0) / t.wxy * 10 + 0.5)) end
    local saveSpot, saveReq = { D.SPOT[500], D.SPOT[504] }, { D.SREQ[500], D.SREQ[504] }
    D.SPOT[500] = "k,1,1416," .. spot(420, -700) .. ",20,c"
    D.SPOT[504] = "k,1,1416," .. spot(-300, -600) .. ",20,c"
    D.SREQ[500], D.SREQ[504] = "1:10", "1:10"
    c.objectives = { [500] = { { text = "Crushridge Ogre slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } },
                     [504] = { { text = "Crushridge Mage slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish()
    QB.Arrow:Set(true)
    for _ = 1, 5 do frame(c, 0.1) end
    local qids, changes, was = {}, 0, nil
    local from, to = { -852, -517 }, { 470, -700 }
    for k = 0, 34 do
      local f = k / 34
      walkTo(c, from[1] + (to[1] - from[1]) * f, from[2] + (to[2] - from[2]) * f)
      for _ = 1, 6 do frame(c, 0.1) end
      QB.Model.Finish(); Mini.Place()
      local t = A.t
      assert(t and t.obj and (t.qid == 500 or t.qid == 504), "step " .. k .. ": an objective's spot: " .. tostring(t and t.name))
      assert(Mini.aim and Mini.aim.name == t.name, "step " .. k .. ": the minimap leads there too")
      if was and t.qid ~= was then changes = changes + 1 end
      was = t.qid
      qids[t.qid] = true
    end
    assert(changes == 0 and qids[504] and not qids[500], "one quest all the way, the mages' (the nearer at Southshore): " .. changes .. " changes")
    -- an ogre slain at the end of the walk: still the mages' spot
    c.objectives[500][1].numFulfilled = 1
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 6 do frame(c, 0.1) end
    QB.Model.Finish(); Mini.Place()
    assert(A.t.obj and A.t.qid == 504, "an ogre slain: still the mages' spot: " .. tostring(A.t.name))
    D.SPOT[500], D.SPOT[504] = saveSpot[1], saveSpot[2]
    D.SREQ[500], D.SREQ[504] = saveReq[1], saveReq[2]
  end }

  -- the flight paths you know: once the client says which, the planner flies only those (as the arrow does). Near Alterac
  -- the flight master you fly from is Southshore's, not Chillwind Camp's you never found, and the planner's minutes to
  -- Stormwind are the arrow's way's
  RCASES[#RCASES + 1] = { "the planner flies the flight paths you know", function()
    local c = hillsClient("Rfly", { { 7, 0 } })
    local QB, TV, M = c.QB, c.QB.Travel, c.QB.Model
    c.taxiKnown = { [2] = true, [14] = true } -- Stormwind and Southshore
    local f = TV.frame
    f.__scripts.OnEvent(f, "PLAYER_ENTERING_WORLD"); frame(c, 3.1)
    assert(M.Place("A", 0, 203, -818).hub == 21 and TV.Partial("A"), "flight paths read, Chillwind Camp's not known: Southshore's is the one to fly from")
    local sw = hubOf(c, "Stormwind")
    local here, swPlace = M.Place("A", 0, 203, -818), M.Place("A", 0, sw[3] + 20, sw[4])
    local plan = TV.Route({ c = 0, wx = 203, wy = -818 }, { name = "Stormwind", c = 0, wx = sw[3] + 20, wy = sw[4] }, TV.Opts("route"))
    local mins = M.Between(here, swPlace, "A", M.Factor(false))
    assert(plan and math.abs(mins - plan.min) < 1.5, string.format("the planner's minutes to Stormwind are the arrow's: %.1f and %.1f", mins, plan and plan.min or -1))
    c.taxiKnown = nil
  end }

  -- /qb trace: opt-in, a ring of 200 lines in the saved file, the last 30 printed, cleared when switched off
  RCASES[#RCASES + 1] = { "/qb trace", function()
    local c = hillsClient("Rtrace", { { 500, 1 }, { 501, 1 } })
    local QB, env = c.QB, c.env
    assert(not QB.tracing and env.QuestBankDB.trace == nil, "off by default")
    env.SlashCmdList.QUESTBANK("trace on")
    assert(QB.tracing and env.QuestBankDB.trace.on, "on")
    QB.Arrow:Set(true)
    for _ = 1, 5 do frame(c, 0.1) end
    -- Southshore's quest handed in: the route goes to Tarren Mill
    c.log, c.done[500] = { { 501, 1 } }, true
    c.ev(QB.eventFrame, "QUEST_TURNED_IN", 500, 1150, 0)
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish()
    for _ = 1, 5 do frame(c, 0.1) end
    local lines = env.QuestBankDB.trace.lines
    local all = table.concat(lines, "\n")
    assert(all:find("re-plan", 1, true) and all:find("your quests or their state", 1, true) and all:find("target: ", 1, true), "a re-plan and why, the target:\n" .. all)
    for i = 1, 260 do QB.Trace("line %d", i) end
    assert(#lines == 200 and lines[200]:find("line 260$"), "the last 200 kept")
    c.chat = {}
    env.SlashCmdList.QUESTBANK("trace print")
    assert(#c.chat == 31 and c.chat[#c.chat]:find("line 260"), "print: a header and the last 30: " .. #c.chat)
    -- a loading screen: noted as a jump alone (the re-plan line says whether one followed: Core.lua)
    local T = QB.Target
    T.frame.__scripts.OnEvent(T.frame, "PLAYER_ENTERING_WORLD")
    assert(lines[#lines]:find("a jump in place %(a loading screen%)$"), "a jump, noted as such: " .. lines[#lines])
    env.SlashCmdList.QUESTBANK("trace off")
    assert(not QB.tracing and env.QuestBankDB.trace == nil, "off: cleared")
  end }

  -- Zephras Isle, Forever's own starting zone, lies off the two continents on a world of its own (map 2991 under its
  -- zone map 2521). 5.4.3 placed nothing there: Data.lua gave its 56 NPCs continent -1, as inside an instance, so the
  -- 120 quests handed in there were left out of Now, Available and Highest XP (and filed under "Other quests" where
  -- they showed), the route could not place them, and the arrow, the minimap and the minutes had nothing to go on. A
  -- level-5 character on the isle: the client places it as Data.lua does, its quests are on a card of their own with
  -- minutes, a hand-in there is routed, and the arrow and the minimap lead to it. Inside a dungeon nothing is placed,
  -- as before
  local ISLE = { minx = 1247.917, maxx = 4956.25, miny = -1331.25, maxy = 4231.25 } -- UiMapAssignment's, map 2521
  local function isleClient(name, log, done)
    local c = newClient({ name = name, level = 5, cap = 60, faction = "Alliance", className = "Mage", class = "MAGE", classID = 8,
      race = "Human", log = log, done = done or {}, world = { 2991, 3200, 1650 }, map = 2521, bagSlots = {}, bind = "Shen'dar Village" })
    local env = c.env
    c.me = { wx = 3200, wy = 1650 }
    local function toMap(wx, wy) return (ISLE.maxy - wy) / (ISLE.maxy - ISLE.miny), (ISLE.maxx - wx) / (ISLE.maxx - ISLE.minx) end
    env.C_Map.GetBestMapForUnit = function() return 2521 end
    env.MapUtil.GetDisplayableMapForPlayer = function() return 2521 end
    env.C_Map.GetPlayerMapPosition = function(m)
      if m ~= 2521 then return nil end
      local x, y = toMap(c.me.wx, c.me.wy)
      return { x = x, y = y, GetXY = function(self) return self.x, self.y end }
    end
    env.C_Map.GetMapPosFromWorldPos = function(cont, pos, m)
      if cont ~= 2991 or m ~= 2521 then return nil end
      return m, env.CreateVector2D(toMap(pos.x, pos.y))
    end
    env.C_Map.GetMapRectOnMap = function() return nil end
    env.IsInInstance = function() return false, "none" end
    login(c)
    return c
  end
  RCASES[#RCASES + 1] = { "Zephras Isle at level 5", function()
    -- Foul Matriarch done (Aetheen of the Gales takes it, 900 yards north), Al'Aketh Thugs under way, a quest of Elwynn's
    -- done too (handed in across the sea, which the planner knows no way to)
    local c = isleClient("Isle", { { 92470, 1 }, { 92544, 0 }, { 7, 1 } })
    local QB, D, M, UI, A, Mini = c.QB, c.QB.Data, c.QB.Model, c.QB.UI, c.QB.Arrow, c.QB.Mini
    local function npc(name) for i, n in ipairs(D.NPC) do if n[1] == name and n[2] == 2521 then return i, n end end end
    local ai, an = npc("Aetheen of the Gales")
    local w = M.World(2521, an[3], an[4])
    assert(an[5] == 2991 and w and w.c == 2991 and math.abs(w.wx - an[6]) < 2 and math.abs(w.wy - an[7]) < 2,
      "the client and Data.lua place the isle alike, on its own world: " .. tostring(w and w.c))
    local me = QB.API.WorldPosition()
    assert(me and me.c == 2991 and math.abs(me.wx - 3200) < 1, "where you stand on the isle")
    local q = QB.Quest.Get(92470)
    assert(q.cat and q.cat.name == "Zephras Isle" and q.cat.key ~= "misc" and not q.turn.inside, "the isle's quests on its own card, not Other quests, and not inside")
    c.instWorld = { [1581] = true }
    assert(M.World(1581, 50, 50) == nil, "a dungeon's map: nothing placed, as before")
    c.instWorld = nil
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE"); frame(c, 1); QB.Model.Finish(); frame(c, 1)
    QB:Recompute(true)
    -- the route: Aetheen first, walked to from where you stand; Elwynn after, across the sea: by the hearthstone (the
    -- planner's, an inn you bind first), or with no way known and no minutes made up for it
    local r = QB.routeNow
    local l1 = r and r.legs[1]
    assert(r and r.fromHere and l1 and l1.stop.c == 2991 and l1.stop.npcs[1] == ai and l1.kind == "foot" and l1.travel > 1 and l1.travel < 10 and #r.unplaced == 0,
      "the hand-in on the isle is routed, walked to from you: " .. tostring(l1 and l1.stop.name) .. ", " .. tostring(l1 and l1.kind) .. " " .. tostring(l1 and l1.travel))
    local l2 = r.legs[2]
    assert(#r.legs == 2 and l2.stop.c == 0 and ((l2.kind == "none" and l2.late) or l2.kind == "hearth") and r.t < 60,
      string.format("then Elwynn, after the isle: %s by %s, %.1f min in all", tostring(l2 and l2.stop.name), tostring(l2 and l2.kind), r.t))
    -- the hearthstone not ready: no way to Elwynn known from the isle. That leg counts no minutes (the route's own stay
    -- the isle's), comes after the isle and reads so on the Route page
    local function fake(id, npc) return { q = { id = id, turnIdx = npc, lvl = 5, base = 500, mult = 1, name = "Q" .. id }, st = { code = "banked" } } end
    local rr = M.Plan({ fake(990101, QB.Quest.Get(7).turnIdx), fake(990102, ai) },
      { level = 5, xp = 0, goal = "route", fac = "A", start = { c = 2991, wx = 3200, wy = 1650 }, mounted = false, noHearth = true })
    assert(#rr.legs == 2 and rr.legs[1].stop.c == 2991 and rr.legs[2].kind == "none" and rr.legs[2].late and rr.legs[2].travel == 0 and rr.t < 30,
      string.format("no way known: %s by %s, %.1f min in all", tostring(rr.legs[2] and rr.legs[2].stop.name), tostring(rr.legs[2] and rr.legs[2].kind), rr.t))
    local keep, keepPlan = QB.routeNow, QB.routePlan
    QB.routeNow, QB.routePlan = rr, rr -- (questing, the page shows the planned route)
    UI:Open(3); UI:Refresh()
    local said
    for _, l in ipairs(UI.views[3].legs.items) do if l:IsShown() and l.travel:GetText() == "No known way there" then said = true end end
    assert(said, "the Route page: No known way there")
    QB.routeNow, QB.routePlan = keep, keepPlan
    -- the minutes: the isle's givers walked to, in Available's rows and the Highest XP finder
    local cand
    for _, cc in ipairs(UI:Candidates(nil, 5)) do if cc.id == 92472 then cand = cc end end
    assert(cand and cand.mins and cand.mins > 0 and cand.mins < 15 and not cand.waste, "The Next Step: a candidate with its minutes on foot: " .. tostring(cand and cand.mins))
    -- Now and Available: a Zephras Isle card with minutes, no isle quest under Other quests
    for _, tab in ipairs({ 6, 2 }) do
      UI:Open(tab); QB.Model.Finish(); UI:Refresh()
      local isle, misc
      for _, card in ipairs(UI.views[tab].cards.items) do
        if card:IsShown() and card.title:GetText() == "Zephras Isle" then isle = card end
        if card:IsShown() and card.title:GetText() == "Other quests" then misc = card end
      end
      assert(isle and (isle.where:GetText():find("min away", 1, true) or isle.where:GetText():find("you're here", 1, true)),
        (tab == 6 and "Now" or "Available") .. ": a Zephras Isle card with minutes: " .. tostring(isle and isle.where:GetText()))
      for _, row in ipairs(misc and misc.rows.items or {}) do
        assert(not (row:IsShown() and row.q and row.q.cat and row.q.cat.name == "Zephras Isle"), "no isle quest under Other quests")
      end
    end
    UI:Open(1); UI.findMode = "xp"; UI:Refresh()
    local xpRow
    for _, row in ipairs(UI.views[1].swaps) do if row:IsShown() and row.add and row.add.cat and row.add.cat.name == "Zephras Isle" then xpRow = row break end end
    assert(xpRow and (xpRow.cutName:GetText():find(" · %d+ min") or xpRow.cutName:GetText():find(" · here", 1, true)),
      "Highest XP: the isle's quests, with their trip: " .. tostring(xpRow and xpRow.cutName:GetText()))
    -- the arrow and the minimap lead to the route's first stop, on the isle (questing, the planned route: Aetheen, or
    -- the Thugs' hand-in or a spot of theirs), in yards and minutes
    A:Set(true)
    for _ = 1, 5 do frame(c, 0.1) end
    Mini.Place()
    local F = c.env.QuestBankArrow
    local s1 = QB.Target.Route().legs[1].stop
    assert(A.t and A.t.kind == "route" and A.t.c == 2991 and s1.c == 2991 and A.t.stop == s1.name and F.dist:GetText():find("yards · %d+ min$"),
      "the arrow points at the isle's stop: " .. tostring(A.t and A.t.name) .. " | " .. tostring(F.dist:GetText()))
    assert(Mini.aim and Mini.aim.name == A.t.name, "the minimap leads there too: " .. tostring(Mini.aim and Mini.aim.name))
    local pinned = false
    for _, d in ipairs(Mini.ListCached()) do
      local dw = d.wx and d or (d.m and M.World(d.m, d.x, d.y))
      if dw and dw.c == 2991 then pinned = true end
    end
    assert(pinned, "and pins the isle's stop and spots on the minimap")
    -- the Map page on the isle's map, nothing amiss
    UI:Open(8)
    for _ = 1, 3 do frame(c, 0.1) end
    QB.MapPage.Tick(1)
    assert(QB.MapPage.canvas:GetMapID() == 2521, "the Map page shows the isle")
    UI.findMode = nil
  end }

  -- The review of 5.4.4 (each case below failed on the files before this round):
  -- the world map lists only the flight paths you found, and you know none on your land (only Theramore's, across the
  -- sea): the planner found no flight master to start from, and the route, from Southshore, started at Tarren Mill
  local function onlyFound(c)
    local all = c.env.C_TaxiMap.GetTaxiNodesForMap
    c.env.C_TaxiMap.GetTaxiNodesForMap = function(m)
      local out = {}
      for _, e in ipairs(all(m)) do if not e.isUndiscovered then out[#out + 1] = e end end
      return out
    end
  end
  RCASES[#RCASES + 1] = { "flight paths known only off your land: the route starts from you", function()
    local c = hillsClient("Roff", { { 500, 1 }, { 501, 1 } })
    local QB, TV, M = c.QB, c.QB.Travel, c.QB.Model
    onlyFound(c)
    c.taxiKnown = { [hubOf(c, "Theramore")[6]] = true }
    local f = TV.frame
    f.__scripts.OnEvent(f, "PLAYER_ENTERING_WORLD"); frame(c, 3.1)
    QB:Recompute(true); QB.Model.Finish()
    local r = QB.routeNow
    assert(TV.tells and TV.Partial("A") and M.Place("A", 0, -852, -517).hub > 0, "Theramore alone known: a place to start from all the same")
    assert(r.fromHere and r.legs[1] and r.legs[1].kind ~= "start" and QB.routePlan.fromHere and QB.UI.Here(),
      "the route from where you stand: " .. tostring(r.legs[1] and r.legs[1].kind) .. " to " .. tostring(r.legs[1] and r.legs[1].stop.name))
    c.taxiKnown = nil
  end }

  -- the minimap's blue quest area: the quest the one target leads to (5.4.4 as first built showed the first quest of
  -- your log at stop 1, the ogres' while the arrow led to the mages')
  RCASES[#RCASES + 1] = { "the minimap's quest area is the target's quest", function()
    local c = hillsClient("Rarea", { { 500, 0 }, { 504, 0 } })
    local QB, D, A, Mini, MV = c.QB, c.QB.Data, c.QB.Arrow, c.QB.Mini, c.QB.MiniView
    local function spot(wx, wy) local t = HILLS[1416]; return string.format("%d,%d", math.floor((wy - t.wy0) / t.wyx * 10 + 0.5), math.floor((wx - t.wx0) / t.wxy * 10 + 0.5)) end
    local saveSpot, saveReq = { D.SPOT[500], D.SPOT[504] }, { D.SREQ[500], D.SREQ[504] }
    D.SPOT[500] = "k,1,1416," .. spot(420, -700) .. ",20,c"
    D.SPOT[504] = "k,1,1416," .. spot(470, -790) .. ",20,c"
    D.SREQ[500], D.SREQ[504] = "1:10", "1:10"
    c.objectives = { [500] = { { text = "Crushridge Ogre slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } },
                     [504] = { { text = "Crushridge Mage slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } } }
    standAt(c, 0, 470, -790); c.me.wx, c.me.wy = 470, -790
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish()
    A:Set(true)
    for _ = 1, 5 do frame(c, 0.1) end
    Mini.Place()
    assert(A.t and A.t.obj and A.t.qid == 504 and MV.AreaQuest() == 504, "the mages' spot, and their area: " .. tostring(MV.AreaQuest()))
    D.SPOT[500], D.SPOT[504] = saveSpot[1], saveSpot[2]
    D.SREQ[500], D.SREQ[504] = saveReq[1], saveReq[2]
  end }

  -- a stroke softened only where it crosses another quest's icon: walking sideways past an icon beside the stroke from
  -- you, its first part (from you) stays at full strength (5.4.4 as first built dimmed the whole stroke as long as any
  -- icon lay on it, and it came back at the band's edge)
  RCASES[#RCASES + 1] = { "the stroke from you, softened only where it crosses an icon", function()
    local c = hillsClient("Rsoft", { { 500, 0 }, { 7, 0 } })
    local QB, D, A, Mini, MR = c.QB, c.QB.Data, c.QB.Arrow, c.QB.Mini, c.QB.MiniRoute
    local function spot(wx, wy) local t = HILLS[1416]; return string.format("%d,%d", math.floor((wy - t.wy0) / t.wyx * 10 + 0.5), math.floor((wx - t.wx0) / t.wxy * 10 + 0.5)) end
    local saveSpot, saveReq = { D.SPOT[500], D.SPOT[7], D.SPOT[504] }, { D.SREQ[500], D.SREQ[7] }
    D.SPOT[500] = "k,1,1416," .. spot(450, -700) .. ",20,c"
    D.SPOT[7] = "k,1,1416," .. spot(260, -697) .. ",20,c"
    D.SPOT[504] = nil
    D.SREQ[500], D.SREQ[7] = "1:10", "1:10"
    c.objectives = { [500] = { { text = "Crushridge Ogre slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } },
                     [7] = { { text = "Kobold Vermin slain: 0/10", type = "monster", finished = false, numFulfilled = 0, numRequired = 10 } } }
    c.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish()
    A:Set(true)
    walkTo(c, 200, -700)
    for _ = 1, 10 do frame(c, 0.1) end
    QB.Model.Finish(); Mini.Place()
    assert(A.t and A.t.obj and A.t.qid == 500, "the target: the ogres' spot, the kobolds' icon on the way")
    -- each look: the alphas of the stroke from you (its parts: the lines of stroke 1)
    local full, soft, dimmedWhole = QB:Settings().zmAlpha or 1, 0, 0
    for k = 0, 16 do
      walkTo(c, 200, -760 + k * 7.5)
      frame(c, 0.05)
      Mini.Place()
      local most, least = 0, 1
      for i = 1, MR.route.used do
        local l = MR.route.lines[i]
        -- (before 5.4.4's review a stroke was one line: the first)
        if l.of == 1 or (l.of == nil and i == 1) then most, least = math.max(most, l.__vertex[4]), math.min(least, l.__vertex[4]) end
      end
      if most < full - 1e-6 then dimmedWhole = dimmedWhole + 1 end
      if least < full - 1e-6 then soft = soft + 1 end
    end
    assert(dimmedWhole == 0, "the stroke from you never dimmed whole: " .. dimmedWhole .. " looks")
    assert(soft > 0, "and softened where it crosses the kobolds' icon")
    D.SPOT[500], D.SPOT[7], D.SPOT[504] = saveSpot[1], saveSpot[2], saveSpot[3]
    D.SREQ[500], D.SREQ[7] = saveReq[1], saveReq[2]
  end }

  for _, case in ipairs(RCASES) do
    case[2]()
    print("5.4.4 " .. case[1] .. ": ok")
  end
end)()

----------------------------------------------------------------------------
-- 5.4.4: the owner's play test of 5.4.3 (2026-10-20, a level-21 mage), and what he asked for after it. Each case below
-- failed on the files before this round (run them alone against an older QuestBank: the cases are in B3CASES, in
-- order, after the harness's helpers, with HERE pointed there) and passes now:
--   a hand-in in reach first, whatever its value ("it told me to go to Booty Bay despite standing a few meters from a
--   quest hand-in"); a click shows a place for now and changes no route ("all it takes for me to break routing is
--   clicking a quest"); QuestBank's own arrow by default again; Accept for me a choice; the sparkle without health
--   bars; no light on a trainer you can't use; thinner strokes under the quest icons; the missing-buffs banner kept
--   while you use it; sellers of camp goods learned; Skip this quest; flight paths per character; quest icons half
--   size; the golden path joined ahead of you
----------------------------------------------------------------------------
;(function()
  local B3CASES = {}
  -- a level-21 human mage of the Alliance, questing (no cap, no lock), standing at (wx, wy) on the Eastern Kingdoms
  local function mage(name, log, done, wx, wy, saved)
    local c = newClient({ name = name, level = 21, cap = 60, faction = "Alliance", className = "Mage", class = "MAGE", classID = 8,
      race = "Human", log = log or {}, done = done or {}, world = { 0, wx or -9200, wy or -2150 }, map = 1433, bagSlots = {}, bind = "Lakeshire" })
    if saved then c.env.QuestBankDB = saved end
    login(c)
    return c
  end
  -- one frame of play: the clock, the timers due, every shown frame's OnUpdate once
  local function frame(c, dt)
    c.clock = c.clock + dt
    table.sort(c.timers, function(a, b) return a.t < b.t end)
    while c.timers[1] and c.timers[1].t <= c.clock do table.remove(c.timers, 1).f() end
    for _, f in ipairs(c.frames) do
      local u = f.__scripts.OnUpdate
      if u and f:IsVisible() then u(f, dt) end
    end
  end
  local function settle(c)
    c.ev(c.QB.eventFrame, "QUEST_LOG_UPDATE")
    for _ = 1, 5 do frame(c, 0.1) end
    c.QB.Model.Finish()
    c.QB:Recompute(true)
    c.QB.Model.Finish()
    for _ = 1, 3 do frame(c, 0.1) end
  end
  local function said(c) return c.chat[#c.chat] or "" end
  local function copy(t)
    if type(t) ~= "table" then return t end
    local o = {}
    for k, v in pairs(t) do o[k] = copy(v) end
    return o
  end
  -- the catalog's quests for a level-21 Alliance mage: pred(q, npc, xp) over each one with a hand-in NPC on a continent,
  -- the lowest id first
  local function catalog(c, pred)
    local QB, D = c.QB, c.QB.Data
    local ids = {}
    for id in pairs(D.Q) do ids[#ids + 1] = id end
    table.sort(ids)
    for _, id in ipairs(ids) do
      local q = QB.Quest.Get(id)
      local n = q and q.turnIdx and q.turnIdx > 0 and D.NPC[q.turnIdx]
      if n and n[5] == 0 and QB.Quest.ForMe(q) and not q.repeatable and not (q.turn and q.turn.inside) and (q.req or 1) <= 21 then
        local xp = QB.Model.XpAt(q, 21)
        if pred(q, n, xp) then return q, n end
      end
    end
  end
  local function line(c) return (c.QB.Model.CHEAP or 400) * c.QB.Scale(21) end

  -- 1. a hand-in a few yards away comes first, whatever it pays; one the route passes goes as it passes; one that costs
  -- a trip still goes last
  B3CASES[#B3CASES + 1] = { "a hand-in in reach first, whatever its value", function()
    local c = mage("Bone")
    local QB, M, D = c.QB, c.QB.Model, c.QB.Data
    local cheap, cn = catalog(c, function(q, n, xp) return n[2] == 1433 and xp > 0 and xp < line(c) end)
    local rich, rn = catalog(c, function(q, n, xp) return n[2] == 1436 and xp >= 4 * line(c) end)
    assert(cheap and rich, "a hand-in worth little in Redridge and one worth a lot in Westfall")
    -- the mage stands 10 yards from the cheap one's NPC, both quests done
    c.log = { { cheap.id, 1 }, { rich.id, 1 } }
    standAt(c, 0, cn[6] + 10, cn[7])
    settle(c)
    local r = QB.routeNow
    assert(r and r.legs[1] and r.legs[1].stop.npcs[1] == cheap.turnIdx and r.legs[2] and r.legs[2].stop.npcs[1] == rich.turnIdx,
      "the route hands the near one in first: " .. tostring(r and r.legs[1] and r.legs[1].stop.name))
    local t = QB.Target.Get(QB.API.WorldPosition())
    assert(t and not t.obj and t.qid == cheap.id and (t.label or ""):find("^Hand in ") and (t.label or ""):find(" here$"),
      "the one target: Hand in " .. cheap.name .. " here: " .. tostring(t and t.label))
    QB.Arrow:Set(true)
    for _ = 1, 3 do frame(c, 0.1) end
    local F = c.env.QuestBankArrow
    assert(F.name:GetText() == t.label or F.name:GetText():find("^Hand in here: "), "the arrow's label says so (a long name: the words first): " .. tostring(F.name:GetText()))
    -- the planner on its own: a stop in reach first; a cheap one the route passes (under a minute's detour) handed in on
    -- the way; a cheap one off the way (a trip of its own) last
    local function fake(id, npc, base) return { q = { id = id, turnIdx = npc, lvl = 21, base = base, mult = 1, name = "Q" .. id }, st = { code = "banked" } } end
    -- three NPCs in a line east of Lakeshire's flight master, out of town (400, 650 and 900 yards; the middle one 5
    -- yards off the line), made for the case, and one far off (the Westfall hand-in above)
    local lh, lhi = hubOf(c, "Lakeshire")
    local walkOf = function(d) return d * M.DETOUR / M.RUN / 60 end
    local base = #D.NPC
    for k, d in ipairs({ 400, 650, 900 }) do
      D.NPC[base + k] = { "Case NPC " .. k, 1433, 50, 50, 0, lh[3], lh[4] - d + (k == 2 and 5 or 0), lhi, walkOf(d), 0, 0 }
    end
    local a, mid, b = base + 1, base + 2, base + 3
    local far = rn and rich.turnIdx
    local na = D.NPC[a]
    local start = { c = 0, wx = na[6] + 5, wy = na[7] }
    local entries = { fake(990301, a, 3000), fake(990302, b, 3000), fake(990303, mid, 50), fake(990304, far, 50) }
    local plan = M.Plan(entries, { level = 21, xp = 0, goal = "hour", fac = "A", start = start, mounted = false })
    local order = {}
    for _, l in ipairs(plan.legs) do order[#order + 1] = l.stop.npcs[1] == a and "near" or l.stop.npcs[1] == b and "far end" or l.stop.npcs[1] == mid and "passed" or "trip" end
    for k = 1, 3 do D.NPC[base + k] = nil end
    assert(table.concat(order, ",") == "near,passed,far end,trip", "in reach first, the one passed on the way, then the far end; the cheap trip last: " .. table.concat(order, ","))
  end }

  -- 2. a click shows the place on the arrow for now; reached and handed in, the route is the one a player who never
  -- clicked has. And on the world map (QuestBank's layer) and the Map page: a plain click shows, a labelled Shift-click
  -- adds or takes out
  B3CASES[#B3CASES + 1] = { "a click shows it for now; the route as if it never happened", function()
    local q, n = nil, nil
    local function twin(name)
      local c = mage(name)
      if not q then
        q, n = catalog(c, function(qq, nn, xp) return nn[2] == 1433 and xp >= 1000 end)
        assert(q, "a quest handed in in Redridge")
      end
      local other = catalog(c, function(qq, nn, xp) return qq.id ~= q.id and nn[2] == 1433 and xp >= 1000 and qq.turnIdx ~= q.turnIdx end)
      c.log = { { q.id, 1 }, { other.id, 1 } }
      standAt(c, 0, n[6] + 400, n[7] + 300)
      settle(c)
      c.QB.Arrow:Set(true)
      for _ = 1, 3 do frame(c, 0.1) end
      return c
    end
    local clicked, plain = twin("Clicker"), twin("Plain")
    local QB, A, F = clicked.QB, clicked.QB.Arrow, clicked.env.QuestBankArrow
    local plan0 = copy(QB:Plan())
    QB.UI.QuestClick(q, QB:Status(q), "LeftButton")
    frame(clicked, 0.1)
    local t = A.Target()
    assert(A.Mode() == "route" and t and t.temp and t.qid == q.id and t.what == "turn", "a click: the hand-in shown for now, the arrow's choice kept on the route")
    assert(F.name:GetText():find("^Showing ") and F.hint:IsShown() and F.hint:GetText() == "Right-click: back to your route", "its label: Showing, and the way back: " .. F.name:GetText())
    for _, k in ipairs({ "add", "cut", "skip" }) do assert(next(QB:Plan()[k] or {}) == next(plan0[k] or {}), "the click changed no plan: " .. k) end
    -- reached: it goes a few seconds later, and the arrow says it is back on the route
    standAt(clicked, 0, n[6] + 3, n[7])
    for _ = 1, 60 do frame(clicked, 0.1) end
    assert(not A.temp and A.Target() and A.Target().kind == "route" and F.hint:GetText() == "Back to your route", "reached: back on the route, said once")
    -- handed in, by both
    for _, c in ipairs({ clicked, plain }) do
      for i = #c.log, 1, -1 do if c.log[i][1] == q.id then table.remove(c.log, i) end end
      c.done[q.id] = true
      c.ev(c.QB.eventFrame, "QUEST_TURNED_IN", q.id, 1000, 0)
      standAt(c, 0, n[6] + 3, n[7])
      settle(c)
    end
    local function route(c)
      local out = {}
      for _, l in ipairs(c.QB.routeNow.legs) do out[#out + 1] = l.stop.name end
      return table.concat(out, " > ")
    end
    assert(route(clicked) == route(plain) and #clicked.QB.routeNow.legs > 0, "the route as a player's who never clicked: " .. route(clicked) .. " / " .. route(plain))
    assert(A.Mode() == "route" and A.Target().kind == "route" and A.Target().name == plain.QB.Arrow.Target().name, "the arrow on the route, as the other's")
    -- clicked again, then handed in without getting there: over at once
    local other = clicked.log[1][1]
    local oq = QB.Quest.Get(other)
    QB.UI.QuestClick(oq, QB:Status(oq), "LeftButton")
    assert(A.temp and A.temp.qid == other, "shown for now")
    clicked.log = {}
    clicked.done[other] = true
    settle(clicked)
    assert(not A.temp and A.Target() == nil or (A.Target() and not A.Target().temp), "its quest handed in: over, without getting there")
    -- the world map's quest icons and the Map page's (QuestMap.lua's click, one for both): a plain click shows, Shift adds
    local QM = QB.QuestMap
    local give
    for _, d in ipairs(QM:Build(1433, false)) do if d.kind == "give" and d.quests and d.quests[1] then give = give or d end end
    assert(give, "a ! on Redridge's map")
    local gid = give.quests[1].id
    clicked.shift = false
    QM.ClickForTest(give, "LeftButton")
    assert(A.temp and A.temp.what == "give" and not QB:IsAdded(gid) and A.Mode() == "route", "a plain click on a !: shown for now, and nothing more")
    clicked.shift = true
    QM.ClickForTest(give, "LeftButton")
    assert(QB:IsAdded(gid) and said(clicked):find("Added to your route", 1, true), "Shift-click: Add to my route, said so")
    QM.ClickForTest(give, "LeftButton")
    assert(not QB:IsAdded(gid) and said(clicked):find("Out of your route", 1, true), "Shift-click again: out of it")
    clicked.shift = false
    lines = {}
    QM.IconMethods.OnMouseEnter({ data = give, layer = { world = true } })
    local tip = table.concat(lines, "\n")
    assert(tip:find("<Click to show it on the arrow for now>", 1, true) and tip:find("<Shift-click: add to my route>", 1, true), "its tooltip says both: " .. tip)
    -- the route's own pins (Pins.lua, on the world map and the Map page): a click shows, nothing more
    local P = QB.Pins
    local pin
    for _, d in ipairs(P.list or {}) do if d.num then pin = pin or d end end
    if pin then
      local before = copy(QB:Plan())
      P.Pin.OnMouseClickAction({ data = pin }, "LeftButton")
      assert(A.temp and A.Mode() == "route" and next(QB:Plan().skip) == next(before.skip or {}), "a route pin: shown for now, nothing more")
    end
    -- right-click while shown: back to the route at once
    F.__scripts.OnClick(F, "RightButton")
    assert(not A.temp and A.Target() == nil or not A.Target().temp, "right-click: back")
  end }

  -- 3. QuestBank's own arrow is the default again; the compass an option, kept by a save that chose it
  B3CASES[#B3CASES + 1] = { "QuestBank's own arrow by default; the compass kept where chosen", function()
    local function arrowOf(c)
      c.QB.Arrow:Set(true)
      for _ = 1, 3 do frame(c, 0.1) end
      return c.env.QuestBankArrow
    end
    local fresh = mage("Fresh")
    local F = arrowOf(fresh)
    assert(not fresh.QB.Arrow.QT() and fresh.QB:Settings().arrowStyle == "questbank" and F.arrow.__atlas == "npe_arrowup" and not F.dial:IsShown(),
      "a fresh save: QuestBank's arrow (the game's tutorial arrow, coloured by your heading)")
    local old = mage("Old", nil, nil, nil, nil, { settings = { markerStyle = "questtrail", arrow = true, compassSize = 48 } })
    assert(not old.QB.Arrow.QT(), "a 5.4.3 save that never chose: QuestBank's arrow")
    local chose = mage("Chose", nil, nil, nil, nil, { settings = { arrowStyle = "compass", arrow = true } })
    local CF = arrowOf(chose)
    assert(chose.QB.Arrow.QT() and CF.dial:IsShown() and not CF.arrow:IsShown(), "a save that chose the compass keeps it")
    -- the arrow's right-click menu and Settings switch it, each in one place
    F.__scripts.OnClick(F, "RightButton")
    local Mn = fresh.env.QuestBankMenu
    local look
    for _, b in ipairs(Mn.items) do if b:IsShown() and b.label:GetText() == "Look: QuestBank's arrow" then look = b end end
    assert(look, "the menu names the look")
    look.__scripts.OnClick(look)
    assert(fresh.QB.Arrow.QT() and fresh.QB:Settings().arrowStyle == "compass", "the menu: the compass")
    fresh.QB.UI:Open(5); fresh.QB.UI:Refresh()
    local v5 = fresh.QB.UI.views[5]
    assert(v5.arrowStyle:GetText() == "Compass", "Settings says so")
    v5.arrowStyle.__scripts.OnClick(v5.arrowStyle)
    assert(not fresh.QB.Arrow.QT() and v5.arrowStyle:GetText() == "QuestBank's", "Settings: QuestBank's again")
  end }

  -- 4. Accept for me: Off for a new install; a save that had it on takes Quests worth taking; grey and low-value
  -- quests left; a quest on your route taken; one outside it taken or left as you choose
  B3CASES[#B3CASES + 1] = { "Accept for me is a choice", function()
    local c = mage("Acceptor", nil, nil, nil, nil, { settings = { autoAccept = true } })
    local QB, Au = c.QB, c.QB.Auto
    local low = catalog(c, function(q, n, xp) return xp > 0 and xp < line(c) and QB:Status(q).code == "todo" end)
    local worth = catalog(c, function(q, n, xp) return xp >= 2 * line(c) and QB:Status(q).code == "todo" end)
    local other = catalog(c, function(q, n, xp) return q.id ~= worth.id and xp >= 2 * line(c) and QB:Status(q).code == "todo" end)
    assert(low and worth and other, "a quest worth little and two worth taking")
    -- the quest window, as the game opens it
    local function offered(id, trivial)
      c.auto = {}
      c.window = { id = id, xp = 0, title = "Q" .. id }
      c.env.C_QuestLog.IsQuestTrivial = function() return trivial or false end
      c.ev(QB.eventFrame, "QUEST_DETAIL")
      tick(c, 1)
      return c.auto[#c.auto] == "AcceptQuest " .. id
    end
    assert(not offered(low.id), "a save that had it on, a quest worth little at your level: left to you (5.4.3 took it)")
    assert(QB:Settings().autoAccept == "worth", "that save: Quests worth taking")
    local fresh = mage("Newbie")
    assert(fresh.QB:Settings().autoAccept == "off", "a new install: off")
    assert(not offered(worth.id, true), "grey: left to you")
    assert(offered(worth.id), "worth taking: taken")
    QB:Settings().autoAcceptOther = "leave"
    assert(not offered(worth.id), "outside your route, with Leave the window to me: left")
    QB:SetAdded(worth.id, true)
    assert(offered(worth.id), "on your route: taken")
    QB:SetAdded(low.id, true)
    assert(offered(low.id), "on your route, though worth little: you chose it, taken")
    QB:Settings().autoAccept = "route"
    QB:Settings().autoAcceptOther = "accept"
    assert(not offered(other.id) and offered(worth.id), "Quests on my route: only those")
    QB:Settings().autoAccept = "off"
    assert(not offered(worth.id), "Off: none")
    -- Settings and the minimap's menu say it, a line each
    QB.UI:Open(5); QB:Settings().autoAccept = "worth"; QB.UI:Refresh()
    local v5 = QB.UI.views[5]
    assert(v5.autoAccept:GetText() == "Accept for me: Quests worth taking" and v5.autoOther:GetText() == "Outside my route: Accept them" and v5.autoOther:IsEnabled(),
      "Settings: " .. v5.autoAccept:GetText() .. " / " .. v5.autoOther:GetText())
    c.env.C_QuestLog.IsQuestTrivial = nil
  end }

  -- 5. the sparkle without the health bars: the soft-interact nameplate left as the game has it; a 5.4.3 save that had
  -- it changed gets it back; an option of its own, which Restore covers
  B3CASES[#B3CASES + 1] = { "the sparkle without health bars", function()
    local GAME = { SoftTargetInteract = "1", SoftTargetInteractArc = "0", SoftTargetInteractRange = "10", SoftTargetNameplateInteract = "0",
                   SoftTargetIconInteract = "1", SoftTargetIconGameObject = "0", SoftTargetLowPriorityIcons = "0", SoftTargetIconEnemy = "0" }
    local function pew(c) local f = c.QB.Glow.frame; f.__scripts.OnEvent(f, "PLAYER_ENTERING_WORLD") end
    local fresh = mage("Sparky")
    fresh.cvars = copy(GAME)
    pew(fresh)
    assert(fresh.cvars.SoftTargetInteract == "3" and fresh.cvars.SoftTargetIconGameObject == "1" and fresh.cvars.SoftTargetNameplateInteract == "0",
      "the light on: its settings set, the health bars' nameplate left off")
    -- a 5.4.3 save: the light had set the nameplate on, keeping the game's own Off to put back
    local saved = { settings = { glow = { on = true, style = "sparkle", npcs = true, other = true, combat = false,
      saved = { SoftTargetInteract = "1", SoftTargetInteractArc = "0", SoftTargetInteractRange = "10", SoftTargetNameplateInteract = "0",
                SoftTargetIconGameObject = "0", SoftTargetLowPriorityIcons = "0" }, yours = {} } } }
    local old = mage("Oldspark", nil, nil, nil, nil, saved)
    old.cvars = copy(GAME, nil)
    for k, v in pairs({ SoftTargetInteract = "3", SoftTargetInteractArc = "2", SoftTargetInteractRange = "15", SoftTargetNameplateInteract = "1",
                        SoftTargetIconGameObject = "1", SoftTargetLowPriorityIcons = "1" }) do old.cvars[k] = v end
    pew(old)
    assert(old.cvars.SoftTargetNameplateInteract == "0" and old.cvars.SoftTargetInteract == "3" and said(old):find("no longer puts a health bar", 1, true),
      "a 5.4.3 save: the nameplate back to the player's own Off, said once: " .. said(old))
    assert(old.QB:Settings().glow.saved.SoftTargetNameplateInteract == nil, "and nothing kept for it")
    -- the option: on, set; off, back; Restore puts back the player's own
    old.QB.Glow.SetPlates(true)
    assert(old.cvars.SoftTargetNameplateInteract == "1" and old.QB:Settings().glow.saved.SoftTargetNameplateInteract == "0", "Health bars on: set, the game's own kept")
    old.QB.Glow.SetPlates(false)
    assert(old.cvars.SoftTargetNameplateInteract == "0", "off: back")
    old.QB.Glow.SetPlates(true)
    old.QB.Glow.Restore("button")
    assert(old.cvars.SoftTargetNameplateInteract == "0" and old.cvars.SoftTargetInteract == "1", "Restore: the player's own values")
    old.QB:Settings().glow.plates = false
  end }

  -- 6. the light picks its NPCs: a herbalist with two professions gets none on a herbalism trainer; a trainer she can use
  -- lights; her class trainer while it has new spells
  B3CASES[#B3CASES + 1] = { "no light on a trainer you can't use", function()
    local c = mage("Herby")
    local QB, Glow, env = c.QB, c.QB.Glow, c.env
    local plate = env.CreateFrame("Frame")
    local sub = "Herbalism Trainer"
    env.C_TooltipInfo.GetUnit = function(unit) return { lines = { { leftText = c.soft and c.soft.name or "" }, { leftText = "<" .. sub .. ">" } } } end
    local n = 0
    local function at(name, subtitle)
      sub, n = subtitle, n + 1
      c.soft = { name = name, plate = plate, guid = string.format("Creature-0-4455-0-12-%d-0000A1B2C3", 9000 + n) }
      Glow.Update()
      return env.QuestBankGlow:IsShown() and Glow.kind
    end
    c.profs = { { "Herbalism", 150 }, { "Alchemy", 120 } }
    assert(not at("Test Herbalist", "Herbalism Trainer"), "two professions, Herbalism far from its cap: no light on its trainer")
    c.profs = { { "Herbalism", 290 }, { "Alchemy", 120 } }
    assert(at("Test Herbalist", "Herbalism Trainer") == "npc", "a rank to train: lit")
    c.profs = { { "Mining", 40 } }
    assert(at("Test Herbalist", "Herbalism Trainer") == "npc", "one profession: a second to learn, lit")
    assert(at("Test Cook", "Cooking Trainer") == "npc", "a secondary one not learned: lit")
    assert(not at("Test Weaponmaster", "Weapon Master"), "not a trainer you use: no light")
    -- the class's trainer: new spells at an even level (Classic's), until its window says when the next ones come
    c.level = 22
    assert(at("Test Mage", "Mage Trainer") == "npc", "the mage's trainer at 22: lit")
    env.GetNumTrainerServices = function() return 2 end
    env.GetTrainerServiceInfo = function(i) if i == 1 then return "Frostbolt", "used", 0, 20 end return "Fire Blast", "unavailable", 0, 24 end
    env.IsTradeskillTrainer = function() return false end
    local f = Glow.frame
    f.__scripts.OnEvent(f, "TRAINER_SHOW")
    assert(not at("Test Mage", "Mage Trainer"), "its window said the next spell is at 24: no light at 22")
    c.level = 24
    assert(at("Test Mage", "Mage Trainer") == "npc", "at 24: lit")
    -- every other NPC: only when asked for
    c.level = 21
    assert(not at("Test Smith", "Weaponsmith"), "a vendor: no light")
    QB:Settings().glow.everyNpc = true
    assert(at("Test Smith", "Weaponsmith") == "npc", "Every other NPC too: white")
    QB:Settings().glow.everyNpc = false
    c.soft, c.profs = nil, nil
  end }

  -- 7. the strokes a quarter thinner (a width you set kept), under every quest icon on the Map page (its canvas orders
  -- its pins as the world map does), a gap round each pin, softened over another icon
  B3CASES[#B3CASES + 1] = { "thinner strokes under the quest icons", function()
    local fresh = mage("Thin")
    local set = fresh.QB:Settings()
    assert(set.zmWidth == 6 and set.gpWidth == 6 and fresh.QB.MiniRoute.THICK == 6, "6 pixels, not 8")
    local old = mage("Thick", nil, nil, nil, nil, { settings = { zmWidth = 8, gpWidth = 8 } })
    assert(old.QB:Settings().zmWidth == 6 and old.QB:Settings().gpWidth == 6, "a save at the old default: the new one")
    local own = mage("Own", nil, nil, nil, nil, { settings = { zmWidth = 10, gpWidth = 12 } })
    assert(own.QB:Settings().zmWidth == 10 and own.QB:Settings().gpWidth == 12, "a width of your own: yours")
    -- the Map page: its strokes' level under the offers' and the quests'
    fresh.QB.UI:Open(8)
    for _ = 1, 3 do frame(fresh, 0.1) end
    local MP = fresh.QB.MapPage
    local mgr = MP.canvas:GetPinFrameLevelsManager()
    local blob, offer, quest = mgr:GetValidFrameLevel("PIN_FRAME_LEVEL_QUEST_BLOB"), mgr:GetValidFrameLevel("PIN_FRAME_LEVEL_QUEST_OFFER"), mgr:GetValidFrameLevel("PIN_FRAME_LEVEL_ACTIVE_QUEST")
    assert(blob < offer and offer < quest, string.format("the strokes' level (%d) under the offers' (%d) and the quests' (%d)", blob, offer, quest))
    -- drawn: three stops across Redridge's map with its ! icons about, the strokes' frame under every icon's; a sheet of
    -- it for the layout page ("Map page: strokes under the quest icons")
    local P = fresh.QB.Pins
    local saveList = P.list
    P.list = { { m = 1433, x = 20, y = 60, num = 1, name = "One", ids = {}, quests = {}, lines = {} },
               { m = 1433, x = 50, y = 45, num = 2, name = "Two", ids = {}, quests = {}, lines = {} },
               { m = 1433, x = 80, y = 60, num = 3, name = "Three", ids = {}, quests = {}, lines = {} } }
    MP.Go(1433, "user")
    MP.RefreshLayers()
    local strokes = MP.lines.active[1]
    local lowest
    for _, layer in ipairs({ fresh.QB.QuestMap.pageProvider, P.pageProvider }) do
      for _, f in ipairs(layer and layer.active or {}) do lowest = math.min(lowest or 1e9, f.__frameLevel or 0) end
    end
    assert(strokes and lowest and (strokes.__frameLevel or 0) < lowest, string.format("the strokes' frame (%s) under every icon (the lowest %s)", tostring(strokes and strokes.__frameLevel), tostring(lowest)))
    if layouts and dumpLayout then layouts[#layouts + 1] = dumpLayout(fresh.QB.UI.frame, "Map page: strokes under the quest icons (5.4.4)") end
    P.list = saveList
    -- a stroke stops a gap short of the pins it joins, and is softened where it crosses another icon
    local MR = fresh.QB.MiniRoute
    local ctx = { frame = fresh.env.CreateFrame("Frame"), lines = {}, used = 0, r = 1000, square = true }
    MR.Stroke(ctx, 0, 0, 100, 0, { 1, 1, 1 }, 4, 1, 16, 16)
    local l = ctx.lines[1]
    assert(math.abs(l.__start[3] - 11) < 1e-6 and math.abs(l.__stop[3] - 89) < 1e-6, "a gap of half the pin and 3 pixels at each end: " .. l.__start[3] .. ", " .. l.__stop[3])
    local marks = { { x = 50, y = 2, r = 8 }, { x = 0, y = 0, r = 8 } }
    assert(MR.Soften(0, 0, 100, 0, marks, 2, 2) == MR.SOFT and MR.Soften(0, 0, 100, 0, { marks[2] }, 1, 2) == 1,
      "softened over an icon on its way, not over the one it starts at")
  end }

  -- 8. the missing-buffs banner: a click on one keeps the others, through the cast and the meal
  B3CASES[#B3CASES + 1] = { "the missing-buffs banner kept while you use it", function()
    local c = mage("Hungry")
    local QB, env, Camp = c.QB, c.env, c.QB.Camp
    c.known = { [1459] = true, [168] = true }
    c.o.bagSlots = { { 2888, 1 } }
    c.buffs = {}
    local f = Camp.frame
    local function ev(e, ...) f.__scripts.OnEvent(f, e, ...) end
    c.resting = true; ev("PLAYER_ENTERING_WORLD")
    c.resting = false; ev("PLAYER_UPDATE_RESTING")
    local B = env.QuestBankBuffBanner
    local function icons()
      local out = {}
      for i = 1, 6 do
        local b = env["QuestBankBuff_" .. i]
        if b and b:IsShown() then out[#out + 1] = b.state.key end
      end
      return table.concat(out, ",")
    end
    assert(B:IsShown() and icons() == "food,self1,self2", "left town: food, Arcane Intellect, Frost Armor: " .. icons())
    -- Arcane Intellect clicked: its cast under way, 13 seconds on the banner's clock
    local ai = env.QuestBankBuff_2
    if ai.__scripts.OnClick then ai.__scripts.OnClick(ai, "LeftButton") end -- (the game's own click; QuestBank's hook on it)
    env.UnitCastingInfo = function(unit) return unit == "player" and "Arcane Intellect" or nil end
    tick(c, 13)
    assert(B:IsShown() and icons() == "food,self1,self2", "13 seconds on, the cast under way: every icon still there: " .. icons())
    env.UnitCastingInfo = nil
    c.buffs = { "Arcane Intellect" }
    ev("UNIT_AURA", "player")
    assert(B:IsShown() and icons() == "food,self1", "Arcane Intellect on: that one gone, the others stay: " .. icons())
    -- the food: the last piece eaten, the meal under way
    local food = env.QuestBankBuff_1
    if food.__scripts.OnClick then food.__scripts.OnClick(food, "LeftButton") end
    c.o.bagSlots = {}
    c.buffs = { "Arcane Intellect", "Food" }
    ev("UNIT_AURA", "player")
    tick(c, 20)
    assert(B:IsShown() and icons() == "food,self1", "eating it, the last one: the food stays until Well Fed: " .. icons())
    c.buffs = { "Arcane Intellect", "Well Fed" }
    ev("UNIT_AURA", "player")
    assert(B:IsShown() and icons() == "self1", "Well Fed: the food gone, Frost Armor left: " .. icons())
    -- untouched, it goes after its 12 seconds as before
    tick(c, 13)
    assert(not B:IsShown(), "untouched: gone")
    c.known, c.buffs = nil, nil
  end }

