  -- travel: a hand-in across a flight the character knows: the step before it is the arrow's ("Fly to Stormwind")
  G6CASES[#G6CASES + 1] = { "travel steps come from the arrow's way", function()
    local c = human("Flyer", {}, {}, nil, 12)
    local QB, G, D = c.QB, c.QB.Guide, c.QB.Data
    -- a quest handed in in Stormwind City while standing in Northshire: the route flies or walks; a travel step precedes it
    local function stormwindQuest()
      local ids = {}
      for id in pairs(D.Q) do ids[#ids + 1] = id end
      table.sort(ids)
      for _, id in ipairs(ids) do
        local q = QB.Quest.Get(id)
        local n = q and q.turnIdx and q.turnIdx > 0 and D.NPC[q.turnIdx]
        if n and n[2] == 1453 and q.lvl <= 14 and QB.Quest.ForMe(q) and not q.repeatable then return id end
      end
    end
    local sw = stormwindQuest()
    assert(sw, "a Stormwind hand-in for a level-12 human")
    c.log = { { sw, 1 } }
    QB:Settings().guide.on = true
    QB.Arrow:Set(true)
    settle(c)
    for _ = 1, 10 do frame(c, 0.1) end
    local travel, handin
    for i, s in ipairs(G.steps) do
      if s.kind == "travel" and not travel then travel = i end
      if s.kind == "handin" and s.qid == sw then handin = i end
    end
    assert(handin, "the hand-in is a step")
    if QB.Arrow.MiniStep() then assert(travel and travel < handin, "a travel step before the hand-in it leads to") end
  end }

  -- nothing worth taking in reach: a level-22 human in Northshire with every Elwynn quest done (the catalog's quests
  -- for the level band marked done, the rest too high): one step says to grind, where, until which level, and where
  -- the plan goes on
  G6CASES[#G6CASES + 1] = { "nothing worth taking in reach: the grind step", function()
    local c = human("Grinder", {}, {}, nil, 22)
    local QB, G, D = c.QB, c.QB.Guide, c.QB.Data
    for id, r in pairs(D.Q) do if r[2] <= 22 then c.done[id] = true end end -- everything you could take: done
    QB.API.RefreshDone()
    QB:Settings().guide.on = true
    settle(c)
    local s = G.steps[1]
    assert(s and s.kind == "grind", "a grind step: " .. tostring(s and G.Text(s)))
    assert(G.Text(s):match("^Kill around .+ until level (%d+)") and s["until"] and s["until"] > 22, "it names the level: " .. G.Text(s))
    assert(#G.steps == 1, "the only step")
    assert(G.Text(s):find(", then ", 1, true), "and where the plan goes on: " .. G.Text(s))
  end }

  -- the offline data the Train step reads (Task 7): the class trainers placed on the two continents and each class's
  -- learn levels
  G6CASES[#G6CASES + 1] = { "data: class trainers and spell levels are in Data.lua", function()
    local c = human("Datum")
    local D = c.QB.Data
    assert(type(D.TRAINER) == "table" and #D.TRAINER > 50, "D.TRAINER rows: " .. tostring(D.TRAINER and #D.TRAINER))
    local mage, placed = 0, 0
    for _, t in ipairs(D.TRAINER) do
      assert(type(t[1]) == "number" and type(t[2]) == "string" and type(t[3]) == "number" and t[3] >= 1 and t[3] <= 11, "a row: id, name, class id")
      if t[3] == 8 then mage = mage + 1 end
      if t[4] == 0 or t[4] == 1 then placed = placed + 1 end
    end
    assert(mage >= 10 and placed > #D.TRAINER * 0.8, "mage trainers and most placed on the two continents: " .. mage .. ", " .. placed)
    assert(type(D.SPELL_LV) == "table" and type(D.SPELL_LV.WARRIOR) == "table" and #D.SPELL_LV.WARRIOR >= 15 and D.SPELL_LV.WARRIOR[1] == 1, "spell levels per class token")
    for _, tok in ipairs({ "PALADIN", "HUNTER", "ROGUE", "PRIEST", "SHAMAN", "MAGE", "WARLOCK", "DRUID" }) do
      assert(D.SPELL_LV[tok] and #D.SPELL_LV[tok] >= 10, tok .. " has levels")
    end
  end }

  -- a level-10 human warrior in Northshire (10 is a warrior learn level) with a hand-in in Goldshire: "Train at
  -- Lyria Du Lac" (Goldshire's warrior trainer) comes before the Goldshire hand-in; the window read with nothing
  -- left to learn completes it; no trainer known near the route gives a reminder line, not a step; TRAINER_SHOW at
  -- an unknown trainer learns it (one the seed knows is not written down again)
  G6CASES[#G6CASES + 1] = { "the train step before the next town hand-in; a trainer learned in play", function()
    local c = human("Trainee", { { 62, 1 } }, {}, nil, 10) -- The Fargodeep Mine, handed in to Marshal Dughan in Goldshire
    local QB, G, D = c.QB, c.QB.Guide, c.QB.Data
    QB:Settings().guide.on = true
    assert(G.NeedsTraining(10), "level 10 is a warrior learn level and nothing trained yet")
    settle(c)
    local train, handin
    for i, s in ipairs(G.steps) do
      if s.kind == "train" then train = i end
      if s.kind == "handin" and s.qid == 62 and not handin then handin = i end
    end
    assert(train and handin and train < handin, "Train before the Goldshire hand-in: " .. tostring(train) .. " / " .. tostring(handin))
    assert(G.Text(G.steps[train]) == "Train at Lyria Du Lac", G.Text(G.steps[train]))
    assert(not G.reminder, "a step, so no reminder")
    -- the window: everything learned
    c.env.IsTradeskillTrainer = function() return false end
    c.env.GetNumTrainerServices = function() return 1 end
    c.env.GetTrainerServiceInfo = function() return "Heroic Strike", "used", 0, 10 end
    c.npcName = "Lyria Du Lac"
    c.npcGUID = "Creature-0-4455-0-12-913-0000A1B2C3"
    c.ev(QB.eventFrame, "TRAINER_SHOW")
    settle(c)
    for _, s in ipairs(G.steps) do assert(s.kind ~= "train", "trained: no train step") end
    assert(G.DB().trained == 10, "noted as trained at 10")
    assert(not (QB.Discover.DB().trainer and QB.Discover.DB().trainer["c913"]), "a trainer the seed knows is not written down")
    -- a class with no known trainer near the route: a reminder, no step
    local keep = D.TRAINER
    D.TRAINER = {}
    G.DB().trained = 0
    settle(c)
    for _, s in ipairs(G.steps) do assert(s.kind ~= "train", "no trainer known: no step") end
    assert(G.reminder and G.reminder > c.clock, "a reminder line instead")
    -- learned in play: the window at an unknown trainer notes it, and the step is back
    c.npcGUID = "Creature-0-4455-0-12-999999-0000A1B2C3"
    c.env.GetTrainerServiceInfo = function() return "Rend", "available", 0, 10 end
    c.ev(QB.eventFrame, "TRAINER_SHOW")
    local t = QB.Discover.DB().trainer and QB.Discover.DB().trainer["c999999"]
    assert(t and t.n == "Lyria Du Lac" and t.cl == 1 and t.m == 1429, "the trainer learned: name, class, place")
    assert(G.DB().trained == 0, "something still to learn: not trained")
    settle(c)
    local back = false
    for _, s in ipairs(G.steps) do if s.kind == "train" then back = true end end
    assert(back, "a learned trainer gives the step")
    assert(not G.reminder, "and the reminder goes")
    D.TRAINER = keep
    assert(#c.chat == 0 or not c.chat[#c.chat]:lower():find("train", 1, true), "nothing said in chat")
  end }

  -- "about 14 min to level 6": from the plan's XP a minute until ten minutes of play are measured, then from the
  -- XP an hour (Timer); nothing at the cap
  G6CASES[#G6CASES + 1] = { "time to level: from the plan, then from the XP an hour", function()
    local c = human("Clock", { { 7, 0 }, { 15, 0 }, { 18, 0 } }, { [783] = true }, nil, 5)
    local QB, G, Timer = c.QB, c.QB.Guide, c.QB.Timer
    QB:Settings().guide.on = true
    c.xp = 200
    c.env.UnitXPMax = function() return 900 end
    QB:ReadState()
    settle(c)
    local text, mins, measured = G.TimeToLevel()
    assert(text and text:find(" to level 6$") and mins and mins > 0 and not measured, "from the plan: " .. tostring(text))
    assert(text:match("^about %d+ min") or text:match("^under a minute") or text:match("^about %d+ h"), "the words: " .. text)
    -- ten minutes of play with 600 XP gained: 3,600 an hour; 100 to go at level 5 (900 - 800): about 2 min
    Timer.NoteXP()
    for _ = 1, 10 do c.clock = c.clock + 60; c.xp = c.xp + 60; Timer.NoteXP() end
    QB:ReadState()
    local t2, m2, meas2 = G.TimeToLevel()
    assert(meas2 and m2 and math.abs(m2 - (900 - c.xp) / 3600 * 60) < 0.5 and t2:find("^about %d+ min to level 6"), "measured: " .. tostring(t2) .. " " .. tostring(m2))
    -- the words at every span
    assert(G.SpanText(0.4) == "under a minute" and G.SpanText(14.4) == "about 14 min" and G.SpanText(130) == "about 2 h 10 min" and G.SpanText(120) == "about 2 h", "the spans")
    -- at the cap: nothing
    local was = QB.state.level
    QB.state.level = 60
    assert(G.TimeToLevel() == nil, "nothing at 60")
    QB.state.level = was
  end }

  -- a party of two: Rone holds Kobold Camp Cleanup, Brann holds it too and Investigate Echo Ridge; the fill prefers
  -- what the party holds, and each sees the other's step (Sync's 1G line)
  G6CASES[#G6CASES + 1] = { "a party of two: shared quests first, each member's step shown", function()
    local a = newClient({ name = "Rone", level = 3, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1, race = "Human",
      log = { { 7, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    local b = newClient({ name = "Brann", level = 3, cap = 60, faction = "Alliance", className = "Paladin", class = "PALADIN", classID = 2, race = "Human",
      log = { { 7, 0 }, { 15, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    login(a); login(b)
    a.objectives = { [7] = { { text = "Kobold Vermin slain: 1/8", type = "monster", finished = false, numFulfilled = 1, numRequired = 8 } } }
    b.objectives = { [7] = { { text = "Kobold Vermin slain: 4/8", type = "monster", finished = false, numFulfilled = 4, numRequired = 8 } },
                     [15] = { { text = "Investigate Echo Ridge: 0/1", type = "event", finished = false, numFulfilled = 0, numRequired = 1 } } }
    for _, c in ipairs({ a, b }) do c.QB:Settings().guide.on = true end
    settle(a); settle(b)
    a.QB.Sync:Broadcast(true); b.QB.Sync:Broadcast(true)
    for _ = 1, 3 do tick(a, 2); tick(b, 2); deliver() end
    settle(a); settle(b)
    for _ = 1, 3 do tick(a, 2); tick(b, 2); deliver() end
    -- the fill: Rone's plan holds Investigate Echo Ridge (Brann has it) ahead of other picks of the same worth
    assert(a.QB:Plan().auto[15] or a.QB:Plan().add[15], "Rone's plan takes the quest Brann holds")
    -- each other's step
    -- (a chat sender carries the surname: "Brann Steelhand", as the Party page names him)
    local function listed(ms) local t = {} for _, m in ipairs(ms) do t[#t + 1] = m.name .. ": " .. m.text end return table.concat(t, " | ") end
    local ms = a.QB.Guide.MemberSteps()
    assert(#ms == 1 and ms[1].name:find("^Brann") and ms[1].text == b.QB.Guide.Text(b.QB.Guide.steps[1]), "Rone sees Brann's step: " .. listed(ms))
    local mb = b.QB.Guide.MemberSteps()
    assert(#mb == 1 and mb[1].name:find("^Rone"), "Brann sees Rone's: " .. listed(mb))
    -- the message sent is the first step's text (one line, under 255 bytes, no escape codes)
    assert(a.QB.Sync.lastStep and a.QB.Sync.lastStep == a.QB.Guide.Text(a.QB.Guide.steps[1]), "the step text sent is the first step's")
    -- the same step again sends nothing; a change within STEP_GAP waits and then goes
    local sent = #a.outbox
    a.QB.Sync:Step(a.QB.Sync.lastStep)
    assert(#a.outbox == sent, "the same step is not sent again")
    assert(#a.chat == 0 or not a.chat[#a.chat]:find("step", 1, true), "nothing said in chat")
  end }

  -- the party's lines stand until something changed (Sync's member-step version, G.memberVer): a new step from a
  -- member moves the line, leaving the group clears them; nothing is made in between (the memory gate measures it)
  G6CASES[#G6CASES + 1] = { "the party's lines: made again only when a member's step or the group changed", function()
    local a = newClient({ name = "Rone", level = 3, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1, race = "Human",
      log = { { 7, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    local b = newClient({ name = "Brann", level = 3, cap = 60, faction = "Alliance", className = "Paladin", class = "PALADIN", classID = 2, race = "Human",
      log = { { 7, 0 }, { 15, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    login(a); login(b)
    for _, cc in ipairs({ a, b }) do cc.QB:Settings().guide.on = true; cc.QB:Settings().welcome = nil end
    settle(a); settle(b)
    a.QB.Sync:Broadcast(true); b.QB.Sync:Broadcast(true)
    for _ = 1, 3 do tick(a, 2); tick(b, 2); deliver() end
    settle(a); settle(b)
    for _ = 1, 3 do tick(a, 2); tick(b, 2); deliver() end
    a.QB.StepFrame.Apply(); a.QB.StepFrame.Refresh()
    local af, G = a.env.QuestBankStep, a.QB.Guide
    assert(#G.MemberSteps() == 1 and af.members[1] and af.members[1]:IsShown() and af.members[1]:GetText():find("Brann", 1, true), "Brann's step shown: " .. tostring(af.members[1] and af.members[1]:GetText()))
    local v0, list = G.memberVer, G.MemberSteps()
    for _ = 1, 20 do af.elapsed = 1; af.__scripts.OnUpdate(af, 0.016) end
    assert(G.memberVer == v0 and G.MemberSteps() == list, "nothing changed: the same list, the same version")
    -- Brann's step changes: the line follows
    b.QB.Sync.stepAt = nil
    b.QB.Sync:Step("Hand in Kobold Camp Cleanup")
    tick(b, 2); deliver()
    a.QB.StepFrame.Refresh()
    assert(G.memberVer > v0 and af.members[1]:GetText():find("Hand in Kobold Camp Cleanup", 1, true), "a new step from Brann: the line follows: " .. tostring(af.members[1]:GetText()))
    -- out of the group: the lines go
    a.o.group = false
    a.QB.StepFrame.Refresh()
    assert(#G.MemberSteps() == 0 and not af.members[1]:IsShown(), "alone: no member lines")
  end }

  -- the step frame (StepFrame.lua): the step now in ink, the two next greyed, "about N min to level 6"; a click opens
  -- the Quest Log on the quest; a right-click is the menu; scale and lock kept; hidden by its setting; nothing clipped
  -- at any scale (the sheets go to the layout page)
  G6CASES[#G6CASES + 1] = { "the step frame: one line now, two greyed, the time line, click and right-click", function()
    local c = human("Framer", { { 7, 0 } }, { [783] = true }, nil, 5)
    local QB, G, SF, UI = c.QB, c.QB.Guide, c.QB.StepFrame, c.QB.UI
    c.objectives = { [7] = { { text = "Kobold Vermin slain: 3/8", type = "monster", finished = false, numFulfilled = 3, numRequired = 8 } } }
    QB:Settings().guide.on = true; QB:Settings().welcome = nil
    QB:SetAdded(15, true); QB:SetAdded(18, true)
    settle(c)
    SF.Apply(); SF.Refresh()
    local f = c.env.QuestBankStep
    assert(f and f:IsShown(), "the frame is up")
    -- (a row too long for the frame shows the step's short form, else is cut with "...": Arrow.lua's A.Fit)
    local function rowIs(t, s) local got, full = t:GetText(), G.Text(s); return got == full or got == G.Short(s) or (got:sub(-3) == "..." and full:sub(1, #got - 3) == got:sub(1, -4)) end
    assert(rowIs(f.now, G.steps[1]) and rowIs(f.next1, G.steps[2]) and rowIs(f.next2, G.steps[3]),
      "the three lines: " .. tostring(f.now:GetText()) .. " | " .. tostring(f.next1:GetText()) .. " | " .. tostring(f.next2:GetText()))
    local r, g = f.next1:GetTextColor()
    assert(r < 0.8 and g < 0.8, "the next steps greyed")
    assert(f.time:GetText():find(" to level 6$"), "the time line: " .. tostring(f.time:GetText()))
    -- a click: the window on the Quest Log, the step's quest framed
    f.rows[1].__scripts.OnClick(f.rows[1], "LeftButton")
    assert(UI.frame and UI.frame:IsShown() and UI.tab == 1, "a click opens the Quest Log")
    assert(UI.scrollToQuest == nil, "the quest was shown once")
    UI.frame:Hide()
    -- the right-click menu: Not now, Drop, Lock, scales, Hide, Settings
    f.rows[1].__scripts.OnClick(f.rows[1], "RightButton")
    local labels = {}
    for _, it in ipairs(UI.lastMenu or {}) do labels[#labels + 1] = it[1] end
    local joined = table.concat(labels, " | ")
    assert(joined:find("Not now", 1, true) and joined:find("Drop ", 1, true) and joined:find("Lock", 1, true) and joined:find("Scale: 80%", 1, true)
      and joined:find("Hide", 1, true) and joined:find("Settings", 1, true), "the menu: " .. joined)
    -- Not now from the menu puts the first step's quest off
    for _, it in ipairs(UI.lastMenu) do if it[1] == "Not now" then it[2]() end end
    settle(c); SF.Refresh()
    assert(G.PutOff(7), "Not now put the quest off")
    -- scale and lock are kept
    SF.SetScale(1.2)
    assert(QB:Settings().guide.scale == 1.2 and math.abs(f:GetScale() - 1.2) < 0.001, "scale kept")
    QB:Settings().guide.locked = true; SF.Apply()
    assert(f.__dragOff, "locked: no drag")
    -- off: hidden
    QB:Settings().guide.frame = false; SF.Apply()
    assert(not f:IsShown(), "hidden by the setting")
    QB:Settings().guide.frame = true; QB:Settings().guide.locked = false; SF.SetScale(1); SF.Apply()
    assert(f:IsShown() and not f.__dragOff, "back, and unlocked")
    -- the layout: nothing clipped at any scale; the sheets for the layout page
    for _, sc in ipairs({ 0.8, 1, 1.2 }) do
      SF.SetScale(sc); SF.Refresh()
      for _, pr in ipairs(checkLayout(f, "step frame at " .. sc)) do STAGE_PROBLEMS[#STAGE_PROBLEMS + 1] = pr end
      STAGE_LAYOUTS[#STAGE_LAYOUTS + 1] = dumpLayout(f, "Step frame at " .. sc)
    end
    SF.SetScale(1)
    assert(#c.chat == 0 or not c.chat[#c.chat]:find("step", 1, true), "nothing said in chat")
  end }

  -- a pick-up too long for the row (6.0.0's review: "Accept Dwarven Outfitters from Sten Stou..." cut at the giver's
  -- name): the row says "Accept Dwarven Outfitters" and its tooltip the whole line with the giver; a row that says
  -- it all has no tooltip
  G6CASES[#G6CASES + 1] = { "the step frame: a long pick-up shows Accept X, the giver in the row's tooltip", function()
    local c = newClient({ name = "Coldridge", level = 1, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1,
      race = "Dwarf", log = {}, done = {}, world = { 0, -6215, 330 }, map = 1426, bagSlots = {}, bind = "Kharanos" })
    login(c)
    local QB, G, SF = c.QB, c.QB.Guide, c.QB.StepFrame
    QB:Settings().welcome = nil
    settle(c); SF.Apply(); SF.Refresh()
    local f = c.env.QuestBankStep
    local cut = 0
    for i = 1, 3 do
      local s = G.steps[i]
      local t = f.rows[i].text
      if s then
        local full = G.Text(s)
        lines = {}
        f.rows[i].__scripts.OnEnter(f.rows[i])
        if t:GetText() == full then
          assert(#lines == 0, "a row that says it all has no tooltip: " .. table.concat(lines, " | "))
        else
          assert(s.kind == "accept" and t:GetText() == G.Short(s) and not t:GetText():find("...", 1, true), "a cut pick-up row says Accept X: " .. t:GetText())
          assert(#lines == 1 and lines[1] == full, "its tooltip is the whole line: " .. table.concat(lines, " | "))
          cut = cut + 1
        end
        f.rows[i].__scripts.OnLeave(f.rows[i])
      end
    end
    assert(cut >= 1, "a pick-up row too long for the frame (Sten Stoutarm's)")
    assert(G.Short(G.steps[1]) == "Accept Dwarven Outfitters" and G.Short({ kind = "handin" }) == nil, "the short form is the pick-up's alone")
  end }

  -- the quest-item button: the game's secure button for the first step's quest item, set, shown and hidden out of a
  -- fight only; a reward window with a choice: Hand in for me stops, QuestBank's pick is marked with its own glow
  -- over the game's button, nothing is chosen, and the step says so
  G6CASES[#G6CASES + 1] = { "the quest-item button out of a fight; a reward choice stops, marks, does not choose", function()
    local c = human("Itemer", { { 7, 0 } }, { [783] = true }, nil, 5)
    local QB, G, SF = c.QB, c.QB.Guide, c.QB.StepFrame
    c.objectives = { [7] = { { text = "Kobold Vermin slain: 3/8", type = "monster", finished = false, numFulfilled = 3, numRequired = 8 } } }
    c.questItems[7] = { 6948, 134414 }
    QB:Settings().guide.on = true; QB:Settings().welcome = nil
    settle(c); SF.Apply(); SF.Refresh()
    local f = c.env.QuestBankStep
    assert(f.item and f.item:IsShown() and f.item:GetAttribute("type") == "item" and f.item:GetAttribute("item") == "item:6948", "the item button set: " .. tostring(f.item and f.item:GetAttribute("item")))
    -- in a fight the button stays as it is; the change waits
    c.combat = true
    c.questItems[7] = nil
    settle(c); SF.Refresh()
    assert(f.item:IsShown() and f.item:GetAttribute("item") == "item:6948", "in a fight: nothing changes")
    c.combat = false
    c.ev(QB.eventFrame, "PLAYER_REGEN_ENABLED")
    SF.Refresh()
    assert(not f.item:IsShown(), "out of it: the button goes")
    -- a reward window with two choices: Hand in for me stops, the Gear finder's pick is marked, nothing chosen
    QB:Settings().autoTurnIn = true
    c.window = { id = 7, xp = 85, title = "Kobold Camp Cleanup", rc = { 2362, 2361 } } -- a shield and a hammer
    c.auto = {}
    c.ev(QB.eventFrame, "QUEST_COMPLETE")
    tick(c, 1)
    for _, a in ipairs(c.auto) do assert(not a:find("^GetQuestReward"), "nothing chosen: " .. a) end
    assert(G.reward and G.reward.qid == 7 and (G.reward.index == 1 or G.reward.index == 2), "the Guide holds the choice: " .. tostring(G.reward and G.reward.index))
    SF.Refresh()
    assert(f.now:GetText():find("^Choose a reward: "), "the step says so: " .. f.now:GetText())
    assert(SF.mark and SF.mark:IsShown(), "the pick is marked")
    c.ev(QB.eventFrame, "QUEST_FINISHED")
    assert(not SF.mark:IsShown() and G.reward == nil, "the window shut: the mark goes")
    SF.Refresh()
    assert(not f.now:GetText():find("^Choose a reward: "), "the step is back: " .. f.now:GetText())
    -- with Hand in for me off, the Guide still holds the pick (the window is yours; the mark helps)
    QB:Settings().autoTurnIn = false
    c.ev(QB.eventFrame, "QUEST_COMPLETE")
    tick(c, 1)
    assert(G.reward and G.reward.qid == 7, "the pick is held with Hand in for me off")
    for _, a in ipairs(c.auto) do assert(not a:find("^GetQuestReward"), "and nothing chosen: " .. a) end
    c.ev(QB.eventFrame, "QUEST_FINISHED")
    c.window = nil
    assert(#c.chat == 0 or not c.chat[#c.chat]:find("reward", 1, true), "nothing said in chat")
  end }

  -- the step frame hidden in a fight (6.0.0's review: the secure item button stayed on screen for good, as the hidden
  -- frame's OnUpdate never runs): the fight's end (PLAYER_REGEN_ENABLED, Core.lua's frame) hides the button; shown
  -- again in a fight, the button waits and comes with the fight's end
  G6CASES[#G6CASES + 1] = { "the item button goes when the frame was hidden in a fight, once the fight is over", function()
    local h = human("Hider", { { 7, 0 } }, { [783] = true }, nil, 5)
    local QB, SF = h.QB, h.QB.StepFrame
    h.objectives = { [7] = { { text = "Kobold Vermin slain: 3/8", type = "monster", finished = false, numFulfilled = 3, numRequired = 8 } } }
    h.questItems[7] = { 6948, 134414 }
    QB:Settings().guide.on = true; QB:Settings().welcome = nil
    settle(h); SF.Apply(); SF.Refresh()
    local f = h.env.QuestBankStep
    assert(f.item and f.item:IsShown(), "the item button up")
    h.combat = true
    QB:Settings().guide.frame = false; SF.Apply()
    assert(not f:IsShown() and f.item:IsShown() and SF.pendingItem, "hidden in a fight: the button stands, the change waits")
    h.combat = false
    h.ev(QB.eventFrame, "PLAYER_REGEN_ENABLED")
    for _ = 1, 30 do frame(h, 0.1) end
    assert(not f.item:IsShown() and not SF.pendingItem, "the fight over: the button goes with the hidden frame")
    h.combat = true
    QB:Settings().guide.frame = true; SF.Apply()
    assert(f:IsShown() and not f.item:IsShown() and SF.pendingItem, "shown in a fight: the button waits")
    h.combat = false
    h.ev(QB.eventFrame, "PLAYER_REGEN_ENABLED")
    assert(f.item:IsShown() and f.item:GetAttribute("item") == "item:6948", "the fight over: the button is back for the shown frame")
  end }

  -- a fresh install: the step frame opens on the welcome card (the auto choice, the outside-route choice, hand in for
  -- me), Done keeps the choices, says the one chat line and gives way to the steps; nothing else is said
  G6CASES[#G6CASES + 1] = { "a fresh install: the welcome card asks the auto choice; one line in chat, nothing else", function()
    local c = human("Newbie", { { 7, 0 } }, { [783] = true }, nil, 2)
    local QB, SF, A = c.QB, c.QB.StepFrame, c.QB.Arrow
    settle(c); SF.Apply()
    local f = c.env.QuestBankStep
    assert(f and f:IsShown() and f.card and f.card:IsShown(), "the frame with the welcome card")
    assert(f.card.accept:GetText() == "Accept for me: Off" and f.card.turnIn:GetChecked() == false and not f.card.other:IsEnabled(), "the choices start at Off: " .. tostring(f.card.accept:GetText()))
    assert(A.frame and A.frame:IsShown(), "QuestBank's arrow is on")
    assert(QB:Settings().arrowStyle == "questbank", "QuestBank's own arrow, not the compass")
    local before = #c.chat
    f.card.accept.__scripts.OnClick(f.card.accept, "LeftButton")
    f.card.accept.__scripts.OnClick(f.card.accept, "LeftButton")
    assert(f.card.accept:GetText() == "Accept for me: Quests worth taking" and f.card.other:IsEnabled(), "two clicks: Quests worth taking, the outside choice opens")
    f.card.other.__scripts.OnClick(f.card.other, "LeftButton")
    assert(f.card.other:GetText() == "Outside my route: Leave the window to me", f.card.other:GetText())
    f.card.turnIn:SetChecked(true); f.card.turnIn.__scripts.OnClick(f.card.turnIn)
    assert(#c.chat == before, "nothing said while choosing")
    checkLayout(f, "welcome card")
    f.card.done.__scripts.OnClick(f.card.done, "LeftButton")
    local s = QB:Settings()
    assert(s.autoAccept == "worth" and s.autoAcceptOther == "leave" and s.autoTurnIn == true and s.welcome == nil, "the choices kept")
    assert(#c.chat == before + 1 and c.chat[#c.chat]:find("QuestBank is guiding you. /qb opens the full window; right%-click the step frame for its options%."), "the one line: " .. tostring(c.chat[#c.chat]))
    assert(not f.card:IsShown() and f.now:GetText() ~= "", "the card gives way to the steps")
    settle(c); SF.Refresh()
    assert(#c.chat == before + 1, "and nothing more")
    checkLayout(f, "steps after the welcome")
  end }

  -- a 5.x save: "Let QuestBank guide you?" once; Not now changes nothing and hides the frame (Settings brings the
  -- Guide back later); Yes turns the Guide and the arrow on, the welcome card follows from the player's own choices
  G6CASES[#G6CASES + 1] = { "a 5.x save: one question, both answers", function()
    local saved = function() return { settings = { v544 = true, autoAccept = "route", autoTurnIn = true, arrow = false, arrowStyle = "compass", tab = 6 } } end
    -- Not now
    local c = human("Oldhand", { { 7, 0 } }, { [783] = true }, saved(), 8)
    local QB, SF = c.QB, c.QB.StepFrame
    settle(c); SF.Apply()
    local f = c.env.QuestBankStep
    assert(f:IsShown() and f.card:IsShown() and f.card.title:GetText() == "Let QuestBank guide you?", "the question: " .. tostring(f.card.title:GetText()))
    checkLayout(f, "the 5.x question")
    local before = #c.chat
    f.card.no.__scripts.OnClick(f.card.no, "LeftButton")
    local s = QB:Settings()
    assert(s.guide.on == false and s.welcome == nil and s.arrow == false and s.arrowStyle == "compass" and s.autoAccept == "route" and s.autoTurnIn == true, "Not now: nothing changed")
    assert(not f:IsShown() and #c.chat == before, "the frame hides, nothing said")
    s.guide.on = true; SF.Apply()
    assert(f:IsShown() and not f.card:IsShown(), "Settings turns the Guide on later: the frame is back with steps")
    -- Yes
    local d = human("Convert", { { 7, 0 } }, { [783] = true }, saved(), 8)
    local QD, SD = d.QB, d.QB.StepFrame
    settle(d); SD.Apply()
    local g = d.env.QuestBankStep
    local n0 = #d.chat
    g.card.yes.__scripts.OnClick(g.card.yes, "LeftButton")
    local t = QD:Settings()
    assert(t.guide.on == true and t.arrow == true and t.autoAccept == "route" and t.autoTurnIn == true and t.arrowStyle == "compass", "Yes: the Guide and the arrow on, the rest as it was")
    assert(g.card:IsShown() and g.card.accept and g.card.accept:GetText() == "Accept for me: Quests on my route", "then the welcome card, starting from their own choice")
    assert(d.QB.Arrow.frame and d.QB.Arrow.frame:IsShown(), "the arrow is up")
    g.card.done.__scripts.OnClick(g.card.done, "LeftButton")
    assert(#d.chat == n0 + 1 and d.chat[#d.chat]:find("guiding you", 1, true), "the one line after Done")
  end }

  -- /qb guide on a 5.x save never asked (6.0.0's review: the Guide came on under the question, the arrow off): the
  -- command answers it: no question, the frame with steps, the arrow and 6.0's switches on, the one line; off again
  -- asks nothing
  G6CASES[#G6CASES + 1] = { "/qb guide answers a 5.x save's question", function()
    local d = human("Slash", { { 7, 0 } }, { [783] = true }, { settings = { v544 = true, arrow = false, tab = 6 } }, 8)
    local QB = d.QB
    settle(d); QB.StepFrame.Apply()
    local f = d.env.QuestBankStep
    assert(f.card and f.card:IsShown() and QB:Settings().welcome == "ask", "the question is up")
    d.env.SlashCmdList.QUESTBANK("guide")
    local s = QB:Settings()
    assert(s.guide.on == true and s.welcome == nil and s.arrow == true and s.guide.frame == true, "/qb guide answers the question: on, no welcome, the arrow on")
    assert(not f.card:IsShown() and f:IsShown() and f.rows[1]:IsShown() and f.now:GetText() ~= "", "the frame shows steps, not the question: " .. tostring(f.now:GetText()))
    assert(QB.Arrow.frame and QB.Arrow.frame:IsShown(), "the arrow is up")
    assert(s.minimapGivers == true and s.tipProgress == true, "6.0's switches on as Yes gives them")
    assert(d.chat[#d.chat] and d.chat[#d.chat]:find("guiding you", 1, true), "the one line: " .. tostring(d.chat[#d.chat]))
    d.env.SlashCmdList.QUESTBANK("guide")
    assert(s.guide.on == false and s.welcome == nil, "off again, no question")
  end }

  -- a 5.x save's two new switches (6.0.0's review: the DEFAULTS turned the minimap's ! and the tooltip progress on
  -- behind a "Not now"): off from the migration, off after Not now, on with Yes; a fresh install has both on
  G6CASES[#G6CASES + 1] = { "a 5.x save: the ! and the tooltip progress wait for Yes", function()
    local saved = function() return { settings = { v544 = true, autoAccept = "route", arrow = false, tab = 6 } } end
    local c = human("Holdout", { { 7, 1 } }, { [783] = true }, saved(), 8)
    local QB, SF = c.QB, c.QB.StepFrame
    local s = QB:Settings()
    assert(s.minimapGivers == false and s.tipProgress == false and s.welcome == "ask", "a 5.x save: the ! and the tooltip progress off until it says yes")
    settle(c); SF.Apply()
    local f = c.env.QuestBankStep
    f.card.no.__scripts.OnClick(f.card.no, "LeftButton")
    settle(c)
    assert(s.minimapGivers == false and s.tipProgress == false, "Not now: still off")
    for _, it in ipairs(QB.Mini.List()) do assert(it.kind ~= "give", "no ! on the minimap for a 5.x player who said Not now") end
    local d = human("Joiner", { { 7, 1 } }, { [783] = true }, saved(), 8)
    settle(d); d.QB.StepFrame.Apply()
    local g = d.env.QuestBankStep
    g.card.yes.__scripts.OnClick(g.card.yes, "LeftButton")
    local t = d.QB:Settings()
    assert(t.minimapGivers == true and t.tipProgress == true and t.guide.on == true, "Yes: both on with the Guide")
    settle(d)
    local gives = 0
    for _, it in ipairs(d.QB.Mini.List()) do if it.kind == "give" then gives = gives + 1 end end
    assert(gives > 0, "and the ! pins come")
    local fresh = human("Starter")
    assert(fresh.QB:Settings().minimapGivers == true and fresh.QB:Settings().tipProgress == true, "a fresh install: both on")
  end }

  -- the minimap: a ! for every quest you can take now on your map (the world map's own filter: for you, not grey,
  -- prerequisites done, not held, not done), givers within 30 yards one pin with a count, forty at most, the nearest
  -- first; a ? where a finished quest is handed in as before; the pin draws the game's !; the switch takes them off
  G6CASES[#G6CASES + 1] = { "the minimap: a ! for every quest you can take now, merged, forty at most, a ? where to hand in", function()
    local c = human("Pinner", { { 7, 1 } }, { [783] = true }, nil, 3)
    local QB, Mini, QM, D = c.QB, c.QB.Mini, c.QB.QuestMap, c.QB.Data
    QB:Settings().guide.on = true; QB:Settings().welcome = nil
    c.objectives = { [7] = { { text = "Kobold Vermin slain: 8/8", type = "monster", finished = true, numFulfilled = 8, numRequired = 8 } } }
    settle(c)
    local gives = QM.GiversNear(1429, 3)
    assert(#gives > 0, "givers with quests for a level-3 human on Elwynn's map")
    for _, g in ipairs(gives) do
      assert(g.npc and D.NPC[g.npc] and g.m == 1429 and g.x and g.y and #g.ids > 0, "a giver: its NPC, its place, its quests")
      for _, id in ipairs(g.ids) do
        local q = QB.Quest.Get(id)
        local st = QB:Status(q)
        assert(st.code == "todo" or st.code == "item", "every quest listed is one you can take: " .. q.name .. " " .. st.code)
        assert(not QM.Grey(q, 3), "never a grey one: " .. q.name)
        assert(not QB.state.log[id] and not QB.API.IsDone(id), "not held, not done: " .. q.name)
      end
    end
    local list = Mini.List()
    local give, turn, n = 0, 0, 0
    for _, d in ipairs(list) do
      if d.kind == "give" then give = give + 1; n = n + (d.n or 1) end
      if d.kind == "turn" then turn = turn + 1 end
    end
    assert(give > 0 and give <= 40 and n >= give, "! pins, merged, forty at most: " .. give .. " for " .. n .. " givers")
    assert(turn >= 1, "a ? for Kobold Camp Cleanup's hand-in")
    -- two givers within 30 yards are one pin with a count
    local merged = false
    for _, d in ipairs(list) do if d.kind == "give" and (d.n or 1) > 1 then merged = true; assert(#d.ids >= d.n, "the merged pin carries every quest") end end
    assert(merged, "Northshire's givers at the abbey merge")
    -- the nearest first, and never one where a hand-in's pin stands (the ? at McBride takes the !)
    local last = -1
    for _, d in ipairs(list) do
      if d.kind == "give" then
        assert(d.far >= last, "the nearest first")
        last = d.far
        for _, t in ipairs(list) do
          if t.kind == "turn" then assert(not (t.m == d.m and t.x == d.x and t.y == d.y), "no ! under a ?: " .. tostring(d.name)) end
        end
      end
    end
    -- the switch
    QB:Settings().minimapGivers = false
    for _, d in ipairs(Mini.List()) do assert(d.kind ~= "give", "off: no !") end
    assert(Mini.ListCached() ~= nil, "the cached list follows the switch")
    for _, d in ipairs(Mini.ListCached()) do assert(d.kind ~= "give", "off: the cached list has no ! either") end
    QB:Settings().minimapGivers = true
    -- placed: a ! pin on the minimap, drawn with the game's own atlas, the count on a merged one
    Mini.Invalidate(); Mini.Place()
    local drawn, counted = nil, false
    for _, child in ipairs(c.frames) do
      if child.__parent == c.env.QuestBankMinimap and child.d and child:IsShown() and child.d.kind == "give" then
        drawn = child
        if (child.d.n or 1) > 1 and child.num:GetText() == tostring(child.d.n) then counted = true end
      end
    end
    assert(drawn and drawn.icon.__tex == "atlas:QuestNormal", "a ! drawn on the minimap with the game's atlas: " .. tostring(drawn and drawn.icon.__tex))
    assert(counted, "a merged pin shows its count")
    -- its tooltip lists the quests
    lines = {}
    drawn.__scripts.OnEnter(drawn)
    local joined = table.concat(lines, " | ")
    local q1 = QB.Quest.Get(drawn.d.ids[1])
    assert(joined:find(q1.name, 1, true), "the tooltip lists its quests: " .. joined)
    assert(#c.chat == 0 or not c.chat[#c.chat]:find("quest", 1, true), "nothing said in chat")
  end }

  -- tooltips (Tips.lua): a mob or object that counts for a quest in your log gets "Kobold Vermin: 3/8 (Kobold Camp
  -- Cleanup)" and the party's counts; nothing when the game hides the unit (a secret guid or name), nothing for a
  -- mob of no quest, nothing with the switch off
  G6CASES[#G6CASES + 1] = { "tooltips: Kobold Vermin: 3/8 (Kobold Camp Cleanup), and the party's count", function()
    local a = newClient({ name = "Tipper", level = 3, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1, race = "Human",
      log = { { 7, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    local b = newClient({ name = "Brann", level = 3, cap = 60, faction = "Alliance", className = "Paladin", class = "PALADIN", classID = 2, race = "Human",
      log = { { 7, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    login(a); login(b)
    a.objectives = { [7] = { { text = "Kobold Vermin slain: 3/8", type = "monster", finished = false, numFulfilled = 3, numRequired = 8 } } }
    b.objectives = { [7] = { { text = "Kobold Vermin slain: 6/8", type = "monster", finished = false, numFulfilled = 6, numRequired = 8 } } }
    settle(a); settle(b)
    a.QB.Sync:Broadcast(true); b.QB.Sync:Broadcast(true)
    for _ = 1, 3 do tick(a, 2); tick(b, 2); deliver() end
    local hooks = a.tipHooksByKind[2]
    assert(hooks and #hooks == 1 and a.tipHooksByKind[4] and #a.tipHooksByKind[4] == 1, "one hook each for units and objects")
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-6-0000A1B2C3", lines = { { leftText = "Kobold Vermin" }, { leftText = "Level 1" } } })
    local joined = table.concat(lines, " | ")
    assert(joined:find("Kobold Vermin: 3/8 (Kobold Camp Cleanup)", 1, true), "the line: " .. joined)
    assert(joined:match("Brann[%a ]* 6/8"), "the party's count (a chat sender carries the surname, as the Party page names him): " .. joined)
    -- the same list reused: a second hover makes the same lines
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-6-0000A1B2C3", lines = { { leftText = "Kobold Vermin" } } })
    assert(table.concat(lines, " | ") == joined, "the same again")
    -- a secret guid or name: nothing
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = SECRET.str(), lines = { { leftText = SECRET.str() } } })
    assert(#lines == 0, "secret: nothing shown")
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-6-0000A1B2C3", lines = { { leftText = SECRET.str() } } })
    assert(#lines == 0, "a secret name: nothing shown")
    -- a mob of no quest: nothing
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-99-0000A1B2C3", lines = { { leftText = "Stormwind Guard" } } })
    assert(#lines == 0, "no quest: nothing")
    -- the switch
    a.QB:Settings().tipProgress = false
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-6-0000A1B2C3", lines = { { leftText = "Kobold Vermin" } } })
    assert(#lines == 0, "off: nothing")
    a.QB:Settings().tipProgress = true
    -- alone: no party line
    a.env.IsInGroup = function() return false end
    lines = {}
    hooks[1](a.env.GameTooltip, { type = 2, guid = "Creature-0-4455-0-12-6-0000A1B2C3", lines = { { leftText = "Kobold Vermin" } } })
    joined = table.concat(lines, " | ")
    assert(joined:find("Kobold Vermin: 3/8", 1, true) and not joined:find("Brann", 1, true), "alone: your count only: " .. joined)
    assert(#a.chat == 0 or not a.chat[#a.chat]:find("Kobold", 1, true), "nothing said in chat")
  end }

  -- Settings regrouped (UI.lua): Guide first, Map and minimap, the modules, Data you share, Banking last; the Guide's
  -- rows drive their settings and the step frame; nothing clipped
  G6CASES[#G6CASES + 1] = { "Settings open on Guide; Banking last; every row drives its setting", function()
    local c = human("Setter", { { 7, 0 } }, { [783] = true }, nil, 5)
    local QB, UI, SF = c.QB, c.QB.UI, c.QB.StepFrame
    QB:Settings().welcome = nil
    settle(c)
    UI:Open(5); UI:Refresh()
    local v = UI.views[5]
    local order = {}
    for _, h in ipairs(v.headings) do order[#order + 1] = h:GetText() end
    assert(order[1] == "Guide" and order[2] == "Map and minimap" and order[#order] == "Banking", "the order: " .. table.concat(order, " > "))
    local seen = {}
    for _, h in ipairs(order) do seen[h] = true end
    assert(seen["Data you share"] and seen["Interact light"] and seen["Camp bar"] and seen["Timers"], "the module and data sections are there")
    local iData, iBank = 0, 0
    for i, h in ipairs(order) do if h == "Data you share" then iData = i end if h == "Banking" then iBank = i end end
    assert(iData < iBank and iData > 2, "Data you share before Banking, after the modules")
    -- the Guide's rows
    assert(v.guideOn:GetChecked() == true and v.guideFrame:GetChecked() == true and v.arrow:GetChecked() == true, "the rows show the settings")
    v.guideOn:SetChecked(false); v.guideOn.__scripts.OnClick(v.guideOn)
    assert(QB:Settings().guide.on == false and not c.env.QuestBankStep:IsShown(), "Guide off: the frame hides")
    v.guideOn:SetChecked(true); v.guideOn.__scripts.OnClick(v.guideOn)
    assert(QB:Settings().guide.on == true and c.env.QuestBankStep:IsShown(), "on again")
    v.guideFrame:SetChecked(false); v.guideFrame.__scripts.OnClick(v.guideFrame)
    assert(QB:Settings().guide.frame == false and not c.env.QuestBankStep:IsShown(), "the frame's own switch")
    v.guideFrame:SetChecked(true); v.guideFrame.__scripts.OnClick(v.guideFrame)
    assert(c.env.QuestBankStep:IsShown(), "and back")
    v.guideLocked:SetChecked(true); v.guideLocked.__scripts.OnClick(v.guideLocked)
    assert(QB:Settings().guide.locked == true and c.env.QuestBankStep.__dragOff, "locked in place")
    v.guideLocked:SetChecked(false); v.guideLocked.__scripts.OnClick(v.guideLocked)
    v.guideScale.__scripts.OnClick(v.guideScale, "LeftButton")
    assert(QB:Settings().guide.scale ~= 1 and v.guideScale:GetText():find("%%") and math.abs(c.env.QuestBankStep:GetScale() - QB:Settings().guide.scale) < 0.001, "the scale cycles: " .. v.guideScale:GetText())
    for _ = 1, 2 do v.guideScale.__scripts.OnClick(v.guideScale, "LeftButton") end
    assert(QB:Settings().guide.scale == 1, "and round to 100%")
    assert(v.autoAccept:GetText():find("^Accept for me: ") and v.autoOther and v.autoTurnIn and v.autoKey and v.minimapGivers and v.tipProgress, "auto, the ! and the tooltips sit under Guide")
    v.minimapGivers:SetChecked(false); v.minimapGivers.__scripts.OnClick(v.minimapGivers)
    assert(QB:Settings().minimapGivers == false, "the ! switch")
    v.minimapGivers:SetChecked(true); v.minimapGivers.__scripts.OnClick(v.minimapGivers)
    v.tipProgress:SetChecked(false); v.tipProgress.__scripts.OnClick(v.tipProgress)
    assert(QB:Settings().tipProgress == false, "the tooltip switch")
    v.tipProgress:SetChecked(true); v.tipProgress.__scripts.OnClick(v.tipProgress)
    -- the Guide's rows sit above the Map's, and the Banking rows below everything else
    assert(v.guideOn.__points[1].y > v.pins.__points[1].y and v.pins.__points[1].y > v.glowOn.__points[1].y and v.modeBtns[1].__points[1].y < v.glowOn.__points[1].y, "top to bottom: Guide, Map, the light, Banking")
    -- the page is laid out with nothing clipped (the harness's layout pass covers Settings; this checks it here too)
    UI:Refresh()
    local lay = checkLayout(UI.frame, "settings after the regroup")
    assert(#lay == 0, "settings laid out: " .. table.concat(lay, "; "))
    STAGE_LAYOUTS[#STAGE_LAYOUTS + 1] = dumpLayout(UI.frame, "Settings, 6.0")
    -- the sidebar is untouched
    assert(UI.SIDEBAR[#UI.SIDEBAR].name == "Settings", "the sidebar as it was")
    UI.frame:Hide()
  end }

  for _, case in ipairs(G6CASES) do
    case[2]()
    print("6.0 guide: " .. case[1] .. ": ok")
  end
end)()

----------------------------------------------------------------------------
-- 5.4.2: memory, and the lag that grew through a session ("QuestBank made me lag towards the end, using 80 MB").
-- The trails' graph was built again from scratch at each point noted, inside the minimap's update (half a second at
-- 12,000 points, and megabytes of garbage each time); a re-plan made 15 MB of garbage; every frame's error wrapper,
-- the minimap's list and view, and each refresh's statuses made more; and the minimap's dungeon count turned every quest
-- of the catalog into a 34-field view at login. Measured here on a client of its own (the owner's twin), late in a
-- long session. Bytes are those QuestBank's own code allocates (ownBytes: a call and return hook charges each
-- allocation to the file of the function that made it, so the harness's mock client is left out), with the JIT off,
-- as the game runs Lua 5.1.
-- Memory kept is estimated from what is reachable from QB and QuestBankDB, in LuaJIT's layout (kept()).
----------------------------------------------------------------------------
;(function()
  local floor, sqrt = math.floor, math.sqrt
  local function ownBytes(fn)
    local getinfo, count = debug.getinfo, collectgarbage
    local acc, mine, last, mark = 0, false, 0, 0
    -- at a call, the function called runs now; at a return, its caller (a C function, string.format and the like,
    -- allocates for whoever called it)
    local function hook(ev)
      local now = count("count")
      if mine then acc = acc + (now - last) end
      local info = getinfo(ev == "call" and 2 or 3, "S")
      if info and info.what ~= "C" then mine = info.source:find("/QuestBank/", 1, true) ~= nil end
      -- (the hook's own tables pile up with the collector stopped: emptied now and then, between two counts)
      if count("count") - mark > 65536 then collectgarbage("collect"); collectgarbage("stop"); mark = count("count") end
      last = count("count")
    end
    if jit then jit.off(); jit.flush() end
    collectgarbage("collect"); collectgarbage("stop")
    last = count("count")
    mark = last
    debug.sethook(hook, "cr")
    fn()
    debug.sethook()
    collectgarbage("restart")
    if jit then jit.on() end
    return acc * 1024
  end
  local function full() collectgarbage("collect"); collectgarbage("collect"); return collectgarbage("count") end
  -- what a client's QuestBank keeps: everything reachable from QB and QuestBankDB (a widget counted as a small table,
  -- QuestBank's own fields on it followed; the upvalues of QuestBank's own functions followed, where its caches live)
  local function pow2(n) local p = 1; while p < n do p = p * 2 end; return p end
  local function kept(c, skip)
    collectgarbage("collect"); collectgarbage("collect") -- (a weak table's dead entries go first)
    local seen = { [c] = true, [c.env] = true, [BASE] = true, [_G] = true, [ALL] = true, [clients] = true, [c.frames] = true, [c.timers] = true }
    for _, x in ipairs(skip or {}) do seen[x] = true end
    local total, queue, qi = 0, { c.QB, c.env.QuestBankDB }, 1
    local function push(v)
      local tv = type(v)
      if tv == "string" then
        if not seen[v] then seen[v] = true; total = total + 17 + #v end
      elseif (tv == "table" or tv == "function") and not seen[v] then
        queue[#queue + 1] = v
      end
    end
    while qi <= #queue do
      local v = queue[qi]
      queue[qi], qi = false, qi + 1
      if v and not seen[v] then
        seen[v] = true
        if type(v) == "table" then
          if rawget(v, "__kind") and rawget(v, "__scripts") then
            total = total + 150
            for k, x in pairs(v) do if type(k) ~= "string" or not k:find("^__") then push(k); push(x) end end
            for _, s in pairs(rawget(v, "__scripts")) do push(s) end
          else
            local n, h = #v, 0
            for k in pairs(v) do if not (type(k) == "number" and k >= 1 and k <= n and k % 1 == 0) then h = h + 1 end end
            total = total + 64 + (n > 0 and pow2(n) * 8 or 0) + (h > 0 and pow2(h) * 24 or 0)
            local mt = debug.getmetatable(v)
            if type(mt) == "table" then push(mt) end
            for k, x in pairs(v) do push(k); push(x) end
          end
        else
          local info = debug.getinfo(v, "Su")
          total = total + 40 + 8 * (info.nups or 0)
          if info.source:find("/QuestBank/", 1, true) then
            for i = 1, info.nups or 0 do local _, x = debug.getupvalue(v, i); push(x) end
          end
        end
      end
    end
    return total / 1024
  end
  -- a deterministic walk (the client has no randomseed)
  local seed = 4242
  local function rand() seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648 end

  local mc = newClient({
    name = "Memo", level = 20, cap = 20, faction = "Alliance", className = "Paladin", class = "PALADIN", classID = 2, race = "Human",
    log = OWNER_LOG, world = { 0, -9460, 60 },
    done = { [96393] = true, [96394] = true, [96395] = true, [96403] = true, [98423] = true, [96391] = true, [6981] = true,
             [155] = true, [142] = true, [141] = true, [135] = true, [132] = true, [65] = true, [389] = true, [373] = true },
    bagSlots = { { 268540, 4 }, { 251522, 1 } },
  })
  local QB, env = mc.QB, mc.env
  c = mc
  mc.o.map = 1429
  env.IsInInstance = function() return false, "none" end
  local m0 = full()
  login(mc)
  env.SlashCmdList.QUESTBANK("")
  QB.Model.Finish()
  for t = 1, 9 do QB.UI:ShowTab(t) end
  QB.UI.frame:Hide()
  QB.Arrow:Set(true)
  mc.map:Close() -- (the game's world map shut, as it is while you play)

  -- 1. what is kept after login with every page opened. 5.4.1 kept 15.1 MB (LuaJIT; about 22 MB in the client's Lua
  -- 5.1): the quest views 7.2 MB of it, the catalog (Data.lua) 4.2 MB, the window 1.1 MB. 5.4.2 keeps about 9.3 MB:
  -- the catalog, the window and its widgets 2.6 MB, the quest views 0.85 MB, the maps' and flights' tables about 1 MB.
  -- The budget, 11 MB, leaves room to grow and fails if the views (6 MB more) come back whole
  local KEEP_BUDGET = 11 * 1024
  local afterLoad = kept(mc)
  print(string.format("memory: kept after login and every page %.0f KB (budget %d KB); the heap grew %.0f KB with the harness's widgets",
    afterLoad, KEEP_BUDGET, full() - m0))
  assert(afterLoad < KEEP_BUDGET, string.format("QuestBank keeps %.0f KB after login, over its budget of %d KB", afterLoad, KEEP_BUDGET))

  -- a late session's trails: 8,000 points (about seven hours on foot) round where you stand, noted before this session
  local Walk = QB.Walk
  local home = { mc.o.world[2], mc.o.world[3] }
  local function fill(n, box, keepOn)
    local x, y, h, cnt = home[1], home[2], 0, 0
    local W = Walk.DB()
    if not keepOn then W[0] = nil end
    while cnt < n do
      h = h + (rand() - 0.5) * 1.2
      local nx, ny = x + math.cos(h) * 16, y + math.sin(h) * 16
      if math.abs(nx - home[1]) > box or math.abs(ny - home[2]) > box then h = math.atan2(home[2] - y, home[1] - x) else x, y = nx, ny end
      if rand() < 0.003 then Walk.Note({ c = 0, wx = x + 4000, wy = y + 4000 }) end -- (a hearth now and then: a new trail)
      if Walk.Note({ c = 0, wx = x, wy = y }) then cnt = cnt + 1 end
    end
    return x, y
  end
  local function points() local n = 0; for _, t in ipairs(Walk.DB()[0] or {}) do n = n + #t / 2 end; return n end

  -- one frame of play: the clock, walking (a heading that wanders, kept within 1,500 yards of home), the timers due,
  -- every visible frame's OnUpdate
  local heading, turnAt, speed = 0, 0, 7
  local function frame(dt)
    mc.clock = mc.clock + dt
    if speed > 0 then
      if mc.clock >= turnAt then heading, turnAt = heading + (rand() - 0.5) * 2, mc.clock + 2 + rand() * 8 end
      local w = mc.o.world
      local nx, ny = w[2] + math.cos(heading) * speed * dt, w[3] + math.sin(heading) * speed * dt
      if math.abs(nx - home[1]) > 1500 or math.abs(ny - home[2]) > 1500 then heading = math.atan2(home[2] - w[3], home[1] - w[2])
      else w[2], w[3] = nx, ny end
    end
    table.sort(mc.timers, function(a, b) return a.t < b.t end)
    while mc.timers[1] and mc.timers[1].t <= mc.clock do table.remove(mc.timers, 1).f() end
    for _, f in ipairs(mc.frames) do
      local u = f.__scripts.OnUpdate
      if u and f:IsVisible() then u(f, dt) end
    end
  end

  fill(8000, 1500)
  for _ = 1, 200 do frame(0.05) end
  -- (the trails, their graph and the quest survey grow with play by design, bounded by their caps: weighed apart)
  local function sansTrails() return kept(mc, { Walk.G, Walk.DB() }) end
  local before, beforeAll, builds0 = sansTrails(), kept(mc), Walk.builds
  -- 2. a long session on those trails: twenty minutes walking, the quest log changing every
  -- 5 seconds, XP and the bags every 30, a hand-in every 7 minutes, the window opened on each page every 2 minutes
  local cycle = function()
    QB.UI:Open(1)
    for t = 2, 9 do QB.UI:ShowTab(t) end
    QB.UI.frame:Hide()
  end
  local sched = {
    { 5, function() mc.ev(QB.eventFrame, "QUEST_LOG_UPDATE") end },
    { 30, function() mc.xp = (mc.xp or 0) + 250; mc.ev(QB.eventFrame, "PLAYER_XP_UPDATE", "player") end },
    { 30, function() mc.ev(QB.eventFrame, "BAG_UPDATE_DELAYED") end },
    { 420, function()
        for i, e in ipairs(mc.log) do
          if e[2] == 1 then
            table.remove(mc.log, i); mc.done[e[1]] = true
            mc.ev(QB.eventFrame, "QUEST_TURNED_IN", e[1], 1150, 0); mc.ev(QB.eventFrame, "QUEST_LOG_UPDATE")
            break
          end
        end
      end },
    { 120, function() if cycle then cycle() end end },
    { 60, function() mc.outbox, mc.chat, mc.said = {}, {}, {} end },
  }
  for _, s in ipairs(sched) do s.next = mc.clock + s[1] end
  local function play(seconds, fps)
    fps = fps or 20
    for _ = 1, seconds * fps do
      frame(1 / fps)
      for _, s in ipairs(sched) do if mc.clock >= s.next then s.next = s.next + s[1]; s[2]() end end
    end
  end
  local p0 = points()
  play(20 * 60, 10) -- (at 10 frames a second: the minimap places its pins at most 20 times a second anyway)
  local after, afterAll = sansTrails(), kept(mc)
  -- QuestBank's own garbage late in the session: ten seconds of play (the window shut) and one look through the
  -- window's pages, a minute of play counting the pages' share of their 2 minutes
  local pages = cycle
  cycle = nil
  local walk = ownBytes(function() play(10) end) * 6
  local look = ownBytes(pages)
  local perMinute = walk + look / 2
  print(string.format("a long session: %d trail points (+%d); kept %.0f KB before and %.0f KB after (%+.1f%%), %.0f and %.0f KB with the trails; garbage late in it %.0f KB a minute (%.0f playing, %.0f a look through the pages); graphs built whole %d",
    points(), points() - p0, before, after, (after - before) / before * 100, beforeAll, afterAll, perMinute / 1024, walk / 1024, look / 1024, Walk.builds - builds0))
  -- 5.4.1 made 27 to 44 MB of garbage a minute walking (mock left out), 60 MB a minute at 8,000 points
  assert(perMinute < 3 * 1024 * 1024, string.format("late in a session QuestBank makes %.0f KB of garbage a minute (at most 3 MB)", perMinute / 1024))
  assert(after < before * 1.05, string.format("a long session grows what is kept by %.1f%% (at most 5%%, the trails aside)", (after - before) / before * 100))
  assert(afterAll - after < 2048 and afterAll < beforeAll * 1.15, string.format("the trails' graph at %d points: %.0f KB (at most 2 MB)", points(), afterAll - after))
  assert(Walk.builds == builds0 and points() > p0 + 300, "the trails' graph grew point by point: never built whole while walking")

  -- 3. every frame, standing still with nothing changing: each OnUpdate that always runs (the minimap's, the arrow's,
  -- the trails', the camp bar's) allocates next to nothing. 5.4.1: 2.3 KB a frame on the minimap's, 565 B on the
  -- arrow's, about 260 B on the others (the error wrapper alone)
  speed = 0
  for _ = 1, 40 do frame(0.05) end
  QB.Mini.Invalidate(); QB.Mini.Place() -- (the list made now: its 30-second safety net does not fall in the count)
  local IDLE_MAX = 64 -- bytes a call
  local measured = {}
  local runners = {}
  for _, f in ipairs(mc.frames) do
    local u = f.__scripts.OnUpdate
    if u and f:IsVisible() then runners[#runners + 1] = f end
  end
  for _, f in ipairs(runners) do
    local u = f.__scripts.OnUpdate
    local per = ownBytes(function()
      for _ = 1, 120 do mc.clock = mc.clock + 1 / 60; u(f, 1 / 60) end
    end) / 120
    measured[#measured + 1] = string.format("%s %.0f", f.__name == "QuestBankMinimap" and "minimap" or f == QB.Arrow.frame and "arrow"
      or f == QB.Walk.frame and "trails" or f == QB.Camp.frame and "camp" or tostring(f.__where), per)
  end
  for i, f in ipairs(runners) do
    local per = tonumber(measured[i]:match("(%S+)$"))
    assert(per < IDLE_MAX, string.format("an OnUpdate allocates %.0f bytes a frame standing still (at most %d): %s", per, IDLE_MAX, table.concat(measured, ", ")))
  end
  assert(#runners >= 4, "the minimap's, the arrow's, the trails' and the camp bar's OnUpdate run: " .. #runners)
  -- the wrapper that keeps errors out of the game's way (QB.Safe): no table or closure a call any more, the arguments
  -- in upvalues, exactly as many as given (an event handler counts them), and a call within a call its own
  for n = 0, 8 do
    local got, args = nil, {}
    local f = QB.Safe(function(...) got = select("#", ...) end, "harness")
    for i = 1, n do args[i] = (i % 3 ~= 0) and i or nil end
    f(unpack(args, 1, n))
    assert(got == n, "QB.Safe passes " .. n .. " arguments as " .. tostring(got))
  end
  local depth, inner = 0, nil
  inner = QB.Safe(function(k, word)
    depth = depth + 1
    if k < 3 then inner(k + 1, "w" .. (k + 1)) end
    assert(word == "w" .. k, "a call's arguments stay its own after a call within it")
  end, "harness")
  inner(1, "w1")
  local quiet = QB.Safe(function(self, dt) return self, dt end, "harness")
  local safeBytes = ownBytes(function() for _ = 1, 100 do quiet(mc, 0.016) end end) / 100
  assert(depth == 3 and safeBytes < 8, string.format("QB.Safe: a call within a call, and %.0f bytes a call", safeBytes))
  -- and walking: the minimap follows you, the golden path is trimmed behind you and searched again now and then
  speed = 7
  local walking = ownBytes(function() for _ = 1, 240 do frame(1 / 60) end end) / 240
  print(string.format("every frame: standing still, bytes a call: %s; walking, all of them %.0f bytes a frame", table.concat(measured, ", "), walking))
  assert(walking < 512, string.format("walking, QuestBank allocates %.0f bytes a frame (at most 512)", walking))

  -- 4. the trails' graph against 5.4.1's search, kept here as it was: the same ways on a fixed set of trips, a point
  -- noted and a search at 12,000 points cheap, and the cap cutting one long trail in one pass
  local function refGraph(trails)
    local CELL, JOIN = 250, 25
    local function cell(x, y) return floor(x / CELL) .. ":" .. floor(y / CELL) end
    local nodes, byCell = {}, {}
    for ti, t in ipairs(trails) do
      for i = 1, #t - 1, 2 do
        local id = #nodes + 1
        nodes[id] = { x = t[i], y = t[i + 1], adj = {}, t = ti }
        if i > 1 then local prev = id - 1; nodes[id].adj[#nodes[id].adj + 1] = prev; nodes[prev].adj[#nodes[prev].adj + 1] = id end
        local k = cell(t[i], t[i + 1])
        byCell[k] = byCell[k] or {}
        byCell[k][#byCell[k] + 1] = id
      end
    end
    for id, nd in ipairs(nodes) do
      local cx, cy = floor(nd.x / CELL), floor(nd.y / CELL)
      for bx = cx - 1, cx + 1 do
        for by = cy - 1, cy + 1 do
          for _, other in ipairs(byCell[bx .. ":" .. by] or {}) do
            local o = nodes[other]
            if other ~= id and o.t ~= nd.t and (o.x - nd.x) ^ 2 + (o.y - nd.y) ^ 2 <= JOIN * JOIN then nd.adj[#nd.adj + 1] = other end
          end
        end
      end
    end
    return nodes
  end
  local function refPath(N, from, to)
    local REACH, MAX_NODES = 80, 6000
    local function nearest(wx, wy)
      local best, bd = nil, REACH * REACH
      for id, nd in ipairs(N) do
        local d = (nd.x - wx) ^ 2 + (nd.y - wy) ^ 2
        if d < bd then best, bd = id, d end
      end
      return best
    end
    local a, b = nearest(from.wx, from.wy), nearest(to.wx, to.wy)
    if not a or not b then return nil end
    if a == b then return { { from.wx, from.wy }, { N[a].x, N[a].y }, { to.wx, to.wy } } end
    local open, g, came, closed = { [a] = true }, { [a] = 0 }, {}, {}
    local function h(id) return sqrt((N[id].x - N[b].x) ^ 2 + (N[id].y - N[b].y) ^ 2) end
    local f = { [a] = h(a) }
    local explored = 0
    while next(open) do
      local cur, best
      for id in pairs(open) do if not best or f[id] < best then cur, best = id, f[id] end end
      if cur == b then break end
      open[cur] = nil; closed[cur] = true
      explored = explored + 1
      if explored > MAX_NODES then return nil end
      for _, nb in ipairs(N[cur].adj) do
        if not closed[nb] then
          local ng = g[cur] + sqrt((N[nb].x - N[cur].x) ^ 2 + (N[nb].y - N[cur].y) ^ 2)
          if g[nb] == nil or ng < g[nb] then g[nb], came[nb], f[nb] = ng, cur, ng + h(nb); open[nb] = true end
        end
      end
    end
    if not came[b] then return nil end
    local out = { { to.wx, to.wy } }
    local cur = b
    while cur do out[#out + 1] = { N[cur].x, N[cur].y }; cur = came[cur] end
    out[#out + 1] = { from.wx, from.wy }
    for i = 1, floor(#out / 2) do out[i], out[#out + 1 - i] = out[#out + 1 - i], out[i] end
    local function same(p, q) return math.abs(p[1] - q[1]) + math.abs(p[2] - q[2]) < 2 end
    if #out > 2 and same(out[1], out[2]) then table.remove(out, 2) end
    if #out > 2 and same(out[#out], out[#out - 1]) then table.remove(out, #out - 1) end
    return out
  end
  local function length(p) local s = 0; for i = 2, #p do s = s + sqrt((p[i][1] - p[i - 1][1]) ^ 2 + (p[i][2] - p[i - 1][2]) ^ 2) end; return s end
  local function compare(trips)
    local N = refGraph(Walk.DB()[0])
    local tr = Walk.DB()[0]
    local samePts, sameLen, none = 0, 0, 0
    for _ = 1, trips do
      local function spot()
        if rand() < 0.15 then return { wx = home[1] + (rand() - 0.5) * 3400, wy = home[2] + (rand() - 0.5) * 3400 } end
        local t = tr[1 + floor(rand() * #tr)]
        local i = 1 + 2 * floor(rand() * (#t / 2))
        return { wx = t[i] + (rand() - 0.5) * 60, wy = t[i + 1] + (rand() - 0.5) * 60 }
      end
      local from, to = spot(), spot()
      local want, got = refPath(N, from, to), Walk.Path(0, from, to)
      assert((want == nil) == (got == nil), "a way found by one search and not by the other")
      if not want then
        none = none + 1
      else
        local same = #want == #got
        for i = 1, same and #want or 0 do if want[i][1] ~= got[i][1] or want[i][2] ~= got[i][2] then same = false end end
        if same then samePts = samePts + 1 else
          assert(math.abs(length(want) - length(got)) < 1e-6, "a way as long as 5.4.1's (an equal one where two tie)")
          sameLen = sameLen + 1
        end
      end
    end
    return samePts, sameLen, none
  end
  speed = 0
  fill(3000, 1200)
  local a1, b1, n1 = compare(150)
  fill(12000, 1500)
  -- the cap: past 12,000 points the oldest trails go
  local p1 = points()
  for _ = 1, 400 do
    local x, y = home[1] + (rand() - 0.5) * 2000, home[2] + (rand() - 0.5) * 2000
    Walk.Note({ c = 0, wx = x, wy = y }); Walk.Note({ c = 0, wx = x + 16, wy = y })
  end
  assert(points() <= Walk.MAX_POINTS and points() > Walk.MAX_POINTS - 1000, "the cap holds: " .. points() .. " points, from " .. p1)
  local a2, b2, n2 = compare(40)
  print(string.format("trails: the ways of 5.4.1's search: %d trips the same point for point, %d as long (a tie), %d with no way; at 12,000 points %d, %d, %d",
    a1, b1, n1, a2, b2, n2))
  assert(a1 + b1 >= 30 and a2 + b2 >= 10, "trips enough with a way to compare")
  -- a point noted and a search, at 12,000 points: no graph built again, a few kilobytes (the way found) and a fraction
  -- of 5.4.1's build alone (its search built the whole graph again after every point: 0.5 s at 12,000 under Lua 5.4)
  local W = Walk.DB()
  -- on the end of the longest trail, going on along it; the goal 100 points back on it
  local tr = W[0][1]
  for _, t in ipairs(W[0]) do if #t > #tr then tr = t end end
  assert(#tr >= 240, "a trail of 120 points at least: " .. #tr / 2)
  local goal = { tr[#tr - 201], tr[#tr - 200] }
  local gx, gy = tr[#tr - 1], tr[#tr]
  Walk.Note({ c = 0, wx = home[1] + 9000, wy = home[2] + 9000 }); Walk.Note({ c = 0, wx = gx, wy = gy }) -- (back on it)
  Walk.Path(0, { wx = gx, wy = gy }, { wx = goal[1], wy = goal[2] })
  local builds1 = Walk.builds
  local reps, found = 10, 0
  local bytes = ownBytes(function()
    for i = 1, reps do
      Walk.Note({ c = 0, wx = gx + 16 * i, wy = gy })
      if Walk.Path(0, { wx = gx + 16 * i, wy = gy }, { wx = goal[1], wy = goal[2] }) then found = found + 1 end
    end
  end) / reps
  assert(found == reps, "the way back along the trail found each time: " .. found)
  local t1 = os.clock()
  for i = reps + 1, reps * 2 do
    Walk.Note({ c = 0, wx = gx + 16 * i, wy = gy })
    Walk.Path(0, { wx = gx + 16 * i, wy = gy }, { wx = goal[1], wy = goal[2] })
  end
  local per = (os.clock() - t1) / reps
  local r0 = os.clock()
  refGraph(W[0])
  local refBuild = os.clock() - r0
  print(string.format("trails at %d points: a point and a search %.2f ms, %.1f KB; 5.4.1 built its graph in %.0f ms",
    points(), per * 1000, bytes / 1024, refBuild * 1000))
  assert(Walk.builds == builds1, "a point noted grows the graph; nothing is built again")
  assert(bytes < 20 * 1024, string.format("a point and a search allocate %.1f KB (at most 20)", bytes / 1024))
  assert(per < refBuild / 20, "a point and a search cost a small part of what building the graph cost")
  -- the trails drawn round you: a few hundred bytes at 12,000 points (5.4.1: 5 to 18 KB a call, 20 a second)
  Walk.Near(0, home[1], home[2], 400)
  local near = ownBytes(function() for _ = 1, 20 do Walk.Near(0, home[1], home[2], 400) end end) / 20
  assert(near < 1024 and #Walk.Near(0, home[1], home[2], 400) > 20, string.format("the trails near you: %.0f bytes a call (at most 1 KB)", near))
  -- one trail longer than the cap loses its oldest half in one pass (5.4.1 moved the array once for every number:
  -- seconds)
  W[0] = nil
  Walk.Note({ c = 0, wx = home[1] + 9000, wy = home[2] + 9000 }) -- (a jump: what follows is a trail of its own)
  W[0] = nil
  for i = 1, 12000 do Walk.Note({ c = 0, wx = home[1] + i * 15, wy = home[2] }) end
  assert(#W[0] == 1 and #W[0][1] == 24000, "one trail of 12,000 points")
  local cut0 = os.clock()
  Walk.Note({ c = 0, wx = home[1] + 12001 * 15, wy = home[2] })
  local cutMs = (os.clock() - cut0) * 1000
  local t = W[0][#W[0]]
  assert(#W[0] == 1 and #t / 2 == 6001 and t[#t - 1] == home[1] + 12001 * 15 and t[1] == home[1] + 6001 * 15 and cutMs < 50,
    string.format("one trail past the cap keeps its newest half, cut in %.1f ms: %d points from x %s", cutMs, #t / 2, tostring(t[1])))
  W[0] = nil

  -- 5. the golden path drawn: only the pieces round you are cut to the minimap (the rest cannot show), the same pieces
  -- drawn as cutting all of them
  fill(8000, 1500)
  local MR, GP, MV = QB.MiniRoute, QB.MiniRoute.GP, QB.MiniView
  MR.Frames()
  local trs = Walk.DB()[0]
  local tA = trs[#trs]
  local px, py = tA[#tA - 1], tA[#tA]
  local ptx, pty = tA[math.max(1, #tA - 801)], tA[math.max(2, #tA - 800)]
  GP.c = nil
  assert(GP.Update(0, px, py, ptx, pty) and GP.np > 100, "a long way along the trails: " .. tostring(GP.np) .. " pieces")
  for _, view in ipairs({ { radius = 200, facing = 0, square = false }, { radius = 260, facing = 1.1, square = true }, { radius = 120, facing = -2, square = false },
                          { radius = 900, facing = 0.4, square = false } }) do
    local v = { c = 0, wx = px, wy = py, radius = view.radius, R = 70, scale = 70 / view.radius, cs = math.cos(view.facing), sn = math.sin(view.facing),
                facing = view.facing, square = view.square }
    local calls, realLine = 0, MR.Line
    MR.Line = function(...) calls = calls + 1; return realLine(...) end
    local shown = MR.DrawGold(v)
    MR.Line = realLine
    local r, want = v.R - GP.Thickness() / 2 - 1, 0
    -- (zoomed far out, a piece under 4 pixels, the way's own stretches are drawn instead)
    local whole = GP.Spacing() * v.scale < 4
    -- (5.4.4: the pieces round your arrow give way to its gap, MR.YOU pixels)
    local sx, sy = MV.Point(v, GP.dx[1], GP.dy[1])
    for k = 1, whole and GP.dn - 1 or GP.np do
      local x1, y1 = MV.Point(v, whole and GP.dx[k] or GP.ax[k], whole and GP.dy[k] or GP.ay[k])
      local x2, y2 = MV.Point(v, whole and GP.dx[k + 1] or GP.bx[k], whole and GP.dy[k + 1] or GP.by[k])
      x1, y1, x2, y2 = MR.Outside(x1, y1, x2, y2, sx, sy, MR.YOU, false)
      local u1, w1, u2, w2
      if x1 then u1, w1, u2, w2 = MR.Clip(x1, y1, x2, y2, r, v.square) end
      if u1 and (u2 - u1) ^ 2 + (w2 - w1) ^ 2 > 0.25 then want = want + 1 end
    end
    assert(shown == want and shown > 0 and calls < 100, string.format("the golden path: %d pieces drawn of %d (as cutting all: %d), %d cut", shown, GP.np, want, calls))
  end

  -- 6. a re-plan: under 1 MB of garbage (5.4.1: 14.9 MB, a new table for every order tried), and a plan made twice
  -- from the same quests the same (the search's arrays are reused from one order to the next)
  local function routeKey(r)
    local t = {}
    for _, l in ipairs(r.legs) do
      t[#t + 1] = l.stop.name
      for _, row in ipairs(l.rows) do t[#t + 1] = row.q.id .. "=" .. row.xp end
    end
    return table.concat(t, ",") .. string.format(" %.6f %.4f", r.level, r.t)
  end
  QB.Model.Finish()
  -- (both routes planned again: their signatures forgotten. 5.4.4's signature no longer counts QB.liveVer, the XP the
  -- game reported for any quest, only each route quest's own)
  local plan = ownBytes(function() QB.sigNow, QB.sigPlan, QB.pending = nil, nil, nil; QB:Recompute(true) end)
  local entries = QB:RouteEntries("plan")
  local opts = { level = QB.state.level, xp = QB.state.xp, goal = "hour", fac = QB.faction }
  local first, again = QB.Model.Plan(entries, opts), QB.Model.Plan(entries, opts)
  assert(#first.legs > 3 and routeKey(first) == routeKey(again), "the same quests planned twice: the same route")
  print(string.format("a re-plan of both routes: %.0f KB of garbage", plan / 1024))
  assert(plan < 1024 * 1024, string.format("a re-plan made %.0f KB of garbage (at most 1 MB)", plan / 1024))

  -- 6.0: the Guide. A Replan with nothing changed makes under 64 KB (its steps are pooled, its texts made on demand);
  -- a tick of the step frame with nothing changed makes nothing; the Guide on for the twin changes neither of the two
  -- gates below by more than their budgets allow (they run with it on from here)
  QB:Settings().guide.on, QB:Settings().guide.frame, QB:Settings().welcome = true, true, nil
  QB.Guide.Replan()
  QB.StepFrame.Apply(); QB.StepFrame.Refresh()
  QB.Guide.Replan()
  local replan = ownBytes(function() QB.Guide.Replan() end)
  print(string.format("the Guide: a re-plan of the steps %.0f KB of garbage", replan / 1024))
  assert(replan < 64 * 1024, string.format("the Guide's Replan made %.0f KB (at most 64)", replan / 1024))
  local sfr = QB.StepFrame.frame
  assert(sfr and sfr:IsShown() and sfr.now:GetText() ~= "", "the step frame is up on the twin with a step: " .. tostring(sfr and sfr.now:GetText()))
  sfr.elapsed = 1; sfr.__scripts.OnUpdate(sfr, 0.016)
  local ticks = ownBytes(function() for _ = 1, 100 do sfr.elapsed = 1; sfr.__scripts.OnUpdate(sfr, 0.016) end end)
  print(string.format("the step frame: 100 ticks with nothing changed %.0f bytes", ticks))
  assert(ticks < 2048, string.format("the step frame's tick allocates: %.0f bytes over 100 ticks", ticks))
  -- the same gate grouped (6.0.0's review: a member's step made a list, a row and a key string a tick, ~130 bytes of
  -- QuestBank's own): a party of two, each seeing the other's step, then 100 ticks with nothing changed
  do
    local ga = newClient({ name = "Rone", level = 3, cap = 60, faction = "Alliance", className = "Warrior", class = "WARRIOR", classID = 1, race = "Human",
      log = { { 7, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    local gb = newClient({ name = "Brann", level = 3, cap = 60, faction = "Alliance", className = "Paladin", class = "PALADIN", classID = 2, race = "Human",
      log = { { 7, 0 }, { 15, 0 } }, done = { [783] = true }, group = true, world = { 0, -8914, -133 }, map = 1429, bagSlots = {}, bind = "Goldshire" })
    login(ga); login(gb)
    local function settleG(c)
      c.ev(c.QB.eventFrame, "QUEST_LOG_UPDATE")
      tick(c, 0.5)
      c.QB.Model.Finish(); c.QB:Recompute(true); c.QB.Model.Finish()
      tick(c, 0.3)
      c.QB.Guide.Replan()
    end
    for _, c in ipairs({ ga, gb }) do c.QB:Settings().guide.on = true; c.QB:Settings().welcome = nil end
    settleG(ga); settleG(gb)
    ga.QB.Sync:Broadcast(true); gb.QB.Sync:Broadcast(true)
    for _ = 1, 3 do tick(ga, 2); tick(gb, 2); deliver() end
    settleG(ga); settleG(gb)
    for _ = 1, 3 do tick(ga, 2); tick(gb, 2); deliver() end
    ga.QB.StepFrame.Apply(); ga.QB.StepFrame.Refresh()
    local gf = ga.env.QuestBankStep
    assert(#ga.QB.Guide.MemberSteps() == 1 and gf.members[1] and gf.members[1]:IsShown() and gf.members[1]:GetText():find("Brann", 1, true),
      "the grouped frame shows Brann's step: " .. tostring(gf.members[1] and gf.members[1]:GetText()))
    gf.elapsed = 1; gf.__scripts.OnUpdate(gf, 0.016)
    local gticks = ownBytes(function() for _ = 1, 100 do gf.elapsed = 1; gf.__scripts.OnUpdate(gf, 0.016) end end)
    print(string.format("the step frame, grouped: 100 ticks with nothing changed %.0f bytes", gticks))
    assert(gticks < 2048, string.format("the grouped step frame's tick allocates: %.0f bytes over 100 ticks", gticks))
  end

  -- 7. a refresh with the window shut and nothing changed (QUEST_LOG_UPDATE fires all the time while questing): the
  -- same window afterwards, and a few tens of kilobytes (5.4.1: about 400 KB, statuses, item lists and strings anew)
  QB:Changed()
  local function texts()
    local out = {}
    for _, o in ipairs(ALL) do
      if o.__kind == "FontString" and o.__text ~= "" then
        local p, vis, mine = o, true, false
        while p do
          if not p.__shown then vis = false break end
          if p == QB.UI.frame then mine = true end
          p = p.__parent
        end
        if vis and mine then out[#out + 1] = o.__text end
      end
    end
    return table.concat(out, "\n")
  end
  QB.UI:Open(3)
  local page = texts()
  QB.UI.frame:Hide()
  local refresh = ownBytes(function() QB:Changed(); QB:Changed() end) / 2
  QB.UI:Open(3)
  assert(texts() == page, "the Hand-in Route reads the same after two refreshes")
  QB.UI.frame:Hide()
  print(string.format("a refresh, the window shut: %.0f KB of garbage", refresh / 1024))
  assert(refresh < 100 * 1024, string.format("a refresh with nothing changed made %.0f KB of garbage (at most 100)", refresh / 1024))

  -- 8. the saved runs that grew without end: the newest 20, at login and as each run stops; the hand-ins are kept
  -- whole (the site's upload merge counts a hand-in's own reading once only while the hand-in is in the list)
  local db = env.QuestBankDB
  local list = {}
  for i = 1, 600 do list[i] = { id = 100000 + i, xp = 10, at = tostring(i) } end
  db.turnins = list
  db.runs = {}
  for i = 1, 25 do db.runs[i] = { started = i } end
  QB.PruneLogs(db)
  assert(#db.turnins == 600 and #db.runs == QB.MAX_RUNS and db.runs[1].started == 6 and db.runs[20].started == 25,
    "every hand-in kept, the newest 20 runs")
  mc.ev(QB.eventFrame, "QUEST_TURNED_IN", 7, 0, 0)
  assert(#db.turnins == 601 and db.turnins[601].id == 7, "a hand-in in: nothing out")
  -- a run stopped with 20 saved: still 20, the newest last
  QB.Run.Start()
  QB.Run.Stop()
  assert(#db.runs == QB.MAX_RUNS and db.runs[1].started == 7 and db.runs[QB.MAX_RUNS].ended ~= nil, "a run stopped: the oldest out, the newest last")

  -- 9. the quest views: each field as 5.4.1 made it, worked out when read; the whole catalog's views in a fraction
  -- of the memory (5.4.1 built all 3,934 at login: about 7 MB)
  local D, Q = QB.Data, QB.Quest
  local function npcView(i)
    local n = i and i > 0 and D.NPC[i]
    if not n then return nil end
    return { n = n[1], m = n[2], x = n[3], y = n[4], inside = n[5] < 0, place = n[12], idx = i }
  end
  local function eager(id) -- 5.4.1's Q.Get, as it was
    local r = D.Q[id]
    local turnIdx = r[6]
    if D.TURNH and D.TURNH[id] and (QB.faction or QB.API.Faction()) == "H" then turnIdx = D.TURNH[id] end
    local c = { id = id, name = D.QN[id] or ("Quest " .. id), lvl = r[1], req = r[2], side = r[3], base = r[4], mult = r[5],
          turnIdx = turnIdx, giveIdx = r[7], turn = npcView(turnIdx), give = npcView(r[7]), cat = D.CAT[r[8]], cls = r[9],
          flags = r[10], pre = D.PRE[id], tip = D.TIPS[id], bag = D.BAGQ[id], follow = D.FOLLOW[id],
          race = D.RACE[id], excl = D.EXCL[id], nextSteps = D.NEXT[id] }
    c.dungeon = c.flags % 2 == 1
    c.group = floor(c.flags / 2) % 2 == 1
    c.unconfirmed = floor(c.flags / 8) % 2 == 1
    c.classic = floor(c.flags / 16) % 2 == 1
    c.dungeonMult = floor(c.flags / 32) % 2 == 1
    c.xpUnknown = floor(c.flags / 64) % 2 == 1
    c.sodLeftover = floor(c.flags / 128) % 2 == 1
    c.nerfed = floor(c.flags / 256) % 2 == 1
    c.confirmed = floor(c.flags / 512) % 2 == 1
    c.wanted = floor(c.flags / 1024) % 2 == 1
    c.escort = floor(c.flags / 2048) % 2 == 1
    c.repeatable = floor(c.flags / 4096) % 2 == 1
    c.near = floor(c.flags / 8192) % 2 == 1
    c.seenOnly = floor(c.flags / 16384) % 2 == 1
    c.reqStated = floor(c.flags / 32768) % 2 == 1
    c.surveyOnly = floor(c.flags / 65536) % 2 == 1
    c.turnIn = floor(c.flags / 131072) % 2 == 1
    c.note = D.NOTE and D.NOTE[id]
    c.icon = D.QICON[id] or (c.bag and c.bag[3] ~= 2 and QB.API.ItemIcon(c.bag[1])) or QB.API.ItemIcon(D.QITEM[id])
      or (c.cat and c.cat.icon) or D.TEX.questGeneric
    return c
  end
  local fields = {}
  for k in pairs(Q.FIELDS) do fields[#fields + 1] = k end
  local ids = {}
  for id in pairs(D.Q) do ids[#ids + 1] = id end
  table.sort(ids)
  local compared = 0
  for _, id in ipairs(ids) do
    local want, got = eager(id), Q.Get(id)
    for k in pairs(want) do assert(Q.FIELDS[k] or k == "id", "a field 5.4.1 had and 5.4.2 does not work out: " .. k) end
    for _, k in ipairs(fields) do
      local a, b = want[k], got[k]
      if type(a) == "table" and a.idx then
        assert(type(b) == "table", "quest " .. id .. "." .. k)
        for kk, vv in pairs(a) do assert(b[kk] == vv, "quest " .. id .. "." .. k .. "." .. kk) end
      else
        assert(a == b, string.format("quest %d.%s: %s, as read through the view %s", id, k, tostring(a), tostring(b)))
      end
      compared = compared + 1
    end
  end
  -- the memory: the catalog's views as the minimap's dungeon count makes them at login, against 5.4.1's whole ones
  for _, id in ipairs(ids) do Q.Forget(id) end
  local v0 = full()
  QB.changed = QB.changed + 1
  QB.DMap.Progress()
  local v1 = full()
  local whole = {}
  for _, id in ipairs(ids) do whole[id] = eager(id) end
  local v2 = full()
  whole = nil
  print(string.format("quest views: %d fields of %d quests as 5.4.1's; the catalog's views at login %.0f KB, 5.4.1's %.0f KB", compared, #ids, v1 - v0, v2 - v1))
  assert(v1 - v0 < (v2 - v1) - 4096, "the views at login take at least 4 MB less than 5.4.1's")
  c = owner
end)()

local seen = {}
local unique = {}
for _, p in ipairs(problems) do if not seen[p] then seen[p] = true; unique[#unique + 1] = p end end
print("layout problems:", #unique)
for i = 1, math.min(80, #unique) do print("  " .. unique[i]) end
if LAYOUT_OUT then
  local f = assert(io.open(LAYOUT_OUT, "w"))
  f:write(json(layouts))
  f:close()
  print("layout written to " .. LAYOUT_OUT)
end
print(#unique == 0 and "OK" or "OK, with layout problems above")
